@dataclass(frozen=True)
class _DoctorChannelDmPolicy:
    policy: str
    allow_from: list[str]
    policy_path: str
    allow_from_path: str


def _doctor_channel_label(channel_id: str) -> str:
    normalized = _normalize_openclaw_channel_plugin_id(channel_id) or channel_id.strip().lower()
    if normalized in _DOCTOR_CHANNEL_LABELS:
        return _DOCTOR_CHANNEL_LABELS[normalized]
    words = normalized.replace("-", " ").replace("_", " ").split()
    return " ".join(word.capitalize() for word in words) or channel_id


def _doctor_channel_enabled(
    *,
    channel_config: dict[str, object],
    account_config: dict[str, object],
) -> bool:
    if channel_config.get("enabled") is False or account_config.get("enabled") is False:
        return False
    return True


def _doctor_channel_secret_configured(value: object) -> bool:
    if _optional_cli_string(value) is not None:
        return True
    if not isinstance(value, dict):
        return False
    if _optional_cli_string(value.get("id")) is not None and _optional_cli_string(
        value.get("source")
    ) is not None:
        return True
    return any(_doctor_channel_secret_configured(child) for child in value.values())


def _doctor_channel_has_runtime_config(config: dict[str, object]) -> bool:
    for key in _DOCTOR_CHANNEL_CREDENTIAL_KEYS:
        if key in config and _doctor_channel_secret_configured(config.get(key)):
            return True
    return False


def _doctor_channel_configured(
    *,
    channel_config: dict[str, object],
    account_config: dict[str, object],
) -> bool:
    account_configured = account_config.get("configured")
    if isinstance(account_configured, bool):
        return account_configured
    channel_configured = channel_config.get("configured")
    if isinstance(channel_configured, bool):
        return channel_configured
    return _doctor_channel_has_runtime_config(account_config) or _doctor_channel_has_runtime_config(
        channel_config
    )


def _doctor_channel_default_account(
    channel_config: dict[str, object],
) -> tuple[str | None, dict[str, object]]:
    accounts = _dict_config(channel_config.get("accounts"))
    if not accounts:
        return None, channel_config
    configured_default = _optional_cli_string(channel_config.get("defaultAccountId"))
    if configured_default is not None and configured_default in accounts:
        return configured_default, _dict_config(accounts.get(configured_default))
    if DEFAULT_ACCOUNT_ID in accounts:
        return DEFAULT_ACCOUNT_ID, _dict_config(accounts.get(DEFAULT_ACCOUNT_ID))
    account_id = next(iter(accounts))
    return str(account_id), _dict_config(accounts.get(account_id))


def _doctor_dm_list(value: object) -> list[str]:
    if not isinstance(value, list):
        return []
    entries: list[str] = []
    for item in value:
        entry = str(item).strip()
        if entry:
            entries.append(entry)
    return entries


def _doctor_dm_field(
    config: dict[str, object],
    *,
    prefix: str,
    policy_only: bool = False,
) -> tuple[str | None, list[str] | None, str | None, str | None]:
    policy = _optional_cli_string(config.get("dmPolicy"))
    allow_from = _doctor_dm_list(config.get("allowFrom"))
    if policy is not None or (allow_from and not policy_only):
        return (
            policy,
            allow_from if allow_from else None,
            f"{prefix}.dmPolicy" if policy is not None else None,
            f"{prefix}.",
        )
    dm = _dict_config(config.get("dm"))
    nested_policy = _optional_cli_string(dm.get("policy"))
    nested_allow_from = _doctor_dm_list(dm.get("allowFrom"))
    if nested_policy is not None or (nested_allow_from and not policy_only):
        return (
            nested_policy,
            nested_allow_from if nested_allow_from else None,
            f"{prefix}.dm.policy" if nested_policy is not None else None,
            f"{prefix}.dm.",
        )
    return None, None, None, None


def _doctor_security_resolve_dm_policy(
    *,
    channel_id: str,
    channel_config: dict[str, object],
    account_id: str | None,
    account_config: dict[str, object],
) -> _DoctorChannelDmPolicy:
    root_prefix = f"channels.{channel_id}"
    account_prefix = (
        f"{root_prefix}.accounts.{account_id}" if account_id is not None else root_prefix
    )
    field_sources: list[tuple[dict[str, object], str]] = []
    if account_id is not None:
        field_sources.append((account_config, account_prefix))
    field_sources.append((channel_config, root_prefix))

    allow_from: list[str] | None = None
    allow_from_path: str | None = None
    for config, prefix in field_sources:
        policy, source_allow_from, policy_path, source_allow_from_path = _doctor_dm_field(
            config,
            prefix=prefix,
        )
        if source_allow_from is not None and allow_from is None:
            allow_from = source_allow_from
            allow_from_path = source_allow_from_path
        if policy is not None:
            return _DoctorChannelDmPolicy(
                policy=policy,
                allow_from=allow_from or [],
                policy_path=policy_path or f"{prefix}.dmPolicy",
                allow_from_path=source_allow_from_path or f"{prefix}.",
            )

    default_prefix = account_prefix if account_id is not None else root_prefix
    return _DoctorChannelDmPolicy(
        policy="pairing",
        allow_from=allow_from or [],
        policy_path=f"{default_prefix}.dmPolicy",
        allow_from_path=allow_from_path or f"{default_prefix}.",
    )


def _doctor_dm_allow_state(
    *,
    channel_id: str,
    account_id: str | None,
    allow_from: list[str],
    data_dir: Path | None,
) -> tuple[bool, int, bool]:
    has_wildcard = any(entry.strip() == "*" for entry in allow_from)
    normalized = _normalize_allowlist_entries(allow_from)
    store_entries = _read_channel_allow_from_store(
        channel_id,
        account_id=account_id,
        data_dir=data_dir,
    )
    allow_count = len({*normalized, *store_entries})
    return has_wildcard, allow_count, has_wildcard or allow_count > 1


def _doctor_security_channel_dm_warning_lines(
    *,
    label: str,
    channel_id: str,
    account_id: str | None,
    dm_policy: _DoctorChannelDmPolicy,
    dm_scope: str,
    data_dir: Path | None,
) -> list[str]:
    warnings: list[str] = []
    has_wildcard, allow_count, is_multi_user_dm = _doctor_dm_allow_state(
        channel_id=channel_id,
        account_id=account_id,
        allow_from=dm_policy.allow_from,
        data_dir=data_dir,
    )
    if dm_policy.policy == "open":
        warnings.append(
            f'- {label} DMs: OPEN ({dm_policy.policy_path}="open"). Anyone can DM it.'
        )
        if not has_wildcard:
            warnings.append(
                f'- {label} DMs: config invalid - "open" requires '
                f'{dm_policy.allow_from_path}allowFrom to include "*".'
            )
    if dm_policy.policy == "disabled":
        warnings.append(f'- {label} DMs: disabled ({dm_policy.policy_path}="disabled").')
        return warnings
    if dm_policy.policy != "open" and allow_count == 0:
        warnings.append(
            f'- {label} DMs: locked ({dm_policy.policy_path}="{dm_policy.policy}") '
            "with no allowlist; unknown senders will be blocked / get a pairing code."
        )
        warnings.append(
            f"  Approve via: openclaw pairing list {channel_id} / "
            f"openclaw pairing approve {channel_id} <code>"
        )
    if dm_scope == "main" and is_multi_user_dm:
        warnings.append(
            f"- {label} DMs: multiple senders share the main session; run: "
            'openclaw config set session.dmScope "per-channel-peer" '
            '(or "per-account-channel-peer" for multi-account channels) to isolate sessions.'
        )
    return warnings


def _doctor_security_channel_dm_warnings(
    snapshot: dict[str, object],
    data_dir: Path | None,
) -> list[str]:
    channels = _dict_config(snapshot.get("channels"))
    if not channels:
        return []
    session = _dict_config(snapshot.get("session"))
    dm_scope = _optional_cli_string(session.get("dmScope")) or "main"
    warnings: list[str] = []
    for raw_channel_id, raw_channel_config in channels.items():
        channel_id = str(raw_channel_id)
        if channel_id == "defaults" or not isinstance(raw_channel_config, dict):
            continue
        channel_config = raw_channel_config
        account_id, account_config = _doctor_channel_default_account(channel_config)
        if not _doctor_channel_enabled(
            channel_config=channel_config,
            account_config=account_config,
        ):
            continue
        if not _doctor_channel_configured(
            channel_config=channel_config,
            account_config=account_config,
        ):
            continue
        dm_policy = _doctor_security_resolve_dm_policy(
            channel_id=channel_id,
            channel_config=channel_config,
            account_id=account_id,
            account_config=account_config,
        )
        warnings.extend(
            _doctor_security_channel_dm_warning_lines(
                label=_doctor_channel_label(channel_id),
                channel_id=channel_id,
                account_id=account_id,
                dm_policy=dm_policy,
                dm_scope=dm_scope,
                data_dir=data_dir,
            )
        )
    return warnings


def _build_doctor_security_payload(
    config_service: object | None = None,
    data_dir: Path | None = None,
    should_repair: bool = False,
) -> dict[str, object]:
    snapshot = _doctor_security_snapshot(config_service)
    if snapshot is None:
        return {
            "status": "unavailable",
            "summary": (
                "Security doctor contribution is unavailable because gateway config "
                "could not be read."
            ),
            "source": "openzues-native",
            "openClawContribution": "doctor:security",
            "repairAvailable": False,
            "warnings": [],
        }
    safe_bin_changes: list[str] = []
    if should_repair:
        repaired_snapshot, safe_bin_changes = _doctor_exec_safe_bin_repair(snapshot)
        if safe_bin_changes:
            patch_object = getattr(config_service, "patch_object", None)
            set_raw = getattr(config_service, "set_raw", None)
            if callable(patch_object):
                patch_object(repaired_snapshot)
                snapshot = repaired_snapshot
            elif callable(set_raw):
                snapshot_hash = getattr(config_service, "_snapshot_hash", None)
                base_hash = (
                    snapshot_hash(snapshot)
                    if callable(snapshot_hash)
                    else None
                )
                set_raw(json.dumps(repaired_snapshot), base_hash=base_hash)
                snapshot = repaired_snapshot
            else:
                safe_bin_changes = []
    exec_safe_bins = _build_doctor_exec_safe_bins_payload(
        snapshot,
        repair_requested=should_repair,
        changes=safe_bin_changes,
    )
    warnings = [
        *_doctor_security_approvals_warnings(snapshot),
        *_doctor_security_heartbeat_warnings(snapshot),
        *_doctor_security_exec_policy_warnings(snapshot, data_dir),
        *[str(item) for item in _object_list(exec_safe_bins.get("warnings"))],
        *_doctor_security_gateway_exposure_warnings(snapshot),
        *_doctor_security_channel_dm_warnings(snapshot, data_dir),
    ]
    return {
        "status": "warning" if warnings else "ok",
        "summary": (
            "Security doctor found configuration warnings."
            if warnings
            else "No channel security warnings detected."
        ),
        "source": "openzues-native",
        "openClawContribution": "doctor:security",
        "repairAvailable": False,
        "warnings": warnings,
        "auditHint": "openclaw security audit --deep",
        "execSafeBins": exec_safe_bins,
    }


def _with_doctor_security_payload(
    payload: dict[str, object],
    config_service: object | None,
    data_dir: Path | None = None,
    should_repair: bool = False,
) -> dict[str, object]:
    security = _build_doctor_security_payload(
        config_service,
        data_dir=data_dir,
        should_repair=should_repair,
    )
    next_payload = dict(payload)
    next_payload["security"] = security
    warnings = [str(item) for item in _object_list(security.get("warnings"))]
    if warnings:
        next_payload = _with_doctor_added_warnings(next_payload, warnings)
    return next_payload


def _doctor_configured_channel_ids(snapshot: dict[str, object]) -> list[str]:
    channels = _dict_config(snapshot.get("channels"))
    return sorted(
        channel_id
        for channel_id in (str(key).strip() for key in channels)
        if channel_id and channel_id != "defaults"
    )


def _doctor_channel_adapter(
    adapters: object | None,
    channel_id: str,
) -> object | None:
    if isinstance(adapters, Mapping):
        return adapters.get(channel_id)
    get_adapter = getattr(adapters, "get", None)
    if callable(get_adapter):
        return get_adapter(channel_id)
    return None


def _doctor_write_config_snapshot(
    config_service: object | None,
    snapshot: dict[str, object],
) -> dict[str, object]:
    if config_service is None:
        raise RuntimeError("Gateway config is unavailable.")
    set_raw = getattr(config_service, "set_raw", None)
    if callable(set_raw):
        current = _doctor_config_snapshot(config_service)
        snapshot_hash = getattr(config_service, "_snapshot_hash", None)
        base_hash = snapshot_hash(current) if callable(snapshot_hash) else None
        result = set_raw(json.dumps(snapshot), base_hash=base_hash)
        return dict(result) if isinstance(result, dict) else {"result": result}
    patch_object = getattr(config_service, "patch_object", None)
    if callable(patch_object):
        result = patch_object(snapshot)
        return dict(result) if isinstance(result, dict) else {"result": result}
    raise RuntimeError("Gateway config repair runtime is unavailable.")


async def _doctor_channel_preview_warnings(
    *,
    adapter: object,
    snapshot: dict[str, object],
) -> list[str]:
    collect = getattr(adapter, "collect_preview_warnings", None) or getattr(
        adapter,
        "collectPreviewWarnings",
        None,
    )
    if not callable(collect):
        return []
    result = collect(cfg=snapshot, doctorFixCommand="openzues doctor --fix")
    if inspect.isawaitable(result):
        result = await result
    if not isinstance(result, list):
        return []
    return [str(item) for item in result if str(item).strip()]


async def _doctor_channel_repair_mutation(
    *,
    adapter: object,
    snapshot: dict[str, object],
) -> dict[str, object] | None:
    repair = getattr(adapter, "repair_config", None) or getattr(
        adapter,
        "repairConfig",
        None,
    )
    if not callable(repair):
        return None
    result = repair(cfg=snapshot, doctorFixCommand="openzues doctor --fix")
    if inspect.isawaitable(result):
        result = await result
    if not isinstance(result, dict):
        return None
    next_config = result.get("config")
    changes = [str(item) for item in _object_list(result.get("changes")) if str(item).strip()]
    warnings = [str(item) for item in _object_list(result.get("warnings")) if str(item).strip()]
    if not changes and not warnings:
        return None
    return {
        "config": next_config if isinstance(next_config, dict) else snapshot,
        "changes": changes,
        "warnings": warnings,
    }


async def _doctor_channel_mutable_allowlist_warnings(
    *,
    adapter: object,
    snapshot: dict[str, object],
) -> list[str]:
    collect = getattr(adapter, "collect_mutable_allowlist_warnings", None) or getattr(
        adapter,
        "collectMutableAllowlistWarnings",
        None,
    )
    if not callable(collect):
        return []
    result = collect(cfg=snapshot)
    if inspect.isawaitable(result):
        result = await result
    if not isinstance(result, list):
        return []
    return [str(item) for item in result if str(item).strip()]


def _doctor_empty_allowlist_context(
    *,
    account: dict[str, object],
    channel_id: str,
    parent: dict[str, object] | None = None,
    prefix: str,
) -> dict[str, object]:
    account_dm = _dict_config(account.get("dm"))
    parent_dm = _dict_config(parent.get("dm")) if parent is not None else {}
    dm_policy = (
        _optional_cli_string(account.get("dmPolicy"))
        or _optional_cli_string(account_dm.get("policy"))
        or (_optional_cli_string(parent.get("dmPolicy")) if parent is not None else None)
        or _optional_cli_string(parent_dm.get("policy"))
    )
    effective_allow_from = (
        _doctor_dm_list(account.get("allowFrom"))
        or (_doctor_dm_list(parent.get("allowFrom")) if parent is not None else [])
        or _doctor_dm_list(account_dm.get("allowFrom"))
        or _doctor_dm_list(parent_dm.get("allowFrom"))
        or None
    )
    return {
        "account": account,
        "channelName": channel_id,
        "dmPolicy": dm_policy,
        "effectiveAllowFrom": effective_allow_from,
        "parent": parent,
        "prefix": prefix,
    }


async def _doctor_channel_empty_allowlist_extra_warnings(
    *,
    adapter: object,
    channel_id: str,
    channel_config: dict[str, object],
) -> list[str]:
    collect = getattr(adapter, "collect_empty_allowlist_extra_warnings", None) or getattr(
        adapter,
        "collectEmptyAllowlistExtraWarnings",
        None,
    )
    if not callable(collect):
        return []
    contexts = [
        _doctor_empty_allowlist_context(
            account=channel_config,
            channel_id=channel_id,
            prefix=f"channels.{channel_id}",
        )
    ]
    for account_id, raw_account in _dict_config(channel_config.get("accounts")).items():
        if not isinstance(raw_account, dict):
            continue
        contexts.append(
            _doctor_empty_allowlist_context(
                account=raw_account,
                channel_id=channel_id,
                parent=channel_config,
                prefix=f"channels.{channel_id}.accounts.{account_id}",
            )
        )
    warnings: list[str] = []
    for context in contexts:
        result = collect(**context)
        if inspect.isawaitable(result):
            result = await result
        if isinstance(result, list):
            warnings.extend(str(item) for item in result if str(item).strip())
    return warnings


async def _doctor_should_skip_empty_group_allowlist_warning(
    *,
    adapter: object | None,
    context: dict[str, object],
) -> bool:
    if adapter is None:
        return False
    should_skip = getattr(
        adapter,
        "should_skip_default_empty_group_allowlist_warning",
        None,
    ) or getattr(adapter, "shouldSkipDefaultEmptyGroupAllowlistWarning", None)
    if not callable(should_skip):
        return False
    result = should_skip(**context)
    if inspect.isawaitable(result):
        result = await result
    return result is True


async def _doctor_channel_empty_group_allowlist_warnings(
    *,
    adapter: object | None,
    channel_id: str,
    channel_config: dict[str, object],
) -> list[str]:
    contexts = [
        _doctor_empty_allowlist_context(
            account=channel_config,
            channel_id=channel_id,
            prefix=f"channels.{channel_id}",
        )
    ]
    for account_id, raw_account in _dict_config(channel_config.get("accounts")).items():
        if not isinstance(raw_account, dict):
            continue
        contexts.append(
            _doctor_empty_allowlist_context(
                account=raw_account,
                channel_id=channel_id,
                parent=channel_config,
                prefix=f"channels.{channel_id}.accounts.{account_id}",
            )
        )
    warnings: list[str] = []
    for context in contexts:
        account = _dict_config(context.get("account"))
        parent = _dict_config(context.get("parent"))
        group_policy = _optional_cli_string(account.get("groupPolicy")) or _optional_cli_string(
            parent.get("groupPolicy")
        )
        if group_policy != "allowlist":
            continue
        group_allow_from = _doctor_dm_list(account.get("groupAllowFrom")) or _doctor_dm_list(
            parent.get("groupAllowFrom")
        )
        effective_allow_from = context.get("effectiveAllowFrom")
        if group_allow_from or (
            isinstance(effective_allow_from, list) and len(effective_allow_from) > 0
        ):
            continue
        if await _doctor_should_skip_empty_group_allowlist_warning(
            adapter=adapter,
            context=context,
        ):
            continue
        prefix = str(context.get("prefix") or f"channels.{channel_id}")
        warnings.append(
            f'- {prefix}.groupPolicy is "allowlist" but groupAllowFrom '
            "(and allowFrom) is empty - all group messages will be silently dropped. "
            f"Add sender IDs to {prefix}.groupAllowFrom or {prefix}.allowFrom, "
            'or set groupPolicy to "open".'
        )
    return warnings


async def _doctor_channel_config_sequence(
    *,
    adapter: object,
    snapshot: dict[str, object],
    should_repair: bool,
) -> dict[str, list[str]]:
    run_sequence = getattr(adapter, "run_config_sequence", None) or getattr(
        adapter,
        "runConfigSequence",
        None,
    )
    if not callable(run_sequence):
        return {"changeNotes": [], "warningNotes": []}
    result = run_sequence(
        cfg=snapshot,
        env=dict(os.environ),
        shouldRepair=should_repair,
    )
    if inspect.isawaitable(result):
        result = await result
    if not isinstance(result, dict):
        return {"changeNotes": [], "warningNotes": []}
    return {
        "changeNotes": [
            str(item) for item in _object_list(result.get("changeNotes")) if str(item).strip()
        ],
        "warningNotes": [
            str(item) for item in _object_list(result.get("warningNotes")) if str(item).strip()
        ],
    }


async def _doctor_channel_stale_config_mutation(
    *,
    adapter: object,
    snapshot: dict[str, object],
) -> dict[str, object] | None:
    clean = getattr(adapter, "clean_stale_config", None) or getattr(
        adapter,
        "cleanStaleConfig",
        None,
    )
    if not callable(clean):
        return None
    result = clean(cfg=snapshot)
    if inspect.isawaitable(result):
        result = await result
    if not isinstance(result, dict):
        return None
    next_config = result.get("config")
    changes = [str(item) for item in _object_list(result.get("changes")) if str(item).strip()]
    warnings = [str(item) for item in _object_list(result.get("warnings")) if str(item).strip()]
    if not changes and not warnings:
        return None
    return {
        "config": next_config if isinstance(next_config, dict) else snapshot,
        "changes": changes,
        "warnings": warnings,
    }


async def _doctor_channel_compatibility_mutation(
    *,
    adapter: object,
    snapshot: dict[str, object],
) -> dict[str, object] | None:
    normalize = getattr(adapter, "normalize_compatibility_config", None) or getattr(
        adapter,
        "normalizeCompatibilityConfig",
        None,
    )
    if not callable(normalize):
        return None
    result = normalize(cfg=snapshot)
    if inspect.isawaitable(result):
        result = await result
    if not isinstance(result, dict):
        return None
    next_config = result.get("config")
    changes = [str(item) for item in _object_list(result.get("changes")) if str(item).strip()]
    warnings = [str(item) for item in _object_list(result.get("warnings")) if str(item).strip()]
    if not changes and not warnings:
        return None
    return {
        "config": next_config if isinstance(next_config, dict) else snapshot,
        "changes": changes,
        "warnings": warnings,
    }


async def _build_doctor_channel_doctor_payload(
    config_service: object | None,
    adapters: object | None,
    *,
    should_repair: bool = False,
) -> dict[str, object]:
    snapshot = _doctor_config_snapshot(config_service)
    channel_ids = _doctor_configured_channel_ids(snapshot)
    warnings: list[str] = []
    changes: list[str] = []
    sequence_changes: list[str] = []
    sequence_warnings: list[str] = []
    stale_changes: list[str] = []
    stale_warnings: list[str] = []
    compatibility_changes: list[str] = []
    compatibility_warnings: list[str] = []
    empty_allowlist_warnings: list[str] = []
    adapter_count = 0
    changed = False
    next_snapshot = snapshot
    for channel_id in channel_ids:
        adapter = _doctor_channel_adapter(adapters, channel_id)
        if adapter is None:
            continue
        adapter_count += 1
        try:
            compatibility_mutation = await _doctor_channel_compatibility_mutation(
                adapter=adapter,
                snapshot=next_snapshot,
            )
            if compatibility_mutation is not None:
                current_compatibility_changes = [
                    str(item)
                    for item in _object_list(compatibility_mutation.get("changes"))
                    if str(item).strip()
                ]
                current_compatibility_warnings = [
                    str(item)
                    for item in _object_list(compatibility_mutation.get("warnings"))
                    if str(item).strip()
                ]
                compatibility_changes.extend(current_compatibility_changes)
                compatibility_warnings.extend(current_compatibility_warnings)
                changes.extend(current_compatibility_changes)
                warnings.extend(current_compatibility_warnings)
                compatibility_config = compatibility_mutation.get("config")
                if isinstance(compatibility_config, dict) and current_compatibility_changes:
                    next_snapshot = compatibility_config
                    changed = should_repair
            sequence = await _doctor_channel_config_sequence(
                adapter=adapter,
                snapshot=next_snapshot,
                should_repair=should_repair,
            )
            current_sequence_changes = sequence["changeNotes"]
            current_sequence_warnings = sequence["warningNotes"]
            sequence_changes.extend(current_sequence_changes)
            sequence_warnings.extend(current_sequence_warnings)
            changes.extend(current_sequence_changes)
            warnings.extend(current_sequence_warnings)
            stale_mutation = await _doctor_channel_stale_config_mutation(
                adapter=adapter,
                snapshot=next_snapshot,
            )
            if stale_mutation is not None:
                current_stale_changes = [
                    str(item)
                    for item in _object_list(stale_mutation.get("changes"))
                    if str(item).strip()
                ]
                current_stale_warnings = [
                    str(item)
                    for item in _object_list(stale_mutation.get("warnings"))
                    if str(item).strip()
                ]
                stale_changes.extend(current_stale_changes)
                stale_warnings.extend(current_stale_warnings)
                changes.extend(current_stale_changes)
                warnings.extend(current_stale_warnings)
                stale_config = stale_mutation.get("config")
                if isinstance(stale_config, dict) and current_stale_changes:
                    next_snapshot = stale_config
                    changed = should_repair
            if should_repair:
                mutation = await _doctor_channel_repair_mutation(
                    adapter=adapter,
                    snapshot=next_snapshot,
                )
                if mutation is None:
                    continue
                changes.extend(
                    str(item)
                    for item in _object_list(mutation.get("changes"))
                    if str(item).strip()
                )
                warnings.extend(
                    str(item)
                    for item in _object_list(mutation.get("warnings"))
                    if str(item).strip()
                )
                mutation_config = mutation.get("config")
                if isinstance(mutation_config, dict) and _object_list(
                    mutation.get("changes")
                ):
                    next_snapshot = mutation_config
                    changed = True
            else:
                warnings.extend(
                    await _doctor_channel_preview_warnings(
                        adapter=adapter,
                        snapshot=snapshot,
                    )
                )
        except Exception as exc:  # pragma: no cover - defensive adapter boundary
            warnings.append(f"- channels.{channel_id} doctor hook failed: {exc}")
    path: object | None = _config_service_path_label(config_service)
    if should_repair and changed:
        try:
            write_result = _doctor_write_config_snapshot(config_service, next_snapshot)
            path = write_result.get("path") or path
        except Exception as exc:
            warnings.append(f"- Channel plugin doctor repair failed: {exc}")
            return {
                "status": "error",
                "summary": "Channel plugin doctor repair failed.",
                "source": "openzues-native",
                "openClawContribution": "doctor:channel-plugin-contracts",
                "repairRequested": should_repair,
                "repairAvailable": adapter_count > 0,
                "configuredChannels": channel_ids,
                "adapterCount": adapter_count,
                "changed": False,
                "changes": changes,
                "warnings": warnings,
                "path": path,
            }
    for channel_id in channel_ids:
        channel_config = _dict_config(next_snapshot.get("channels")).get(channel_id)
        if not isinstance(channel_config, dict):
            continue
        adapter = _doctor_channel_adapter(adapters, channel_id)
        try:
            current_empty_group_warnings = (
                await _doctor_channel_empty_group_allowlist_warnings(
                    adapter=adapter,
                    channel_id=channel_id,
                    channel_config=channel_config,
                )
            )
            empty_allowlist_warnings.extend(current_empty_group_warnings)
            warnings.extend(current_empty_group_warnings)
        except Exception as exc:  # pragma: no cover - defensive adapter boundary
            warnings.append(
                f"- channels.{channel_id} empty group allowlist doctor hook failed: {exc}"
            )
    for channel_id in channel_ids:
        adapter = _doctor_channel_adapter(adapters, channel_id)
        if adapter is None:
            continue
        try:
            warnings.extend(
                await _doctor_channel_mutable_allowlist_warnings(
                    adapter=adapter,
                    snapshot=next_snapshot,
                )
            )
            channel_config = _dict_config(next_snapshot.get("channels")).get(channel_id)
            if isinstance(channel_config, dict):
                current_empty_allowlist_warnings = (
                    await _doctor_channel_empty_allowlist_extra_warnings(
                        adapter=adapter,
                        channel_id=channel_id,
                        channel_config=channel_config,
                    )
                )
                empty_allowlist_warnings.extend(current_empty_allowlist_warnings)
                warnings.extend(current_empty_allowlist_warnings)
        except Exception as exc:  # pragma: no cover - defensive adapter boundary
            warnings.append(
                f"- channels.{channel_id} mutable allowlist doctor hook failed: {exc}"
            )
    return {
        "status": "warning" if warnings else "ok",
        "summary": (
            "Channel plugin doctor repair applied changes."
            if should_repair and changed
            else (
                "Channel plugin doctor hooks reported warnings."
                if warnings
                else "No channel plugin doctor warnings detected."
            )
        ),
        "source": "openzues-native",
        "openClawContribution": "doctor:channel-plugin-contracts",
        "repairRequested": should_repair,
        "repairAvailable": adapter_count > 0,
        "configuredChannels": channel_ids,
        "adapterCount": adapter_count,
        "changed": changed,
        "changes": changes,
        "sequenceChanges": sequence_changes,
        "sequenceWarnings": sequence_warnings,
        "staleChanges": stale_changes,
        "staleWarnings": stale_warnings,
        "compatibilityChanges": compatibility_changes,
        "compatibilityWarnings": compatibility_warnings,
        "emptyAllowlistWarnings": empty_allowlist_warnings,
        "warnings": warnings,
        "path": path,
    }


async def _with_doctor_channel_doctor_payload(
    payload: dict[str, object],
    config_service: object | None,
    adapters: object | None,
    *,
    should_repair: bool = False,
) -> dict[str, object]:
    channel_doctor = await _build_doctor_channel_doctor_payload(
        config_service,
        adapters,
        should_repair=should_repair,
    )
    next_payload = dict(payload)
    next_payload["channelDoctor"] = channel_doctor
    warnings = [str(item) for item in _object_list(channel_doctor.get("warnings"))]
    if warnings:
        next_payload = _with_doctor_added_warnings(next_payload, warnings)
    return next_payload


_DOCTOR_COMPLETION_SHELL_EXTENSIONS = {
    "bash": "bash",
    "fish": "fish",
    "powershell": "ps1",
    "zsh": "zsh",
}


def _doctor_completion_shell_from_env(env: Mapping[str, str] | None = None) -> str:
    environ = env or os.environ
    shell_path = _optional_cli_string(environ.get("SHELL")) or ""
    shell_name = Path(shell_path).name.lower() if shell_path else ""
    if shell_name in {"bash", "fish", "zsh"}:
        return shell_name
    if shell_name in {"powershell", "pwsh"}:
        return "powershell"
    if os.name == "nt":
        return "powershell"
    return "zsh"


def _doctor_completion_cache_path(
    *,
    data_dir: Path,
    shell: str,
    bin_name: str,
) -> Path:
    safe_bin_name = re.sub(r"[^a-zA-Z0-9._-]", "-", bin_name.strip() or "openzues")
    extension = _DOCTOR_COMPLETION_SHELL_EXTENSIONS.get(shell, shell)
    return data_dir / "completions" / f"{safe_bin_name}.{extension}"


def _doctor_completion_profile_path(
    *,
    shell: str,
    env: Mapping[str, str] | None = None,
) -> Path:
    environ = env or os.environ
    home = Path(
        _optional_cli_string(environ.get("HOME"))
        or _optional_cli_string(environ.get("USERPROFILE"))
        or str(Path.home())
    )
    if shell == "zsh":
        return home / ".zshrc"
    if shell == "bash":
        bashrc = home / ".bashrc"
        return bashrc if bashrc.exists() else home / ".bash_profile"
    if shell == "fish":
        return home / ".config" / "fish" / "config.fish"
    if os.name == "nt":
        user_profile = Path(_optional_cli_string(environ.get("USERPROFILE")) or str(home))
        return (
            user_profile
            / "Documents"
            / "PowerShell"
            / "Microsoft.PowerShell_profile.ps1"
        )
    return home / ".config" / "powershell" / "Microsoft.PowerShell_profile.ps1"


def _doctor_completion_profile_lines(profile_path: Path) -> list[str]:
    try:
        return profile_path.read_text(encoding="utf-8").splitlines()
    except OSError:
        return []


def _doctor_completion_is_profile_line(
    line: str,
    *,
    bin_name: str,
    cache_path: Path | None,
) -> bool:
    stripped = line.strip()
    if stripped in {"# OpenClaw Completion", "# OpenZues Completion"}:
        return True
    if f"{bin_name} completion" in line:
        return True
    if cache_path is not None and str(cache_path) in line:
        return True
    return False


def _doctor_completion_is_slow_line(line: str, *, bin_name: str, cache_path: Path) -> bool:
    return (
        (f"<({bin_name} completion" in line)
        or (f"{bin_name} completion" in line and "| source" in line)
    ) and str(cache_path) not in line


def _doctor_completion_source_line(*, shell: str, cache_path: Path) -> str:
    if shell == "powershell":
        return f'. "{cache_path}"'
    return f'source "{cache_path}"'


def _doctor_completion_generate_cache(cache_path: Path) -> bool:
    cache_path.parent.mkdir(parents=True, exist_ok=True)
    try:
        result = subprocess.run(
            [sys.executable, "-m", "openzues.cli", "--show-completion"],
            capture_output=True,
            check=False,
            encoding="utf-8",
            errors="replace",
            timeout=20,
        )
    except (OSError, subprocess.SubprocessError):
        return False
    if result.returncode != 0 or not result.stdout.strip():
        return False
    try:
        cache_path.write_text(result.stdout, encoding="utf-8")
    except OSError:
        return False
    return True


def _doctor_completion_update_profile(
    *,
    shell: str,
    bin_name: str,
    cache_path: Path,
    profile_path: Path,
) -> bool:
    profile_path.parent.mkdir(parents=True, exist_ok=True)
    lines = _doctor_completion_profile_lines(profile_path)
    filtered: list[str] = []
    skip_next = False
    for line in lines:
        if skip_next:
            skip_next = False
            continue
        if line.strip() in {"# OpenClaw Completion", "# OpenZues Completion"}:
            skip_next = True
            continue
        if _doctor_completion_is_profile_line(
            line,
            bin_name=bin_name,
            cache_path=cache_path,
        ):
            continue
        if _doctor_completion_is_slow_line(line, bin_name=bin_name, cache_path=cache_path):
            continue
        filtered.append(line)

    trimmed = "\n".join(filtered).rstrip()
    source_line = _doctor_completion_source_line(shell=shell, cache_path=cache_path)
    block = f"# OpenZues Completion\n{source_line}"
    next_content = f"{trimmed}\n\n{block}\n" if trimmed else f"{block}\n"
    try:
        current = profile_path.read_text(encoding="utf-8")
    except OSError:
        current = ""
    if next_content == current:
        return False
    profile_path.write_text(next_content, encoding="utf-8")
    return True


def _build_doctor_shell_completion_payload(
    data_dir: Path | None = None,
    *,
    bin_name: str = "openzues",
    should_repair: bool = False,
) -> dict[str, object]:
    if data_dir is not None:
        shell = _doctor_completion_shell_from_env()
        cache_path = _doctor_completion_cache_path(
            data_dir=data_dir,
            shell=shell,
            bin_name=bin_name,
        )
        profile_path = _doctor_completion_profile_path(shell=shell)
        cache_exists = cache_path.exists()
        profile_lines = _doctor_completion_profile_lines(profile_path)
        profile_installed = any(
            _doctor_completion_is_profile_line(
                line,
                bin_name=bin_name,
                cache_path=cache_path if cache_exists else None,
            )
            for line in profile_lines
        )
        uses_slow_pattern = any(
            _doctor_completion_is_slow_line(line, bin_name=bin_name, cache_path=cache_path)
            for line in profile_lines
        )
        repair_changes: list[str] = []
        repair_errors: list[str] = []
        if should_repair and (
            uses_slow_pattern or not profile_installed or not cache_exists
        ):
            cache_generated = cache_exists or _doctor_completion_generate_cache(cache_path)
            if cache_generated and not cache_exists:
                repair_changes.append(f"Generated completion cache at {cache_path}.")
            if not cache_generated:
                repair_errors.append(
                    f"Failed to generate completion cache at {cache_path}."
                )
            if cache_generated and (uses_slow_pattern or not profile_installed):
                try:
                    profile_changed = _doctor_completion_update_profile(
                        shell=shell,
                        bin_name=bin_name,
                        cache_path=cache_path,
                        profile_path=profile_path,
                    )
                except OSError as exc:
                    profile_changed = False
                    repair_errors.append(f"Failed to update {shell} profile: {exc}")
                if profile_changed:
                    if profile_installed:
                        repair_changes.append(f"Updated {shell} profile at {profile_path}.")
                    else:
                        repair_changes.append(
                            f"Installed {shell} completion in {profile_path}."
                        )
            cache_exists = cache_path.exists()
            profile_lines = _doctor_completion_profile_lines(profile_path)
            profile_installed = any(
                _doctor_completion_is_profile_line(
                    line,
                    bin_name=bin_name,
                    cache_path=cache_path if cache_exists else None,
                )
                for line in profile_lines
            )
            uses_slow_pattern = any(
                _doctor_completion_is_slow_line(line, bin_name=bin_name, cache_path=cache_path)
                for line in profile_lines
            )

        warnings: list[str] = []
        if uses_slow_pattern:
            warnings.append(
                f"- Shell completion: {shell} profile uses slow dynamic completion. "
                "Run openzues doctor --fix to upgrade to cached completion."
            )
        if profile_installed and not cache_exists:
            warnings.append(
                f"- Shell completion: {shell} profile is configured but cache is missing "
                f"at {cache_path}. Run openzues doctor --fix to regenerate it."
            )
        summary = (
            "Shell completion repair applied."
            if repair_changes and not warnings and not repair_errors
            else (
                "Shell completion needs attention."
                if warnings or repair_errors
                else "Shell completion profile and cache state are healthy."
            )
        )
        payload: dict[str, object] = {
            "status": "warning" if warnings else "ok",
            "summary": summary,
            "source": "openzues-native",
            "openClawContribution": "doctor:shell-completion",
            "repairAvailable": True,
            "repairRequested": should_repair,
            "changed": bool(repair_changes),
            "shell": shell,
            "profileInstalled": profile_installed,
            "cacheExists": cache_exists,
            "cachePath": str(cache_path),
            "profilePath": str(profile_path),
            "usesSlowPattern": uses_slow_pattern,
            "warnings": warnings,
        }
        if repair_changes:
            payload["changes"] = repair_changes
        if repair_errors:
            payload["errors"] = repair_errors
            payload["status"] = "warning"
        return payload
    return {
        "status": "partial",
        "summary": (
            "Typer shell completion is available, but the OpenClaw doctor repair flow "
            "is not wired into the native OpenZues CLI runtime yet."
        ),
        "source": "openzues-native",
        "openClawContribution": "doctor:shell-completion",
        "repairAvailable": False,
    }


def _with_doctor_shell_completion_payload(
    payload: dict[str, object],
    data_dir: Path | None,
    *,
    should_repair: bool = False,
) -> dict[str, object]:
    shell_completion = _build_doctor_shell_completion_payload(
        data_dir,
        should_repair=should_repair,
    )
    next_payload = dict(payload)
    next_payload["shellCompletion"] = shell_completion
    warnings = [str(item) for item in _object_list(shell_completion.get("warnings"))]
    if warnings:
        next_payload = _with_doctor_added_warnings(next_payload, warnings)
    return next_payload


def _doctor_bundled_plugin_runtime_dependency_summary(
    *,
    missing: list[object],
    conflicts: list[object],
) -> str:
    if missing and conflicts:
        return "Bundled plugin runtime deps are missing and use conflicting versions."
    if conflicts:
        return "Bundled plugin runtime deps use conflicting versions."
    if missing:
        return "Bundled plugin runtime deps are missing."
    return "Bundled plugin runtime deps are present."


def _build_doctor_bundled_plugin_runtime_dependency_payload(
    config_service: object | None,
) -> dict[str, object]:
    build_snapshot = getattr(config_service, "build_snapshot", None)
    if not callable(build_snapshot):
        return {
            "status": "unavailable",
            "summary": (
                "Gateway config is unavailable for bundled plugin runtime dependency "
                "checks."
            ),
            "source": "openzues-native",
            "openClawContribution": "doctor:bundled-plugin-runtime-deps",
            "repairAvailable": False,
            "missing": [],
            "conflicts": [],
            "diagnostics": [],
        }
    try:
        raw_snapshot = build_snapshot()
    except Exception as exc:  # pragma: no cover - defensive adapter boundary
        return {
            "status": "unavailable",
            "summary": f"Gateway config could not be read: {exc}",
            "source": "openzues-native",
            "openClawContribution": "doctor:bundled-plugin-runtime-deps",
            "repairAvailable": False,
            "missing": [],
            "conflicts": [],
            "diagnostics": [],
        }
    snapshot = raw_snapshot if isinstance(raw_snapshot, dict) else {}
    plugin_rows = _plugin_records_from_config_snapshot(snapshot)
    runtime_payload, diagnostics = _build_plugin_runtime_dependency_doctor_payload(
        list(plugin_rows)
    )
    raw_missing = runtime_payload.get("missing")
    raw_conflicts = runtime_payload.get("conflicts")
    missing = raw_missing if isinstance(raw_missing, list) else []
    conflicts = raw_conflicts if isinstance(raw_conflicts, list) else []
    return {
        "status": "error" if missing or conflicts else "ok",
        "summary": _doctor_bundled_plugin_runtime_dependency_summary(
            missing=missing,
            conflicts=conflicts,
        ),
        "source": "openzues-native",
        "openClawContribution": "doctor:bundled-plugin-runtime-deps",
        "repairAvailable": False,
        "missing": missing,
        "conflicts": conflicts,
        "diagnostics": diagnostics,
    }


def _with_doctor_bundled_plugin_runtime_dependencies(
    payload: dict[str, object],
    config_service: object | None,
) -> dict[str, object]:
    next_payload = dict(payload)
    next_payload["bundledPluginRuntimeDependencies"] = (
        _build_doctor_bundled_plugin_runtime_dependency_payload(config_service)
    )
    return next_payload


def _collect_doctor_channel_status_warnings(
    channel_status_payload: dict[str, object],
) -> list[dict[str, object]]:
    accounts_by_channel = channel_status_payload.get("channelAccounts")
    if not isinstance(accounts_by_channel, dict):
        return []
    warnings: list[dict[str, object]] = []
    for raw_channel, raw_accounts in accounts_by_channel.items():
        channel = str(raw_channel or "").strip()
        if not channel or not isinstance(raw_accounts, list):
            continue
        for raw_account in raw_accounts:
            if not isinstance(raw_account, dict):
                continue
            probe = raw_account.get("probe")
            if not isinstance(probe, dict):
                continue
            reason = _optional_cli_string(probe.get("reason"))
            status = _optional_cli_string(probe.get("status"))
            if reason == "native_provider_probe_unsupported" or status == "unsupported":
                continue
            is_issue = probe.get("ok") is False or status in {
                "degraded",
                "error",
                "fail",
                "failed",
                "unavailable",
                "warn",
                "warning",
            }
            if not is_issue:
                continue
            account_id = _optional_cli_string(raw_account.get("accountId"))
            if account_id is None:
                account_id = _optional_cli_string(raw_account.get("account_id"))
            message = (
                _optional_cli_string(probe.get("summary"))
                or _optional_cli_string(probe.get("error"))
                or reason
                or "Channel account probe is not ready."
            )
            warning: dict[str, object] = {
                "channel": channel,
                "accountId": account_id or DEFAULT_ACCOUNT_ID,
                "status": status or "warn",
                "message": message,
            }
            if reason is not None:
                warning["reason"] = reason
            fix = _optional_cli_string(probe.get("fix"))
            if fix is not None:
                warning["fix"] = fix
            warnings.append(warning)
    return warnings


async def _build_doctor_gateway_health_payload(
    app_settings: object,
    gateway_node_methods: object | None,
) -> dict[str, object]:
    base_payload: dict[str, object] = {
        "source": "openzues-native",
        "openClawContribution": "doctor:gateway-health",
        "repairAvailable": False,
        "timeoutMs": 3000,
        "channelProbeTimeoutMs": 5000,
    }
    try:
        health_payload = await _build_live_health_payload(
            cast(Settings, app_settings),
            timeout_ms=3000,
        )
    except Exception as exc:  # pragma: no cover - defensive local runtime boundary
        return {
            **base_payload,
            "status": "unavailable",
            "summary": f"Gateway health probe is unavailable: {exc}",
            "healthOk": False,
            "health": None,
            "channelWarnings": [],
        }

    health_ok = health_payload.get("ok") is True or health_payload.get("status") == "ok"
    channel_status: dict[str, object] | None = None
    channel_warnings: list[dict[str, object]] = []
    if health_ok:
        call = getattr(gateway_node_methods, "call", None)
        if callable(call):
            try:
                raw_channel_status = await call(
                    "channels.status",
                    {"probe": True, "timeoutMs": 5000},
                )
            except Exception as exc:  # pragma: no cover - upstream ignores this branch
                channel_status = {
                    "status": "unavailable",
                    "error": str(exc),
                }
            else:
                if isinstance(raw_channel_status, dict):
                    channel_status = raw_channel_status
                    channel_warnings = _collect_doctor_channel_status_warnings(
                        raw_channel_status
                    )
                else:
                    channel_status = {
                        "status": "unavailable",
                        "error": "channels.status response was not an object",
                    }
        else:
            channel_status = {
                "status": "unavailable",
                "reason": "native_gateway_method_runtime_unavailable",
            }

    if not health_ok:
        status = "error"
        summary = "Gateway health probe did not pass."
    elif channel_warnings:
        status = "warn"
        summary = "Gateway health probe passed with channel warnings."
    else:
        status = "ok"
        summary = "Gateway health probe passed."

    payload: dict[str, object] = {
        **base_payload,
        "status": status,
        "summary": summary,
        "healthOk": health_ok,
        "health": health_payload,
        "channelWarnings": channel_warnings,
    }
    if channel_status is not None:
        payload["channelStatus"] = channel_status
    return payload


async def _with_doctor_gateway_health_payload(
    payload: dict[str, object],
    app_settings: object,
    gateway_node_methods: object | None,
) -> dict[str, object]:
    next_payload = dict(payload)
    next_payload["gatewayHealth"] = await _build_doctor_gateway_health_payload(
        app_settings,
        gateway_node_methods,
    )
    return next_payload


def _doctor_gateway_memory_probe_warning(probe: dict[str, object]) -> str | None:
    if probe.get("checked") is not True or probe.get("ready") is True:
        return None
    error = _optional_cli_string(probe.get("error"))
    if error is not None:
        return f"Gateway memory probe for default agent is not ready: {error}"
    return "Gateway memory probe for default agent is not ready."


async def _build_doctor_gateway_memory_probe(
    gateway_node_methods: object | None,
) -> dict[str, object]:
    call = getattr(gateway_node_methods, "call", None)
    if not callable(call):
        return {"checked": False, "ready": False}
    try:
        payload = await call("doctor.memory.status", {})
    except Exception as exc:  # pragma: no cover - defensive adapter boundary
        return {
            "checked": True,
            "ready": False,
            "error": f"gateway memory probe unavailable: {exc}",
        }
    if not isinstance(payload, dict):
        return {
            "checked": True,
            "ready": False,
            "error": "gateway memory probe response was not an object",
        }
    embedding = payload.get("embedding")
    embedding_payload = embedding if isinstance(embedding, dict) else {}
    result: dict[str, object] = {
        "checked": True,
        "ready": embedding_payload.get("ok") is True,
    }
    agent_id = _optional_cli_string(payload.get("agentId"))
    if agent_id is not None:
        result["agentId"] = agent_id
    provider = _optional_cli_string(embedding_payload.get("provider"))
    if provider is not None:
        result["provider"] = provider
    error = _optional_cli_string(embedding_payload.get("error"))
    if error is not None:
        result["error"] = error
    return result


def _build_doctor_memory_search_payload(
    gateway_memory_probe: dict[str, object],
) -> dict[str, object]:
    warning = _doctor_gateway_memory_probe_warning(gateway_memory_probe)
    if gateway_memory_probe.get("checked") is not True:
        status = "unavailable"
        summary = "Gateway memory probe is unavailable."
    elif gateway_memory_probe.get("ready") is True:
        status = "ok"
        summary = "Gateway memory probe reports embeddings are ready."
    else:
        status = "warn"
        summary = warning or "Gateway memory probe for default agent is not ready."
    warnings = [warning] if warning else []
    return {
        "status": status,
        "summary": summary,
        "source": "openzues-native",
        "openClawContribution": "doctor:memory-search",
        "repairAvailable": False,
        "gatewayMemoryProbe": gateway_memory_probe,
        "warnings": warnings,
    }


async def _with_doctor_memory_search_payload(
    payload: dict[str, object],
    gateway_node_methods: object | None,
) -> dict[str, object]:
    next_payload = dict(payload)
    probe = await _build_doctor_gateway_memory_probe(gateway_node_methods)
    next_payload["memorySearch"] = _build_doctor_memory_search_payload(probe)
    return next_payload


def _doctor_safe_device_text(value: object) -> str | None:
    text = _optional_cli_string(value)
    if text is None:
        return None
    return (
        text.replace("\x1b", "")
        .replace("\r", "\\r")
        .replace("\n", "\\n")
        .replace("\t", " ")
    )


def _doctor_quote_cli_arg(value: str) -> str:
    if re.fullmatch(r"[A-Za-z0-9_/:=.,@%+-]+", value):
        return value
    return "'" + value.replace("'", "'\\''") + "'"


def _doctor_format_cli_args(args: Sequence[str]) -> str:
    return " ".join(_doctor_quote_cli_arg(arg) for arg in args)


def _doctor_unique_strings(*items: object) -> list[str]:
    values: list[str] = []
    seen: set[str] = set()
    for item in items:
        if isinstance(item, str):
            candidates: Sequence[object] = [item]
        elif isinstance(item, (list, tuple)):
            candidates = item
        else:
            continue
        for candidate in candidates:
            if not isinstance(candidate, str):
                continue
            trimmed = candidate.strip()
            if not trimmed or trimmed in seen:
                continue
            seen.add(trimmed)
            values.append(trimmed)
    return values


def _doctor_device_label(pending: dict[str, object]) -> str:
    device_id = _doctor_safe_device_text(pending.get("deviceId")) or "unknown-device"
    label = _doctor_safe_device_text(pending.get("displayName")) or _doctor_safe_device_text(
        pending.get("clientId")
    )
    return f"{label} ({device_id})" if label else device_id


def _doctor_paired_device_label(paired: dict[str, object]) -> str:
    device_id = _doctor_safe_device_text(paired.get("deviceId")) or "unknown-device"
    label = _doctor_safe_device_text(paired.get("displayName")) or _doctor_safe_device_text(
        paired.get("clientId")
    )
    return f"{label} ({device_id})" if label else device_id


def _doctor_format_roles(roles: Sequence[str]) -> str:
    return ", ".join(roles) if roles else "none"


def _doctor_format_scopes(scopes: Sequence[str]) -> str:
    return ", ".join(scopes) if scopes else "none"


def _doctor_approved_roles(paired: dict[str, object]) -> list[str]:
    return _doctor_unique_strings(paired.get("roles"), paired.get("role"))


def _doctor_normalize_device_scopes(value: object) -> list[str]:
    scopes = _doctor_unique_strings(value)
    out = set(scopes)
    if "operator.admin" in out:
        out.add("operator.read")
        out.add("operator.write")
    elif "operator.write" in out:
        out.add("operator.read")
    return sorted(out)


def _doctor_approved_scopes(paired: dict[str, object]) -> list[str]:
    approved = _doctor_normalize_device_scopes(paired.get("approvedScopes"))
    if approved:
        return approved
    return _doctor_normalize_device_scopes(paired.get("scopes"))


def _doctor_role_scopes_allow(
    *,
    role: str,
    requested_scopes: Sequence[str],
    allowed_scopes: Sequence[str],
) -> bool:
    requested = _doctor_unique_strings(list(requested_scopes))
    if not requested:
        return True
    allowed = _doctor_unique_strings(list(allowed_scopes))
    if not allowed:
        return False
    allowed_set = set(allowed)
    normalized_role = role.strip()
    if normalized_role != "operator":
        prefix = f"{normalized_role}."
        return all(scope.startswith(prefix) and scope in allowed_set for scope in requested)
    if "operator.admin" in allowed_set:
        return all(scope.startswith("operator.") for scope in requested)
    for scope in requested:
        if not scope.startswith("operator."):
            return False
        if scope == "operator.read":
            if "operator.read" in allowed_set or "operator.write" in allowed_set:
                continue
            return False
        if scope == "operator.write":
            if "operator.write" in allowed_set:
                continue
            return False
        if scope not in allowed_set:
            return False
    return True


def _doctor_has_pending_scope_upgrade(
    *,
    requested_roles: Sequence[str],
    pending_scopes: Sequence[str],
    approved_roles: Sequence[str],
    approved_scopes: Sequence[str],
) -> bool:
    for role in requested_roles:
        if role not in approved_roles:
            continue
        requested_for_role = [
            scope
            for scope in pending_scopes
            if (
                (role == "operator" and scope.startswith("operator."))
                or (role != "operator" and not scope.startswith("operator."))
            )
        ]
        if requested_for_role and not _doctor_role_scopes_allow(
            role=role,
            requested_scopes=requested_for_role,
            allowed_scopes=approved_scopes,
        ):
            return True
    return False


def _doctor_pending_pairing_warning(
    pending: dict[str, object],
    paired: dict[str, object] | None = None,
) -> str | None:
    request_id = _doctor_safe_device_text(pending.get("requestId"))
    if request_id is None:
        return None
    device_label = _doctor_device_label(pending)
    inspect_command = _doctor_format_cli_args(["openclaw", "devices", "list"])
    approve_command = _doctor_format_cli_args(
        ["openclaw", "devices", "approve", request_id]
    )
    if paired is not None:
        pending_public_key = _optional_cli_string(pending.get("publicKey"))
        paired_public_key = _optional_cli_string(paired.get("publicKey"))
        if (
            pending_public_key is not None
            and paired_public_key is not None
            and pending_public_key != paired_public_key
        ):
            device_id = _doctor_safe_device_text(pending.get("deviceId")) or "unknown-device"
            remove_command = _doctor_format_cli_args(
                ["openclaw", "devices", "remove", device_id]
            )
            return (
                f"- Pending device repair {request_id} for {device_label}: the current "
                "device identity no longer matches the approved pairing record. This "
                "commonly loops on pairing-required for an already paired device. "
                f"Remove the stale record with {remove_command}, then rerun "
                f"{inspect_command} and approve with {approve_command}."
            )
        requested_roles = _doctor_unique_strings(pending.get("roles"), pending.get("role"))
        approved_roles = _doctor_approved_roles(paired)
        if any(role not in approved_roles for role in requested_roles):
            return (
                f"- Pending role upgrade {request_id} for {device_label}: approved roles "
                f"[{_doctor_format_roles(approved_roles)}], requested roles "
                f"[{_doctor_format_roles(requested_roles)}]. Review with "
                f"{inspect_command}, then approve with {approve_command}."
            )
        approved_scopes = _doctor_approved_scopes(paired)
        requested_scopes = _doctor_normalize_device_scopes(pending.get("scopes"))
        if _doctor_has_pending_scope_upgrade(
            requested_roles=requested_roles,
            pending_scopes=requested_scopes,
            approved_roles=approved_roles,
            approved_scopes=approved_scopes,
        ):
            return (
                f"- Pending scope upgrade {request_id} for {device_label}: approved scopes "
                f"[{_doctor_format_scopes(approved_scopes)}], requested scopes "
                f"[{_doctor_format_scopes(requested_scopes)}]. Review with "
                f"{inspect_command}, then approve with {approve_command}."
            )
        return (
            f"- Pending device repair {request_id} for {device_label}: the device is already "
            "paired, but a new approval is still required before the requested auth can be "
            f"used. Review with {inspect_command}, then approve with {approve_command}."
        )
    return (
        f"- Pending device pairing request {request_id} for {device_label}. "
        f"Review with {inspect_command}, then approve with {approve_command}."
    )


def _doctor_token_summaries(paired: dict[str, object]) -> list[dict[str, object]]:
    tokens = paired.get("tokens")
    if isinstance(tokens, list):
        return [item for item in tokens if isinstance(item, dict)]
    if isinstance(tokens, dict):
        return [item for item in tokens.values() if isinstance(item, dict)]
    return []


def _doctor_find_active_token(
    paired: dict[str, object],
    role: str,
) -> dict[str, object] | None:
    for token in _doctor_token_summaries(paired):
        token_role = _optional_cli_string(token.get("role"))
        if token_role != role:
            continue
        if token.get("revokedAtMs") is not None:
            continue
        return token
    return None


def _doctor_number_ms(value: object) -> int | None:
    if isinstance(value, bool):
        return None
    if isinstance(value, int):
        return value
    if isinstance(value, float) and value.is_integer():
        return int(value)
    return None


def _doctor_paired_record_warnings(paired: dict[str, object]) -> list[str]:
    device_id = _doctor_safe_device_text(paired.get("deviceId")) or "unknown-device"
    device_label = _doctor_paired_device_label(paired)
    approved_roles = _doctor_approved_roles(paired)
    approved_scopes = _doctor_approved_scopes(paired)
    warnings: list[str] = []
    if "operator" in approved_roles and not approved_scopes:
        warnings.append(
            f"- Paired device {device_label} is missing its approved operator scope "
            "baseline. Scope upgrades can get stuck in pairing-required until the "
            "device repairs or is re-approved."
        )
    for role in approved_roles:
        rotate_command = _doctor_format_cli_args(
            ["openclaw", "devices", "rotate", "--device", device_id, "--role", role]
        )
        token = _doctor_find_active_token(paired, role)
        if token is None:
            warnings.append(
                f"- Paired device {device_label} has no active {role} device token even "
                "though the role is approved. This commonly ends in pairing-required or "
                f"device-token-mismatch. Rotate a fresh token with {rotate_command}."
            )
            continue
        token_scopes = _doctor_normalize_device_scopes(token.get("scopes"))
        if token_scopes and not _doctor_role_scopes_allow(
            role=role,
            requested_scopes=token_scopes,
            allowed_scopes=approved_scopes,
        ):
            warnings.append(
                f"- Paired device {device_label} has a {role} token outside the approved "
                f"scope baseline [{_doctor_format_scopes(approved_scopes)}]. Rotate it "
                f"with {rotate_command}."
            )
    return warnings


def _doctor_read_local_device_identity(data_dir: Path | None) -> str | None:
    if data_dir is None:
        return None
    identity = _read_cli_json_object(data_dir / "identity" / "device.json")
    if identity is None:
        return None
    if _doctor_number_ms(identity.get("version")) != 1:
        return None
    return _optional_cli_string(identity.get("deviceId"))


def _doctor_local_auth_token_entry(value: object) -> dict[str, object] | None:
    if not isinstance(value, dict):
        return None
    if _optional_cli_string(value.get("token")) is None:
        return None
    role = _optional_cli_string(value.get("role"))
    updated_at_ms = _doctor_number_ms(value.get("updatedAtMs"))
    if role is None or updated_at_ms is None:
        return None
    raw_scopes = value.get("scopes")
    if not isinstance(raw_scopes, list):
        return None
    scopes: list[str] = []
    for scope in raw_scopes:
        if not isinstance(scope, str):
            return None
        scopes.append(scope)
    return {
        "role": role,
        "scopes": scopes,
        "updatedAtMs": updated_at_ms,
    }


def _doctor_read_local_device_auth_store(
    data_dir: Path | None,
) -> dict[str, object] | None:
    if data_dir is None:
        return None
    store = _read_cli_json_object(data_dir / "identity" / "device-auth.json")
    if store is None:
        return None
    if _doctor_number_ms(store.get("version")) != 1:
        return None
    device_id = _optional_cli_string(store.get("deviceId"))
    raw_tokens = store.get("tokens")
    if device_id is None or not isinstance(raw_tokens, dict):
        return None
    tokens: list[dict[str, object]] = []
    for entry in raw_tokens.values():
        token = _doctor_local_auth_token_entry(entry)
        if token is None:
            return None
        tokens.append(token)
    return {"deviceId": device_id, "tokens": tokens}


def _doctor_local_device_auth_warnings(
    paired: Sequence[dict[str, object]],
    data_dir: Path | None,
) -> list[str]:
    identity_device_id = _doctor_read_local_device_identity(data_dir)
    store = _doctor_read_local_device_auth_store(data_dir)
    if identity_device_id is None or store is None:
        return []
    store_device_id = _optional_cli_string(store.get("deviceId"))
    if store_device_id != identity_device_id:
        return []
    paired_device = next(
        (
            device
            for device in paired
            if _optional_cli_string(device.get("deviceId")) == identity_device_id
        ),
        None,
    )
    if paired_device is None:
        return []
    device_label = _doctor_paired_device_label(paired_device)
    approved_roles = set(_doctor_approved_roles(paired_device))
    warnings: list[str] = []
    for entry in _object_list(store.get("tokens")):
        if not isinstance(entry, dict):
            continue
        role = _optional_cli_string(entry.get("role"))
        updated_at_ms = _doctor_number_ms(entry.get("updatedAtMs"))
        if role is None or updated_at_ms is None:
            continue
        rotate_command = _doctor_format_cli_args(
            [
                "openclaw",
                "devices",
                "rotate",
                "--device",
                identity_device_id,
                "--role",
                role,
            ]
        )
        paired_token = _doctor_find_active_token(paired_device, role)
        if paired_token is None:
            if role in approved_roles:
                continue
            warnings.append(
                f"- Local cached {role} device auth for {device_label} no longer has a "
                "matching active gateway token. Reconnect with shared gateway auth to "
                f"refresh it, or rotate with {rotate_command}."
            )
            continue
        gateway_issued_at_ms = _doctor_number_ms(
            paired_token.get("rotatedAtMs")
        ) or _doctor_number_ms(paired_token.get("createdAtMs"))
        if gateway_issued_at_ms is not None and updated_at_ms < gateway_issued_at_ms:
            warnings.append(
                f"- Local cached {role} device token for {device_label} predates the "
                "gateway rotation. This is a stale device-token pattern and can fail "
                "with device token mismatch. Reconnect with shared gateway auth to "
                f"refresh it, or rotate again with {rotate_command}."
            )
            continue
        cached_scopes = _doctor_normalize_device_scopes(entry.get("scopes"))
        paired_scopes = _doctor_normalize_device_scopes(paired_token.get("scopes"))
        if "\n".join(cached_scopes) != "\n".join(paired_scopes):
            warnings.append(
                f"- Local cached {role} device scopes for {device_label} differ from the "
                f"gateway record. Cached scopes [{_doctor_format_scopes(cached_scopes)}], "
                f"gateway scopes [{_doctor_format_scopes(paired_scopes)}]. Reconnect "
                f"with shared gateway auth to refresh it, or rotate with {rotate_command}."
            )
    return warnings


async def _build_doctor_device_pairing_payload(
    gateway_node_methods: object | None,
    data_dir: Path | None = None,
) -> dict[str, object]:
    base_payload: dict[str, object] = {
        "source": "openzues-native",
        "openClawContribution": "doctor:device-pairing",
        "repairAvailable": False,
        "warnings": [],
    }
    call = getattr(gateway_node_methods, "call", None)
    if not callable(call):
        return {
            **base_payload,
            "status": "unavailable",
            "summary": "Device pairing health is unavailable.",
            "checked": False,
        }
    try:
        result = await call("device.pair.list", {})
    except Exception as exc:  # pragma: no cover - defensive adapter boundary
        return {
            **base_payload,
            "status": "unavailable",
            "summary": f"Device pairing health is unavailable: {exc}",
            "checked": False,
        }
    result_payload = result if isinstance(result, dict) else {}
    pending = [
        item for item in _object_list(result_payload.get("pending")) if isinstance(item, dict)
    ]
    paired = [
        item for item in _object_list(result_payload.get("paired")) if isinstance(item, dict)
    ]
    paired_by_device_id = {
        device_id: paired_device
        for paired_device in paired
        if (device_id := _optional_cli_string(paired_device.get("deviceId"))) is not None
    }
    warnings = [
        warning
        for pending_request in pending
        if (
            warning := _doctor_pending_pairing_warning(
                pending_request,
                paired_by_device_id.get(
                    _optional_cli_string(pending_request.get("deviceId")) or ""
                ),
            )
        )
        is not None
    ]
    for paired_device in paired:
        warnings.extend(_doctor_paired_record_warnings(paired_device))
    warnings.extend(_doctor_local_device_auth_warnings(paired, data_dir))
    return {
        **base_payload,
        "status": "warning" if warnings else "ok",
        "summary": (
            "Device pairing has pending requests."
            if warnings
            else "Device pairing has no pending requests."
        ),
        "checked": True,
        "pendingCount": len(pending),
        "pairedCount": len(paired),
        "warnings": warnings,
    }


async def _with_doctor_device_pairing_payload(
    payload: dict[str, object],
    gateway_node_methods: object | None,
    data_dir: Path | None = None,
) -> dict[str, object]:
    device_pairing = await _build_doctor_device_pairing_payload(
        gateway_node_methods,
        data_dir=data_dir,
    )
    next_payload = dict(payload)
    next_payload["devicePairing"] = device_pairing
    warnings = [
        str(warning)
        for warning in _object_list(device_pairing.get("warnings"))
    ]
    return _with_doctor_added_warnings(next_payload, warnings)


def _doctor_config_snapshot(config_service: object | None) -> dict[str, object]:
    build_snapshot = getattr(config_service, "build_snapshot", None)
    if not callable(build_snapshot):
        return {}
    try:
        snapshot = build_snapshot()
    except Exception:
        return {}
    return snapshot if isinstance(snapshot, dict) else {}


_OPENAI_CODEX_PROVIDER_ID = "openai-codex"
_OPENAI_CODEX_OPENAI_BASE_URL = "https://api.openai.com/v1"
_OPENAI_CODEX_LEGACY_APIS = {"openai-responses", "openai-completions"}


def _normalize_codex_override_base_url(value: object) -> str | None:
    if not isinstance(value, str):
        return None
    normalized = value.strip().rstrip("/")
    return normalized or None


def _is_legacy_codex_transport_shape(
    value: object,
    *,
    inherited_base_url: object | None = None,
) -> bool:
    if not isinstance(value, dict):
        return False
    api = _optional_cli_string(value.get("api"))
    if api not in _OPENAI_CODEX_LEGACY_APIS:
        return False
    base_url = _normalize_codex_override_base_url(
        value.get("baseUrl", inherited_base_url)
    )
    return base_url is None or base_url == _OPENAI_CODEX_OPENAI_BASE_URL


def _has_legacy_codex_transport_override(provider_override: object) -> bool:
    if not isinstance(provider_override, dict):
        return False
    if _is_legacy_codex_transport_shape(provider_override):
        return True
    models = provider_override.get("models")
    if not isinstance(models, list):
        return False
    inherited_base_url = provider_override.get("baseUrl")
    return any(
        _is_legacy_codex_transport_shape(model, inherited_base_url=inherited_base_url)
        for model in models
    )


def _config_has_codex_oauth_profile(snapshot: dict[str, object]) -> bool:
    auth = snapshot.get("auth")
    auth_payload = auth if isinstance(auth, dict) else {}
    raw_profiles = auth_payload.get("profiles")
    if isinstance(raw_profiles, dict):
        profiles: list[object] = list(raw_profiles.values())
    elif isinstance(raw_profiles, list):
        profiles = list(raw_profiles)
    else:
        profiles = []
    return any(
        isinstance(profile, dict)
        and _optional_cli_string(profile.get("provider")) == _OPENAI_CODEX_PROVIDER_ID
        and _optional_cli_string(profile.get("mode")) == "oauth"
        for profile in profiles
    )


def _doctor_default_agent_auth_store_path(
    snapshot: dict[str, object],
    data_dir: Path,
) -> Path:
    agents = snapshot.get("agents")
    agents_payload = agents if isinstance(agents, dict) else {}
    raw_entries = agents_payload.get("list")
    entries = [entry for entry in raw_entries if isinstance(entry, dict)] if isinstance(
        raw_entries,
        list,
    ) else []
    entry = next((item for item in entries if item.get("default") is True), None)
    if entry is None and entries:
        entry = entries[0]
    if entry is None:
        agent_id = "main"
        raw_agent_dir: object = None
    else:
        agent_id = (_optional_cli_string(entry.get("id")) or "main").lower()
        raw_agent_dir = entry.get("agentDir")
    if isinstance(raw_agent_dir, str) and raw_agent_dir.strip():
        agent_dir = Path(raw_agent_dir.strip()).expanduser()
        if not agent_dir.is_absolute():
            agent_dir = data_dir / agent_dir
    else:
        agent_dir = data_dir / "agents" / agent_id / "agent"
    return agent_dir / "auth-profiles.json"


def _stored_has_codex_oauth_profile(
    snapshot: dict[str, object],
    data_dir: Path | None,
) -> bool:
    if data_dir is None:
        return False
    store = _read_cli_json_object(_doctor_default_agent_auth_store_path(snapshot, data_dir)) or {}
    raw_profiles = store.get("profiles")
    profiles = raw_profiles.values() if isinstance(raw_profiles, dict) else []
    return any(
        isinstance(profile, dict)
        and _optional_cli_string(profile.get("provider")) == _OPENAI_CODEX_PROVIDER_ID
        and _optional_cli_string(profile.get("type")) == "oauth"
        for profile in profiles
    )


def _build_codex_provider_override_warning(provider_override: object) -> str:
    lines = [
        (
            f"- models.providers.{_OPENAI_CODEX_PROVIDER_ID} contains a legacy "
            "transport override while Codex OAuth is configured."
        ),
        "- Older OpenAI transport settings can shadow the built-in Codex OAuth provider path.",
    ]
    if isinstance(provider_override, dict):
        api = _optional_cli_string(provider_override.get("api"))
        if api is not None:
            lines.append(f"- models.providers.{_OPENAI_CODEX_PROVIDER_ID}.api={api}")
        base_url = _optional_cli_string(provider_override.get("baseUrl"))
        if base_url is not None:
            lines.append(f"- models.providers.{_OPENAI_CODEX_PROVIDER_ID}.baseUrl={base_url}")
    lines.extend(
        [
            (
                "- Remove or rewrite the legacy transport override to restore the built-in "
                "Codex OAuth provider path after recent fixes."
            ),
            (
                "- Custom proxies and header-only overrides can stay; this warning only "
                "targets old OpenAI transport settings."
            ),
        ]
    )
    return "\n".join(lines)


def _dict_config(value: object) -> dict[str, object]:
    return value if isinstance(value, dict) else {}


def _build_doctor_gateway_config_payload(
    config_service: object | None,
) -> dict[str, object] | None:
    snapshot = _doctor_config_snapshot(config_service)
    raw_gateway = snapshot.get("gateway")
    if not isinstance(raw_gateway, dict):
        return None
    gateway = _dict_config(raw_gateway)
    if _optional_cli_string(gateway.get("mode")) is not None:
        return None
    if "bind" in gateway:
        return None
    warning = "\n".join(
        [
            "gateway.mode is unset; gateway start will be blocked.",
            "Fix: run openclaw configure and set Gateway mode (local/remote).",
            "Or set directly: openclaw config set gateway.mode local",
        ]
    )
    return {
        "status": "warning",
        "summary": "gateway.mode is unset; gateway start will be blocked.",
        "source": "openzues-native",
        "openClawContribution": "doctor:gateway-config",
        "reason": "missing_gateway_mode",
        "warnings": [warning],
    }


def _with_doctor_gateway_config_payload(
    payload: dict[str, object],
    config_service: object | None,
) -> dict[str, object]:
    gateway_config = _build_doctor_gateway_config_payload(config_service)
    if gateway_config is None:
        return payload
    next_payload = dict(payload)
    next_payload["gatewayConfig"] = gateway_config
    warnings = [
        str(warning)
        for warning in _object_list(gateway_config.get("warnings"))
    ]
    return _with_doctor_added_warnings(next_payload, warnings)


_GATEWAY_RUNTIME_NODE_MIGRATION_CODES = {
    "gateway-runtime-bun",
    "gateway-runtime-node-version-manager",
}
_GATEWAY_RUNTIME_MISSING_SYSTEM_NODE_WARNING = (
    "System Node 22 LTS (22.14+) or Node 24 not found. Install via "
    "Homebrew/apt/choco and rerun doctor to migrate off Bun/version managers."
)


def _doctor_node_version_tuple(version: str | None) -> tuple[int, int, int] | None:
    if version is None:
        return None
    match = re.search(r"(\d+)\.(\d+)\.(\d+)", version)
    if match is None:
        return None
    return (int(match.group(1)), int(match.group(2)), int(match.group(3)))


def _doctor_node_version_supported(version: str | None) -> bool:
    parsed = _doctor_node_version_tuple(version)
    if parsed is None:
        return False
    return parsed >= (22, 14, 0)


def _resolve_doctor_gateway_system_node_info() -> dict[str, object] | None:
    node_path = shutil.which("node")
    if node_path is None:
        return None
    version: str | None = None
    try:
        completed = subprocess.run(
            [node_path, "--version"],
            capture_output=True,
            check=False,
            text=True,
            timeout=5,
        )
    except (OSError, subprocess.SubprocessError):
        completed = None
    if completed is not None and completed.returncode == 0:
        version = _optional_cli_string(completed.stdout)
    return {
        "path": node_path,
        "version": version.lstrip("v") if version is not None else None,
        "supported": _doctor_node_version_supported(version),
    }


def _doctor_gateway_service_audit_issues(
    snapshot: dict[str, object],
) -> list[dict[str, object]]:
    gateway = _dict_config(snapshot.get("gateway"))
    containers = (
        gateway.get("serviceAudit"),
        snapshot.get("gatewayServiceAudit"),
        snapshot.get("serviceAudit"),
    )
    issues: list[dict[str, object]] = []
    for container in containers:
        if isinstance(container, dict):
            raw_issues = container.get("issues")
        else:
            raw_issues = container
        if not isinstance(raw_issues, list):
            continue
        for issue in raw_issues:
            if isinstance(issue, dict):
                issues.append(dict(issue))
    return issues


def _doctor_gateway_needs_node_runtime_migration(issues: Sequence[object]) -> bool:
    return any(
        isinstance(issue, dict)
        and _optional_cli_string(issue.get("code")) in _GATEWAY_RUNTIME_NODE_MIGRATION_CODES
        for issue in issues
    )


def _doctor_gateway_system_node_warning(
    system_node: dict[str, object] | None,
) -> str | None:
    if system_node is None or system_node.get("supported") is True:
        return None
    version = _optional_cli_string(system_node.get("version")) or "unknown"
    path = _optional_cli_string(system_node.get("path")) or "unknown"
    return (
        f"System Node {version} at {path} is below the required Node 22.14+. "
        "Install Node 24 (recommended) or Node 22 LTS from nodejs.org or Homebrew."
    )


def _build_doctor_gateway_runtime_payload(
    config_service: object | None,
) -> dict[str, object] | None:
    snapshot = _doctor_config_snapshot(config_service)
    issues = _doctor_gateway_service_audit_issues(snapshot)
    if not _doctor_gateway_needs_node_runtime_migration(issues):
        return None
    system_node = _resolve_doctor_gateway_system_node_info()
    if isinstance(system_node, dict) and system_node.get("supported") is True:
        return None
    warnings = [
        warning
        for warning in (
            _doctor_gateway_system_node_warning(system_node),
            _GATEWAY_RUNTIME_MISSING_SYSTEM_NODE_WARNING,
        )
        if warning is not None
    ]
    return {
        "status": "warning",
        "summary": "Gateway runtime needs a supported system Node before migration.",
        "source": "openzues-native",
        "openClawContribution": "doctor:gateway-runtime",
        "reason": "node_runtime_migration_requires_system_node",
        "needsNodeRuntimeMigration": True,
        "systemNode": system_node,
        "issues": issues,
        "warnings": warnings,
    }


def _with_doctor_gateway_runtime_payload(
    payload: dict[str, object],
    config_service: object | None,
) -> dict[str, object]:
    gateway_runtime = _build_doctor_gateway_runtime_payload(config_service)
    if gateway_runtime is None:
        return payload
    next_payload = dict(payload)
    next_payload["gatewayRuntime"] = gateway_runtime
    warnings = [
        str(warning)
        for warning in _object_list(gateway_runtime.get("warnings"))
    ]
    return _with_doctor_added_warnings(next_payload, warnings)


_RUNTIME_BRIDGE_NATIVE_PROVIDER_KINDS = {
    "bluebubbles",
    "discord",
    "googlechat",
    "line",
    "matrix",
    "mattermost",
    "msteams",
    "nextcloud-talk",
    "irc",
    "signal",
    "slack",
    "synology-chat",
    "telegram",
    "twitch",
    "whatsapp",
    "zalo",
}
_RUNTIME_BRIDGE_PROVIDER_EVENTS = {"gateway/send", "gateway/poll"}


def _runtime_bridge_command_available(command: str | None) -> bool:
    normalized = _optional_cli_string(command)
    if normalized is None:
        return False
    candidate = Path(normalized).expanduser()
    if candidate.is_absolute() and candidate.exists():
        return True
    return shutil.which(normalized) is not None


def _runtime_bridge_field(value: object, *names: str) -> object:
    if isinstance(value, Mapping):
        for name in names:
            if name in value:
                return value[name]
        return None
    for name in names:
        if hasattr(value, name):
            return getattr(value, name)
    return None


def _runtime_bridge_bool_field(
    value: object,
    *names: str,
    default: bool | None = None,
) -> bool | None:
    raw = _runtime_bridge_field(value, *names)
    if isinstance(raw, bool):
        return raw
    return default


def _runtime_bridge_route_events(route: object) -> list[str]:
    raw_events = _runtime_bridge_field(route, "events", "eventTypes", "event_types")
    if isinstance(raw_events, str):
        return [raw_events]
    if isinstance(raw_events, Sequence) and not isinstance(raw_events, (str, bytes)):
        return [
            event
            for item in raw_events
            if (event := _optional_cli_string(item)) is not None
        ]
    return []


def _runtime_bridge_route_has_secret(route: object) -> bool | None:
    explicit = _runtime_bridge_bool_field(route, "has_secret", "hasSecret")
    if explicit is not None:
        return explicit
    for key in (
        "secret_preview",
        "secretPreview",
        "secret_token",
        "secretToken",
        "vault_secret_id",
        "vaultSecretId",
    ):
        if _runtime_bridge_field(route, key) not in (None, "", [], {}):
            return True
    return None


def _runtime_bridge_conversation_target(route: object) -> dict[str, object] | None:
    target = _runtime_bridge_field(
        route,
        "conversation_target",
        "conversationTarget",
    )
    if target is None:
        return None
    if hasattr(target, "model_dump"):
        dumped = target.model_dump(mode="json")
        return dumped if isinstance(dumped, dict) else None
    if isinstance(target, Mapping):
        return dict(target)
    return None


def _runtime_bridge_native_provider_route_entry(
    route: object,
) -> dict[str, object] | None:
    kind = _optional_cli_string(_runtime_bridge_field(route, "kind"))
    normalized_kind = kind.lower() if kind is not None else None
    if normalized_kind not in _RUNTIME_BRIDGE_NATIVE_PROVIDER_KINDS:
        return None
    events = _runtime_bridge_route_events(route)
    if events and not _RUNTIME_BRIDGE_PROVIDER_EVENTS.intersection(events):
        return None
    enabled = _runtime_bridge_bool_field(route, "enabled", default=True)
    has_secret = _runtime_bridge_route_has_secret(route)
    conversation_target = _runtime_bridge_conversation_target(route)
    issues: list[str] = []
    if enabled is not True:
        issues.append("disabled")
    if has_secret is False:
        issues.append("missing_secret")
    if conversation_target is None:
        issues.append("missing_conversation_target")
    status = "ready" if not issues else "warning"
    entry: dict[str, object] = {
        "id": _runtime_bridge_field(route, "id"),
        "name": _runtime_bridge_field(route, "name"),
        "kind": normalized_kind,
        "events": events,
        "enabled": enabled is True,
        "status": status,
        "issues": issues,
    }
    if has_secret is not None:
        entry["hasSecret"] = has_secret
    if conversation_target is not None:
        entry["conversationTarget"] = conversation_target
    return entry


async def _build_doctor_runtime_bridge_provider_routes_payload(
    ops_mesh: object | None,
) -> dict[str, object]:
    list_routes = getattr(ops_mesh, "list_notification_route_views", None)
    if not callable(list_routes):
        return {
            "status": "unavailable",
            "summary": "Provider route inventory is unavailable.",
            "nativeCount": 0,
            "routes": [],
        }
    try:
        raw_routes = await list_routes()
    except Exception as exc:  # pragma: no cover - defensive adapter boundary
        return {
            "status": "unavailable",
            "summary": f"Provider route inventory could not be read: {exc}",
            "nativeCount": 0,
            "routes": [],
        }
    routes = [
        entry
        for route in raw_routes
        if (entry := _runtime_bridge_native_provider_route_entry(route)) is not None
    ]
    ready_count = sum(1 for route in routes if route.get("status") == "ready")
    status = "ok" if ready_count == len(routes) else "warning"
    if not routes:
        summary = "No native provider routes are configured for gateway send or poll."
    else:
        summary = (
            f"{ready_count}/{len(routes)} native provider route"
            f"{'s are' if len(routes) != 1 else ' is'} ready."
        )
    return {
        "status": status,
        "summary": summary,
        "nativeCount": len(routes),
        "readyCount": ready_count,
        "routes": routes,
    }


def _build_doctor_runtime_bridge_plugin_executors_payload(
    services: object,
) -> dict[str, object]:
    specs = _plugin_runtime_specs_from_services(services)
    tools = [
        {
            "tool": spec.tool,
            "pluginId": spec.plugin_id,
            "pluginName": spec.plugin_name,
            "ownerOnly": spec.owner_only,
            "optional": spec.optional,
            "source": spec.source,
        }
        for spec in specs
    ]
    owner_only_count = sum(1 for spec in specs if spec.owner_only)
    return {
        "status": "ok",
        "count": len(tools),
        "ownerOnlyCount": owner_only_count,
        "tools": tools,
    }


def _plugin_runtime_activation_payload(
    plugin_rows: list[object],
    services: object,
) -> dict[str, object]:
    manifest_plugins = [plugin for plugin in plugin_rows if isinstance(plugin, Mapping)]
    active_manifest_plugins = [
        plugin for plugin in manifest_plugins if _plugin_row_runtime_activated(plugin)
    ]
    manifest_tool_plugins: list[dict[str, object]] = []
    unavailable_tool_plugins: list[dict[str, object]] = []
    evaluated_tool_availability = False
    config_snapshot = _doctor_config_snapshot(getattr(services, "gateway_config", None))
    for plugin in active_manifest_plugins:
        plugin_id = _optional_cli_string(plugin.get("id"))
        if plugin_id is None:
            continue
        contracts = plugin.get("contracts")
        contract_payload = contracts if isinstance(contracts, dict) else {}
        tools = _plugin_manifest_string_list(contract_payload.get("tools"))
        if tools:
            available_tools, unavailable_tools, availability_evaluated = (
                _plugin_manifest_tool_availability(
                    plugin,
                    tools,
                    config_snapshot=config_snapshot,
                    env=os.environ,
                )
            )
            evaluated_tool_availability = (
                evaluated_tool_availability or availability_evaluated
            )
            entry: dict[str, object] = {"pluginId": plugin_id, "tools": tools}
            if availability_evaluated:
                if unavailable_tools and available_tools:
                    entry["availability"] = "partial"
                elif unavailable_tools:
                    entry["availability"] = "unavailable"
                else:
                    entry["availability"] = "available"
                if unavailable_tools:
                    entry["unavailableTools"] = unavailable_tools
                    unavailable_tool_plugins.append(
                        {"pluginId": plugin_id, "tools": unavailable_tools}
                    )
            manifest_tool_plugins.append(entry)
    runtime_tool_map: dict[str, list[str]] = {}
    runtime_text_transform_plugins: list[dict[str, object]] = []
    for spec in _plugin_runtime_specs_from_services(
        services,
        plugin_rows=active_manifest_plugins,
        config_snapshot=config_snapshot,
        runtime_text_transform_plugins=runtime_text_transform_plugins,
    ):
        plugin_id = _optional_cli_string(spec.plugin_id)
        if plugin_id is None:
            continue
        runtime_tool_map.setdefault(plugin_id, []).append(spec.tool)
    runtime_executor_plugins = [
        {"pluginId": plugin_id, "tools": sorted(_dedupe_cli_strings(tools))}
        for plugin_id, tools in sorted(runtime_tool_map.items())
    ]
    missing_executor_plugins: list[dict[str, object]] = []
    for entry in manifest_tool_plugins:
        plugin_id = _optional_cli_string(entry.get("pluginId"))
        if plugin_id is None:
            continue
        unavailable_tool_set = set(_plugin_manifest_string_list(entry.get("unavailableTools")))
        manifest_tools = _plugin_manifest_string_list(entry.get("tools"))
        available_tools = [tool for tool in manifest_tools if tool not in unavailable_tool_set]
        runtime_tools = set(runtime_tool_map.get(plugin_id, []))
        missing_tools = [tool for tool in available_tools if tool not in runtime_tools]
        if missing_tools:
            missing_executor_plugins.append({"pluginId": plugin_id, "tools": missing_tools})
    if not manifest_tool_plugins:
        status = "ok"
    elif missing_executor_plugins and runtime_executor_plugins:
        status = "partial"
    elif missing_executor_plugins:
        status = "metadata_only"
    elif unavailable_tool_plugins and not runtime_executor_plugins:
        status = "unavailable"
    else:
        status = "ok"
    payload: dict[str, object] = {
        "status": status,
        "manifestToolPlugins": manifest_tool_plugins,
        "runtimeExecutorPlugins": runtime_executor_plugins,
        "missingExecutorPlugins": missing_executor_plugins,
    }
    if evaluated_tool_availability:
        payload["unavailableToolPlugins"] = unavailable_tool_plugins
    activation_plans = _plugin_manifest_activation_plans(plugin_rows)
    if activation_plans:
        payload["activationPlans"] = activation_plans
    if runtime_text_transform_plugins:
        payload["runtimeTextTransformPlugins"] = runtime_text_transform_plugins
    configured_channel_plan = resolve_configured_channel_plugin_plan(
        plugins=manifest_plugins,
        config=config_snapshot,
    )
    if configured_channel_plan.get("entries"):
        payload["configuredChannelPlugins"] = configured_channel_plan
    return payload


def _plugin_row_runtime_activated(plugin: Mapping[str, object]) -> bool:
    return _optional_cli_string(plugin.get("status")) == "loaded"


def _plugin_manifest_tool_availability(
    plugin: Mapping[str, object],
    tools: Sequence[str],
    *,
    config_snapshot: Mapping[str, object],
    env: Mapping[str, str],
) -> tuple[list[str], list[str], bool]:
    tool_metadata = plugin.get("toolMetadata")
    metadata_by_tool = tool_metadata if isinstance(tool_metadata, Mapping) else {}
    available_tools: list[str] = []
    unavailable_tools: list[str] = []
    evaluated = False
    for tool in tools:
        metadata = metadata_by_tool.get(tool)
        if not isinstance(metadata, Mapping):
            available_tools.append(tool)
            continue
        evaluated = True
        if _plugin_manifest_tool_metadata_available(
            plugin,
            metadata,
            config_snapshot=config_snapshot,
            env=env,
        ):
            available_tools.append(tool)
        else:
            unavailable_tools.append(tool)
    return available_tools, unavailable_tools, evaluated


def _plugin_manifest_tool_metadata_available(
    plugin: Mapping[str, object],
    metadata: Mapping[str, object],
    *,
    config_snapshot: Mapping[str, object],
    env: Mapping[str, str],
) -> bool:
    config_signals = metadata.get("configSignals")
    for signal in config_signals if isinstance(config_signals, list) else []:
        if isinstance(signal, Mapping) and _plugin_manifest_config_signal_passes(
            signal,
            config_snapshot=config_snapshot,
            env=env,
        ):
            return True
    for signal in _plugin_manifest_tool_auth_signals(metadata):
        provider = _optional_cli_string(signal.get("provider"))
        if provider is None:
            continue
        if not _plugin_manifest_provider_base_url_guard_passes(
            signal.get("providerBaseUrl"),
            config_snapshot=config_snapshot,
        ):
            continue
        if _plugin_manifest_has_non_empty_env_candidate(
            env,
            _plugin_manifest_setup_provider_env_vars(plugin, provider),
        ):
            return True
    return False


def _plugin_manifest_tool_auth_signals(
    metadata: Mapping[str, object],
) -> list[Mapping[str, object]]:
    auth_signals = metadata.get("authSignals")
    signals: list[Mapping[str, object]] = []
    if isinstance(auth_signals, list):
        for signal in auth_signals:
            if isinstance(signal, Mapping):
                signals.append(signal)
        return signals
    for key in ("authProviders", "aliases"):
        for provider in _plugin_manifest_string_list(metadata.get(key)):
            signals.append({"provider": provider})
    return signals


def _plugin_manifest_config_signal_passes(
    signal: Mapping[str, object],
    *,
    config_snapshot: Mapping[str, object],
    env: Mapping[str, str],
) -> bool:
    del env
    root_path = _optional_cli_string(signal.get("rootPath"))
    if root_path is None:
        return False
    effective_config = _plugin_read_path(config_snapshot, root_path)
    if not isinstance(effective_config, Mapping):
        return False
    overlay_path = _optional_cli_string(signal.get("overlayPath"))
    overlay = _plugin_read_path(effective_config, overlay_path)
    if isinstance(overlay, Mapping):
        effective_config = {**dict(effective_config), **dict(overlay)}
    mode_signal = signal.get("mode")
    if isinstance(mode_signal, Mapping) and not _plugin_manifest_config_mode_passes(
        effective_config,
        mode_signal,
    ):
        return False
    required = _plugin_manifest_string_list(signal.get("required"))
    for path_value in required:
        if not _plugin_has_configured_value(_plugin_read_path(effective_config, path_value)):
            return False
    required_any = _plugin_manifest_string_list(signal.get("requiredAny"))
    if required_any and not any(
        _plugin_has_configured_value(_plugin_read_path(effective_config, path_value))
        for path_value in required_any
    ):
        return False
    return bool(required or required_any or mode_signal)


def _plugin_manifest_config_mode_passes(
    config: Mapping[str, object],
    mode_signal: Mapping[str, object],
) -> bool:
    mode_path = _optional_cli_string(mode_signal.get("path")) or "mode"
    mode = _optional_cli_string(_plugin_read_path(config, mode_path)) or _optional_cli_string(
        mode_signal.get("default")
    )
    if mode is None:
        return False
    allowed = _plugin_manifest_string_list(mode_signal.get("allowed"))
    if allowed and mode not in allowed:
        return False
    disallowed = _plugin_manifest_string_list(mode_signal.get("disallowed"))
    return mode not in disallowed


def _plugin_manifest_provider_base_url_guard_passes(
    value: object,
    *,
    config_snapshot: Mapping[str, object],
) -> bool:
    if not isinstance(value, Mapping):
        return True
    provider = _optional_cli_string(value.get("provider"))
    allowed_base_urls = _plugin_manifest_string_list(value.get("allowedBaseUrls"))
    if provider is None or not allowed_base_urls:
        return True
    provider_config = _plugin_read_path(
        config_snapshot,
        f"models.providers.{provider}",
    )
    raw_base_url = None
    if isinstance(provider_config, Mapping):
        raw_base_url = _optional_cli_string(provider_config.get("baseUrl"))
    base_url = raw_base_url or _optional_cli_string(value.get("defaultBaseUrl"))
    if base_url is None:
        return False
    normalized = base_url.rstrip("/")
    return any(allowed.rstrip("/") == normalized for allowed in allowed_base_urls)


def _plugin_manifest_setup_provider_env_vars(
    plugin: Mapping[str, object],
    provider: str,
) -> list[str]:
    setup = plugin.get("setup")
    if isinstance(setup, Mapping):
        providers = setup.get("providers")
        for entry in providers if isinstance(providers, list) else []:
            if not isinstance(entry, Mapping):
                continue
            if _optional_cli_string(entry.get("id")) == provider:
                env_vars = _plugin_manifest_string_list(entry.get("envVars"))
                if env_vars:
                    return env_vars
    provider_auth_env_vars = plugin.get("providerAuthEnvVars")
    if isinstance(provider_auth_env_vars, Mapping):
        return _plugin_manifest_string_list(provider_auth_env_vars.get(provider))
    return []


def _plugin_manifest_has_non_empty_env_candidate(
    env: Mapping[str, str],
    env_vars: Sequence[str],
) -> bool:
    return any(bool(env.get(env_var, "").strip()) for env_var in env_vars if env_var.strip())


def _plugin_read_path(root: object, path_value: str | None) -> object:
    if path_value is None or not path_value.strip():
        return root
    current = root
    for raw_segment in path_value.split("."):
        segment = raw_segment.strip()
        if not segment:
            return None
        if not isinstance(current, Mapping) or segment not in current:
            return None
        current = current[segment]
    return current


def _plugin_has_configured_value(value: object) -> bool:
    if value is None:
        return False
    if isinstance(value, str):
        return bool(value.strip())
    if isinstance(value, list):
        return bool(value)
    if isinstance(value, Mapping):
        return bool(value)
    return True


def _plugin_manifest_activation_plans(
    plugin_rows: list[object],
) -> list[dict[str, object]]:
    return resolve_manifest_activation_plans(
        plugins=[plugin for plugin in plugin_rows if isinstance(plugin, Mapping)]
    )


def _build_doctor_runtime_bridge_acp_payload(
    config_service: object | None,
    gateway_node_methods: object | None,
) -> dict[str, object]:
    snapshot = _doctor_config_snapshot(config_service)
    acp_config = _dict_config(snapshot.get("acp"))
    enabled = acp_config.get("enabled") is True
    spawn_service = None
    if gateway_node_methods is not None:
        spawn_service = (
            getattr(gateway_node_methods, "_acp_spawn_service", None)
            or getattr(gateway_node_methods, "acp_spawn_service", None)
        )
    if enabled:
        status = "ok" if spawn_service is not None else "warning"
    else:
        status = "disabled" if acp_config else "not_configured"
    return {
        "status": status,
        "enabled": enabled,
        "spawnService": "registered" if spawn_service is not None else "unregistered",
    }


def _build_doctor_runtime_bridge_codex_app_server_payload(
    manager: object | None,
) -> dict[str, object]:
    command = (
        _optional_cli_string(getattr(manager, "default_stdio_command", None))
        or "codex"
    )
    args = (
        _optional_cli_string(getattr(manager, "default_stdio_args", None))
        or "app-server"
    )
    configured = "app-server" in args.split() or "app-server" in args
    available = _runtime_bridge_command_available(command)
    status = "ok" if configured and available else "warning"
    return {
        "status": status,
        "command": command,
        "args": args,
        "configured": configured,
        "available": available,
        "platform": sys.platform,
        "windowsFirst": True,
    }


def _doctor_runtime_bridge_status(sections: Sequence[dict[str, object]]) -> str:
    warning_statuses = {"error", "unavailable", "warning", "warn"}
    return (
        "warning"
        if any(section.get("status") in warning_statuses for section in sections)
        else "ok"
    )


async def _build_doctor_runtime_bridge_payload(
    services: object,
) -> dict[str, object]:
    codex_app_server = _build_doctor_runtime_bridge_codex_app_server_payload(
        getattr(services, "manager", None)
    )
    sandbox = _build_doctor_sandbox_payload(getattr(services, "gateway_config", None))
    provider_routes = await _build_doctor_runtime_bridge_provider_routes_payload(
        getattr(services, "ops_mesh", None)
    )
    plugin_executors = _build_doctor_runtime_bridge_plugin_executors_payload(services)
    acp = _build_doctor_runtime_bridge_acp_payload(
        getattr(services, "gateway_config", None),
        getattr(services, "gateway_node_methods", None),
    )
    sections = [
        codex_app_server,
        sandbox,
        provider_routes,
        plugin_executors,
        acp,
    ]
    status = _doctor_runtime_bridge_status(sections)
    return {
        "status": status,
        "summary": (
            "Native runtime bridge posture is ready."
            if status == "ok"
            else "Native runtime bridge posture has unavailable or degraded checks."
        ),
        "source": "openzues-native",
        "openClawContribution": "doctor:runtime-bridge",
        "windowsFirst": True,
        "codexAppServer": codex_app_server,
        "sandbox": sandbox,
        "providerRoutes": provider_routes,
        "pluginExecutors": plugin_executors,
        "acp": acp,
        "warnings": [],
    }


async def _with_doctor_runtime_bridge_payload(
    payload: dict[str, object],
    services: object,
) -> dict[str, object]:
    next_payload = dict(payload)
    next_payload["runtimeBridge"] = await _build_doctor_runtime_bridge_payload(services)
    return next_payload


