def _openzues_package_root() -> Path:
    try:
        return Path(__file__).resolve(strict=False).parents[2]
    except IndexError:  # pragma: no cover - defensive fallback for unusual loaders
        return Path.cwd()


def _doctor_path_exists(path: Path) -> bool:
    try:
        return path.exists()
    except OSError:
        return False


def _doctor_package_distribution_check(
    *,
    key: str,
    status: str,
    detail: str,
    path: Path | None = None,
) -> dict[str, object]:
    payload: dict[str, object] = {
        "key": key,
        "status": status,
    }
    if path is not None:
        payload["path"] = str(path)
    payload["detail"] = detail
    return payload


def _doctor_normalize_package_dist_path(path: str) -> str:
    return path.replace("\\", "/")


def _doctor_read_package_dist_inventory(
    inventory_path: Path,
) -> tuple[list[str] | None, str | None]:
    if not _doctor_path_exists(inventory_path):
        return None, None
    warning = (
        "Invalid package dist inventory at "
        f"{_PACKAGE_DIST_INVENTORY_RELATIVE_PATH.as_posix()}"
    )
    try:
        parsed = json.loads(inventory_path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return None, warning
    if not isinstance(parsed, list) or any(not isinstance(entry, str) for entry in parsed):
        return None, warning
    files = sorted({_doctor_normalize_package_dist_path(entry) for entry in parsed})
    return files, None


def _doctor_is_externalized_bundled_extension_dist_path(
    relative_path: str,
    externalized_extension_ids: set[str],
) -> bool:
    parts = relative_path.split("/")
    return (
        len(parts) >= 3
        and parts[0] == "dist"
        and parts[1] == "extensions"
        and parts[2] in externalized_extension_ids
    )


def _doctor_is_publishable_externalized_manifest(value: object) -> bool:
    if not isinstance(value, Mapping):
        return False
    openclaw = value.get("openclaw")
    if not isinstance(openclaw, Mapping):
        return False
    bundle = openclaw.get("bundle")
    if isinstance(bundle, Mapping) and bundle.get("includeInCore") is True:
        return False
    release = openclaw.get("release")
    if not isinstance(release, Mapping):
        return False
    return release.get("publishToNpm") is True or release.get("publishToClawHub") is True


def _doctor_collect_externalized_bundled_extension_ids(root: Path) -> set[str]:
    extensions_path = root / "extensions"
    if not _doctor_path_exists(extensions_path):
        return set()
    extension_ids: set[str] = set()
    try:
        extension_entries = list(extensions_path.iterdir())
    except OSError:
        return set()
    for extension_entry in extension_entries:
        try:
            if not extension_entry.is_dir() or extension_entry.is_symlink():
                continue
            parsed = json.loads(
                (extension_entry / "package.json").read_text(encoding="utf-8")
            )
        except (OSError, ValueError):
            continue
        if _doctor_is_publishable_externalized_manifest(parsed):
            extension_ids.add(extension_entry.name)
    return extension_ids


def _doctor_is_packaged_dist_file(
    relative_path: str,
    externalized_extension_ids: set[str],
) -> bool:
    if relative_path == _PACKAGE_DIST_INVENTORY_RELATIVE_PATH.as_posix():
        return False
    if _doctor_is_externalized_bundled_extension_dist_path(
        relative_path,
        externalized_extension_ids,
    ):
        return False
    if relative_path in _PACKAGE_DIST_LOCAL_BUILD_METADATA_PATHS:
        return False
    if relative_path.startswith(_PACKAGE_DIST_OMITTED_QA_EXTENSION_PREFIXES):
        return False
    if relative_path.startswith(_PACKAGE_DIST_OMITTED_PRIVATE_QA_PLUGIN_SDK_PREFIXES):
        return False
    if relative_path in _PACKAGE_DIST_OMITTED_PRIVATE_QA_PLUGIN_SDK_FILES:
        return False
    if relative_path.startswith(_PACKAGE_DIST_OMITTED_PRIVATE_QA_DIST_PREFIXES):
        return False
    if relative_path.endswith(".map"):
        return False
    if relative_path == "dist/plugin-sdk/.tsbuildinfo":
        return False
    parts = relative_path.split("/")
    return not (
        len(parts) >= 3
        and parts[0] == "dist"
        and parts[1] == "extensions"
        and (
            parts[2].lower() == "node_modules"
            or (len(parts) >= 4 and parts[3].lower() == "node_modules")
        )
    )


def _doctor_collect_package_dist_files(root: Path) -> list[str]:
    dist_path = root / "dist"
    if not _doctor_path_exists(dist_path):
        return []
    externalized_extension_ids = _doctor_collect_externalized_bundled_extension_ids(root)
    files: list[str] = []
    for path in dist_path.rglob("*"):
        try:
            if not path.is_file() or path.is_symlink():
                continue
        except OSError:
            continue
        relative_path = _doctor_normalize_package_dist_path(path.relative_to(root).as_posix())
        if _doctor_is_packaged_dist_file(relative_path, externalized_extension_ids):
            files.append(relative_path)
    return sorted(set(files))


def _doctor_package_dist_unsafe_path_warnings(root: Path) -> list[str]:
    dist_path = root / "dist"
    if not _doctor_path_exists(dist_path):
        return []
    warnings: list[str] = []
    for path in dist_path.rglob("*"):
        try:
            if path.is_symlink():
                relative_path = _doctor_normalize_package_dist_path(
                    path.relative_to(root).as_posix()
                )
                warnings.append(f"Unsafe package dist path: {relative_path}")
        except OSError:
            continue
    return sorted(set(warnings))


def _doctor_is_install_stage_dir_name(value: str) -> bool:
    lower = value.lower()
    return lower == ".openclaw-install-stage" or lower.startswith(
        ".openclaw-install-stage-"
    )


def _doctor_collect_legacy_package_dist_staging_debris(root: Path) -> list[str]:
    try:
        package_root_entries = list(root.iterdir())
    except OSError:
        return []
    debris: list[str] = []
    for dist_dir in package_root_entries:
        try:
            if (
                not dist_dir.is_dir()
                or dist_dir.is_symlink()
                or dist_dir.name.lower() != "dist"
            ):
                continue
            dist_entries = list(dist_dir.iterdir())
        except OSError:
            continue
        for dist_entry in dist_entries:
            try:
                if (
                    not dist_entry.is_dir()
                    or dist_entry.is_symlink()
                    or dist_entry.name.lower() != "extensions"
                ):
                    continue
                extension_entries = list(dist_entry.iterdir())
            except OSError:
                continue
            for extension_entry in extension_entries:
                try:
                    if not extension_entry.is_dir() or extension_entry.is_symlink():
                        continue
                    staging_entries = list(extension_entry.iterdir())
                except OSError:
                    continue
                for staging_entry in staging_entries:
                    try:
                        if (
                            staging_entry.is_dir()
                            and not staging_entry.is_symlink()
                            and _doctor_is_install_stage_dir_name(staging_entry.name)
                        ):
                            debris.append(
                                _doctor_normalize_package_dist_path(
                                    staging_entry.relative_to(root).as_posix()
                                )
                            )
                    except OSError:
                        continue
    return sorted(set(debris))


def _doctor_package_dist_staging_debris_warning(debris: Sequence[str]) -> str | None:
    if not debris:
        return None
    return (
        "unexpected legacy plugin dependency staging debris in package dist: "
        f"{', '.join(debris)}"
    )


def _doctor_missing_package_dist_inventory_warning() -> str:
    return (
        "missing package dist inventory "
        f"{_PACKAGE_DIST_INVENTORY_RELATIVE_PATH.as_posix()}"
    )


def _doctor_package_dist_plugin_root(relative_path: str) -> str | None:
    parts = relative_path.split("/")
    if len(parts) < 3 or parts[0] != "dist" or parts[1] != "extensions":
        return None
    return "/".join(parts[:3])


def _doctor_collect_critical_bundled_runtime_sidecars(root: Path) -> list[str]:
    expected: list[str] = []
    for relative_path in _PACKAGE_DIST_BUNDLED_RUNTIME_SIDECAR_PATHS:
        plugin_root = _doctor_package_dist_plugin_root(relative_path)
        if plugin_root is None:
            continue
        if plugin_root in _PACKAGE_DIST_OMITTED_PRIVATE_QA_BUNDLED_PLUGIN_ROOTS:
            continue
        plugin_path = root / Path(plugin_root)
        if _doctor_path_exists(plugin_path / "package.json") or _doctor_path_exists(
            plugin_path / "openclaw.plugin.json"
        ):
            expected.append(relative_path)
    return sorted(set(expected))


def _doctor_missing_bundled_runtime_sidecar_warnings(
    root: Path,
    inventory_expected_files: Sequence[str] | None,
) -> list[str]:
    expected = _doctor_collect_critical_bundled_runtime_sidecars(root)
    if inventory_expected_files is not None:
        inventory_set = set(inventory_expected_files)
        expected = [path for path in expected if path not in inventory_set]
    warnings: list[str] = []
    for relative_path in expected:
        if not _doctor_path_exists(root / Path(relative_path)):
            warnings.append(f"missing bundled runtime sidecar {relative_path}")
    return warnings


def _doctor_resolved_source_checkout_warning(root: Path) -> str | None:
    try:
        resolved_root = root.resolve(strict=False)
    except OSError:
        resolved_root = root
    if (
        (_doctor_path_exists(resolved_root / ".git")
        or _doctor_path_exists(resolved_root / "pnpm-workspace.yaml"))
        and _doctor_path_exists(resolved_root / "src")
        and _doctor_path_exists(resolved_root / "extensions")
    ):
        return f"global package root resolves to source checkout: {resolved_root}"
    return None


def _doctor_package_dist_inventory_file_warnings(
    root: Path,
    expected_files: Sequence[str] | None,
) -> list[str]:
    if expected_files is None:
        return []
    actual_files = _doctor_collect_package_dist_files(root)
    actual_set = set(actual_files)
    expected_set = set(expected_files)
    warnings: list[str] = []
    for relative_path in expected_files:
        if relative_path not in actual_set:
            warnings.append(f"missing packaged dist file {relative_path}")
    for relative_path in actual_files:
        if relative_path not in expected_set:
            warnings.append(f"unexpected packaged dist file {relative_path}")
    return warnings


def _build_doctor_source_install_payload(root: Path) -> dict[str, object] | None:
    workspace_path = root / "pnpm-workspace.yaml"
    if not _doctor_path_exists(workspace_path):
        return None
    node_modules_path = root / "node_modules"
    pnpm_store_path = node_modules_path / ".pnpm"
    package_lock_path = root / "package-lock.json"
    tsx_bin_path = root / "node_modules" / ".bin" / "tsx"
    src_entry_path = root / "src" / "entry.ts"
    warnings: list[str] = []
    checks: list[dict[str, object]] = []

    if _doctor_path_exists(node_modules_path) and not _doctor_path_exists(pnpm_store_path):
        warnings.append(
            "node_modules was not installed by pnpm (missing node_modules/.pnpm). "
            "Run: pnpm install so bundled plugins can load package-local dependencies."
        )
        checks.append(
            _doctor_package_distribution_check(
                key="pnpm_node_modules",
                status="warning",
                path=node_modules_path,
                detail="node_modules was not installed by pnpm (missing node_modules/.pnpm).",
            )
        )
    else:
        checks.append(
            _doctor_package_distribution_check(
                key="pnpm_node_modules",
                status="ok",
                path=node_modules_path,
                detail="pnpm node_modules layout is present or node_modules is absent.",
            )
        )

    if _doctor_path_exists(package_lock_path):
        warnings.append(
            "package-lock.json present in a pnpm workspace. If you ran npm install, remove it "
            "and reinstall with pnpm."
        )
        checks.append(
            _doctor_package_distribution_check(
                key="package_lock",
                status="warning",
                path=package_lock_path,
                detail="package-lock.json is present in a pnpm workspace.",
            )
        )
    else:
        checks.append(
            _doctor_package_distribution_check(
                key="package_lock",
                status="ok",
                path=package_lock_path,
                detail="package-lock.json is absent.",
            )
        )

    if _doctor_path_exists(src_entry_path) and not _doctor_path_exists(tsx_bin_path):
        warnings.append("tsx binary is missing for source runs. Run: pnpm install.")
        checks.append(
            _doctor_package_distribution_check(
                key="tsx_binary",
                status="warning",
                path=tsx_bin_path,
                detail="tsx binary is missing for source runs.",
            )
        )
    else:
        checks.append(
            _doctor_package_distribution_check(
                key="tsx_binary",
                status="ok",
                path=tsx_bin_path,
                detail="tsx binary is present or not required.",
            )
        )

    return {
        "status": "warning" if warnings else "ok",
        "workspace": True,
        "workspacePath": str(workspace_path),
        "nodeModulesPath": str(node_modules_path),
        "pnpmStorePath": str(pnpm_store_path),
        "tsxBinPath": str(tsx_bin_path),
        "checks": checks,
        "warnings": warnings,
    }


def _build_doctor_package_distribution_payload(
    package_root: Path | None = None,
) -> dict[str, object]:
    root = package_root or _openzues_package_root()
    root_exists = _doctor_path_exists(root)
    source_checkout = (
        root_exists
        and _doctor_path_exists(root / "pyproject.toml")
        and _doctor_path_exists(root / "src" / "openzues")
    )
    dist_path = root / "dist"
    inventory_path = root / _PACKAGE_DIST_INVENTORY_RELATIVE_PATH
    dist_present = _doctor_path_exists(dist_path)
    inventory_present = _doctor_path_exists(inventory_path)
    inventory_expected_files, inventory_warning = _doctor_read_package_dist_inventory(
        inventory_path
    )
    inventory_required = not source_checkout
    source_install = _build_doctor_source_install_payload(root) if source_checkout else None
    missing_inventory_warning = _doctor_missing_package_dist_inventory_warning()
    resolved_source_checkout_warning = (
        None if source_checkout else _doctor_resolved_source_checkout_warning(root)
    )
    warnings: list[str] = []
    if not root_exists:
        warnings.append(f"Package root not found: {root}")
    if resolved_source_checkout_warning is not None:
        warnings.append(resolved_source_checkout_warning)
    if inventory_required and not dist_present:
        warnings.append(f"Packaged dist directory is missing: {dist_path}")
    if inventory_required and not inventory_present:
        warnings.append(missing_inventory_warning)
    if inventory_required and inventory_warning is not None:
        warnings.append(inventory_warning)
    staging_debris = (
        _doctor_collect_legacy_package_dist_staging_debris(root)
        if inventory_required and dist_present
        else []
    )
    staging_debris_warning = _doctor_package_dist_staging_debris_warning(
        staging_debris
    )
    if staging_debris_warning is not None:
        warnings.append(staging_debris_warning)
    unsafe_path_warnings = (
        _doctor_package_dist_unsafe_path_warnings(root)
        if inventory_required and dist_present
        else []
    )
    warnings.extend(unsafe_path_warnings)
    inventory_file_warnings: list[str] = []
    if inventory_required and inventory_present and inventory_warning is None:
        inventory_file_warnings = _doctor_package_dist_inventory_file_warnings(
            root,
            inventory_expected_files,
        )
        warnings.extend(inventory_file_warnings)
    sidecar_warnings = (
        _doctor_missing_bundled_runtime_sidecar_warnings(
            root,
            inventory_expected_files,
        )
        if inventory_required
        else []
    )
    warnings.extend(sidecar_warnings)
    if source_install is not None:
        source_install_warnings = source_install.get("warnings")
        if isinstance(source_install_warnings, list):
            warnings.extend(str(warning) for warning in source_install_warnings)
    if source_checkout and warnings:
        status = "warning"
        summary = "OpenZues source checkout has install issues."
        distribution = "source-checkout"
    elif source_checkout:
        status = "info"
        summary = "OpenZues is running from a source checkout; package inventory is informational."
        distribution = "source-checkout"
    elif warnings:
        status = "warning"
        summary = "OpenZues package distribution has missing packaged runtime artifacts."
        distribution = "packaged"
    else:
        status = "ok"
        summary = "OpenZues package distribution inventory is present."
        distribution = "packaged"
    checks = [
        _doctor_package_distribution_check(
            key="package_root",
            status="ok" if root_exists else "warning",
            path=root,
            detail="Package root is readable."
            if root_exists
            else "Package root is missing or unreadable.",
        ),
        _doctor_package_distribution_check(
            key="source_checkout",
            status="info" if source_checkout else "ok",
            detail="Source checkout markers are present."
            if source_checkout
            else "Source checkout markers are absent.",
        ),
        _doctor_package_distribution_check(
            key="dist",
            status="ok" if dist_present else ("info" if source_checkout else "warning"),
            path=dist_path,
            detail="Packaged dist directory is present."
            if dist_present
            else "Packaged dist directory is not required for source checkout runs."
            if source_checkout
            else "Packaged dist directory is missing.",
        ),
        _doctor_package_distribution_check(
            key="postinstall_inventory",
            status=(
                "warning"
                if inventory_warning is not None
                else "ok"
                if inventory_present
                else "info"
                if source_checkout
                else "warning"
            ),
            path=inventory_path,
            detail=inventory_warning
            if inventory_warning is not None
            else "Package dist inventory is present."
            if inventory_present
            else "Package dist inventory is not required for source checkout runs."
            if source_checkout
            else missing_inventory_warning,
        ),
    ]
    if resolved_source_checkout_warning is not None:
        checks.append(
            _doctor_package_distribution_check(
                key="resolved_source_checkout",
                status="warning",
                path=root,
                detail=resolved_source_checkout_warning,
            )
        )
    if inventory_required and inventory_present and inventory_warning is None:
        checks.append(
            _doctor_package_distribution_check(
                key="postinstall_inventory_files",
                status="warning" if inventory_file_warnings else "ok",
                path=dist_path,
                detail="; ".join(inventory_file_warnings)
                if inventory_file_warnings
                else "Package dist inventory matches packaged files.",
            )
        )
    if inventory_required and dist_present:
        checks.append(
            _doctor_package_distribution_check(
                key="legacy_plugin_dependency_staging_debris",
                status="warning" if staging_debris_warning is not None else "ok",
                path=dist_path / "extensions",
                detail=staging_debris_warning
                if staging_debris_warning is not None
                else "No legacy plugin dependency staging debris found.",
            )
        )
        checks.append(
            _doctor_package_distribution_check(
                key="unsafe_package_dist_paths",
                status="warning" if unsafe_path_warnings else "ok",
                path=dist_path,
                detail="; ".join(unsafe_path_warnings)
                if unsafe_path_warnings
                else "No unsafe package dist paths found.",
            )
        )
        checks.append(
            _doctor_package_distribution_check(
                key="bundled_runtime_sidecars",
                status="warning" if sidecar_warnings else "ok",
                path=dist_path / "extensions",
                detail="; ".join(sidecar_warnings)
                if sidecar_warnings
                else "Bundled runtime sidecars are present or not required.",
            )
        )
    payload: dict[str, object] = {
        "status": status,
        "summary": summary,
        "source": "openzues-native",
        "openClawContribution": "doctor:package-distribution",
        "windowsFirst": True,
        "platform": sys.platform,
        "packageRoot": str(root),
        "distribution": distribution,
        "sourceCheckout": source_checkout,
        "distPresent": dist_present,
        "inventoryPath": str(inventory_path),
        "inventoryPresent": inventory_present,
        "inventoryRequired": inventory_required,
        "checks": checks,
        "warnings": warnings,
    }
    if source_install is not None:
        payload["sourceInstall"] = source_install
    return payload


def _with_doctor_package_distribution_payload(
    payload: dict[str, object],
) -> dict[str, object]:
    next_payload = dict(payload)
    next_payload["packageDistribution"] = _build_doctor_package_distribution_payload()
    return next_payload


_CLAUDE_CLI_PROVIDER_ID = "claude-cli"
_CLAUDE_CLI_PROFILE_ID = "anthropic:claude-cli"


def _doctor_claude_cli_command(snapshot: dict[str, object]) -> str:
    agents = _dict_config(snapshot.get("agents"))
    defaults = _dict_config(agents.get("defaults"))
    cli_backends = _dict_config(defaults.get("cliBackends"))
    claude_backend = _dict_config(cli_backends.get(_CLAUDE_CLI_PROVIDER_ID))
    return _optional_cli_string(claude_backend.get("command")) or "claude"


def _doctor_model_primary(snapshot: dict[str, object]) -> str | None:
    agents = _dict_config(snapshot.get("agents"))
    defaults = _dict_config(agents.get("defaults"))
    model = defaults.get("model")
    if isinstance(model, str):
        return _optional_cli_string(model)
    if isinstance(model, dict):
        return _optional_cli_string(model.get("primary"))
    return None


def _doctor_claude_cli_configured(snapshot: dict[str, object]) -> bool:
    primary = _doctor_model_primary(snapshot)
    if primary is not None and primary.lower().startswith(f"{_CLAUDE_CLI_PROVIDER_ID}/"):
        return True
    agents = _dict_config(snapshot.get("agents"))
    defaults = _dict_config(agents.get("defaults"))
    raw_models = defaults.get("models")
    if isinstance(raw_models, dict) and any(
        str(key).lower().startswith(f"{_CLAUDE_CLI_PROVIDER_ID}/")
        for key in raw_models
    ):
        return True
    cli_backends = _dict_config(defaults.get("cliBackends"))
    if any(str(key).lower() == _CLAUDE_CLI_PROVIDER_ID for key in cli_backends):
        return True
    auth = _dict_config(snapshot.get("auth"))
    raw_profiles = auth.get("profiles")
    profiles = raw_profiles.values() if isinstance(raw_profiles, dict) else []
    return any(
        isinstance(profile, dict)
        and _optional_cli_string(profile.get("provider")) == _CLAUDE_CLI_PROVIDER_ID
        for profile in profiles
    )


def _config_has_claude_cli_profile(snapshot: dict[str, object]) -> bool:
    auth = _dict_config(snapshot.get("auth"))
    raw_profiles = auth.get("profiles")
    if not isinstance(raw_profiles, dict):
        return False
    profile = raw_profiles.get(_CLAUDE_CLI_PROFILE_ID)
    if isinstance(profile, dict):
        return True
    return any(
        isinstance(item, dict)
        and _optional_cli_string(item.get("provider")) == _CLAUDE_CLI_PROVIDER_ID
        for item in raw_profiles.values()
    )


def _build_doctor_claude_cli_payload(
    config_service: object | None,
) -> dict[str, object] | None:
    snapshot = _doctor_config_snapshot(config_service)
    if not _doctor_claude_cli_configured(snapshot):
        return None
    command = _doctor_claude_cli_command(snapshot)
    command_path = shutil.which(command)
    lines: list[str] = []
    fix_hints: list[str] = []
    if command_path:
        lines.append(f"- Binary: {command_path}.")
    else:
        lines.append(f'- Binary: command "{command}" was not found on PATH.')
        fix_hints.append(
            "- Fix: install Claude CLI or set agents.defaults.cliBackends.claude-cli.command "
            "to the real binary path."
        )
    lines.append("- Headless Claude auth: unavailable without interactive prompting.")
    fix_hints.append(
        "- Fix: run claude auth login, then openclaw models auth login --provider "
        "anthropic --method cli --set-default."
    )
    if _config_has_claude_cli_profile(snapshot):
        lines.append(
            f"- OpenClaw auth profile: {_CLAUDE_CLI_PROFILE_ID} "
            f"(provider {_CLAUDE_CLI_PROVIDER_ID})."
        )
    else:
        lines.append(f"- OpenClaw auth profile: missing ({_CLAUDE_CLI_PROFILE_ID}).")
        fix_hints.append(
            "- Fix: run openclaw models auth login --provider anthropic --method cli "
            "--set-default."
        )
    warning = "\n".join([*lines, *fix_hints])
    return {
        "status": "warning",
        "summary": "Claude CLI health needs attention.",
        "source": "openzues-native",
        "openClawContribution": "doctor:claude-cli",
        "provider": _CLAUDE_CLI_PROVIDER_ID,
        "command": command,
        "commandPath": command_path,
        "profileId": _CLAUDE_CLI_PROFILE_ID,
        "warnings": [warning],
    }


def _with_doctor_claude_cli_payload(
    payload: dict[str, object],
    config_service: object | None,
) -> dict[str, object]:
    claude_cli = _build_doctor_claude_cli_payload(config_service)
    if claude_cli is None:
        return payload
    next_payload = dict(payload)
    next_payload["claudeCli"] = claude_cli
    warnings = [
        str(warning)
        for warning in _object_list(claude_cli.get("warnings"))
    ]
    return _with_doctor_added_warnings(next_payload, warnings)


def _is_secret_ref(value: object) -> bool:
    return (
        isinstance(value, dict)
        and _optional_cli_string(value.get("source")) is not None
        and _optional_cli_string(value.get("id")) is not None
    )


def _has_configured_secret_input(value: object) -> bool:
    if _is_secret_ref(value):
        return True
    return _optional_cli_string(value) is not None


def _gateway_auth_plaintext_secret(value: object) -> str | None:
    return None if _is_secret_ref(value) else _optional_cli_string(value)


def _build_doctor_gateway_auth_payload(
    config_service: object | None,
    *,
    env: dict[str, str] | None = None,
) -> dict[str, object] | None:
    snapshot = _doctor_config_snapshot(config_service)
    gateway = _dict_config(snapshot.get("gateway"))
    if _optional_cli_string(gateway.get("mode")) != "local":
        return None
    auth = _dict_config(gateway.get("auth"))
    token_value = auth.get("token")
    password_value = auth.get("password")
    explicit_mode = _optional_cli_string(auth.get("mode"))
    token_configured = _has_configured_secret_input(token_value)
    password_configured = _has_configured_secret_input(password_value)
    if explicit_mode is None and token_configured and password_configured:
        warning = "\n".join(
            [
                (
                    "gateway.auth.token and gateway.auth.password are both configured while "
                    "gateway.auth.mode is unset."
                ),
                (
                    "Set an explicit mode to avoid ambiguous auth selection and "
                    "startup/runtime failures."
                ),
                "Set token mode: openclaw config set gateway.auth.mode token",
                "Set password mode: openclaw config set gateway.auth.mode password",
            ]
        )
        return {
            "status": "warning",
            "summary": "gateway.auth.mode is unset for token/password auth.",
            "source": "openzues-native",
            "openClawContribution": "doctor:gateway-auth",
            "reason": "ambiguous_mode",
            "warnings": [warning],
        }

    env_payload = env if env is not None else os.environ
    env_token = _optional_cli_string(env_payload.get("OPENCLAW_GATEWAY_TOKEN"))
    token = _gateway_auth_plaintext_secret(token_value) or env_token
    password = _gateway_auth_plaintext_secret(password_value)
    if explicit_mode is not None:
        mode = explicit_mode
        mode_source = "config"
    elif password is not None:
        mode = "password"
        mode_source = "password"
    elif token is not None:
        mode = "token"
        mode_source = "token"
    else:
        mode = "token"
        mode_source = "default"
    needs_token = mode != "password" and (mode != "token" or token is None)
    if not needs_token:
        return None
    if _is_secret_ref(token_value):
        warning = "\n".join(
            [
                "Gateway token is managed via SecretRef and is currently unavailable.",
                "Doctor will not overwrite gateway.auth.token with a plaintext value.",
                "Resolve/rotate the external secret source, then rerun doctor.",
            ]
        )
        return {
            "status": "warning",
            "summary": "Gateway token SecretRef is currently unavailable.",
            "source": "openzues-native",
            "openClawContribution": "doctor:gateway-auth",
            "reason": "secret_ref_unresolved",
            "mode": mode,
            "modeSource": mode_source,
            "warnings": [warning],
        }
    warning = (
        "Gateway auth is off or missing a token. Token auth is now the recommended "
        "default (including loopback)."
    )
    return {
        "status": "warning",
        "summary": warning,
        "source": "openzues-native",
        "openClawContribution": "doctor:gateway-auth",
        "reason": "missing_token",
        "mode": mode,
        "modeSource": mode_source,
        "warnings": [warning],
    }


def _with_doctor_gateway_auth_payload(
    payload: dict[str, object],
    config_service: object | None,
) -> dict[str, object]:
    gateway_auth = _build_doctor_gateway_auth_payload(config_service)
    if gateway_auth is None:
        return payload
    next_payload = dict(payload)
    next_payload["gatewayAuth"] = gateway_auth
    warnings = [
        str(warning)
        for warning in _object_list(gateway_auth.get("warnings"))
    ]
    return _with_doctor_added_warnings(next_payload, warnings)


def _doctor_browser_health_configured(snapshot: dict[str, object]) -> bool:
    browser = _dict_config(snapshot.get("browser"))
    if _optional_cli_string(browser.get("defaultProfile")) is not None:
        return True
    profiles = browser.get("profiles")
    profile_values = profiles.values() if isinstance(profiles, dict) else []
    return any(
        isinstance(profile, dict)
        and _optional_cli_string(profile.get("driver")) == "existing-session"
        for profile in profile_values
    )


def _doctor_browser_unavailable_payload(message: str) -> dict[str, object]:
    warning = f"- Browser health check is unavailable: {message}"
    return {
        "status": "unavailable",
        "summary": "Browser health check is unavailable.",
        "source": "openzues-native",
        "openClawContribution": "doctor:browser",
        "warnings": [warning],
    }


async def _build_doctor_browser_payload(
    config_service: object | None,
    browser_doctor_adapter: object | None,
) -> dict[str, object] | None:
    snapshot = _doctor_config_snapshot(config_service)
    if not _doctor_browser_health_configured(snapshot):
        return None
    check = getattr(browser_doctor_adapter, "check", None)
    if not callable(check):
        check = getattr(browser_doctor_adapter, "note_chrome_mcp_browser_readiness", None)
    if not callable(check):
        return _doctor_browser_unavailable_payload("browser doctor facade is unavailable.")
    try:
        result = check(snapshot)
        if inspect.isawaitable(result):
            result = await result
    except Exception as exc:  # pragma: no cover - defensive adapter boundary
        return _doctor_browser_unavailable_payload(str(exc))
    result_payload = dict(result) if isinstance(result, dict) else {"result": result}
    result_payload.setdefault("source", "openzues-native")
    result_payload.setdefault("openClawContribution", "doctor:browser")
    return result_payload


async def _with_doctor_browser_payload(
    payload: dict[str, object],
    config_service: object | None,
    browser_doctor_adapter: object | None,
) -> dict[str, object]:
    browser_payload = await _build_doctor_browser_payload(config_service, browser_doctor_adapter)
    if browser_payload is None:
        return payload
    next_payload = dict(payload)
    next_payload["browser"] = browser_payload
    warnings = [
        str(warning)
        for warning in _object_list(browser_payload.get("warnings"))
    ]
    return _with_doctor_added_warnings(next_payload, warnings)


_OPENAI_AUTH_PROBE_URL = (
    "https://auth.openai.com/oauth/authorize?response_type=code"
    "&client_id=openclaw-preflight"
    "&redirect_uri=http%3A%2F%2Flocalhost%3A1455%2Fauth%2Fcallback"
    "&scope=openid+profile+email"
)
_OAUTH_TLS_CERT_ERROR_CODES = {
    "UNABLE_TO_GET_ISSUER_CERT_LOCALLY",
    "UNABLE_TO_VERIFY_LEAF_SIGNATURE",
    "CERT_HAS_EXPIRED",
    "DEPTH_ZERO_SELF_SIGNED_CERT",
    "SELF_SIGNED_CERT_IN_CHAIN",
    "ERR_TLS_CERT_ALTNAME_INVALID",
}
_OAUTH_TLS_CERT_ERROR_PATTERNS = (
    "unable to get local issuer certificate",
    "unable to verify the first certificate",
    "self-signed certificate",
    "self signed certificate",
    "certificate has expired",
    "certificate verify failed",
)


def _classify_openai_oauth_tls_error(error: BaseException) -> dict[str, object]:
    reason = getattr(error, "reason", None)
    root = reason if reason is not None else error
    raw_code = getattr(root, "code", None)
    code = str(raw_code).strip() if raw_code is not None else None
    message = str(root or error)
    message_lower = message.lower()
    is_tls_cert = (
        code in _OAUTH_TLS_CERT_ERROR_CODES
        if code is not None
        else False
    ) or any(pattern in message_lower for pattern in _OAUTH_TLS_CERT_ERROR_PATTERNS)
    return {
        "ok": False,
        "kind": "tls-cert" if is_tls_cert else "network",
        "code": code,
        "message": message,
    }


def _run_openai_oauth_tls_preflight(
    *,
    timeout_seconds: float = 4.0,
) -> dict[str, object]:
    request = Request(_OPENAI_AUTH_PROBE_URL, method="GET")
    try:
        with urlopen(request, timeout=timeout_seconds):
            return {"ok": True}
    except HTTPError:
        return {"ok": True}
    except URLError as exc:
        return _classify_openai_oauth_tls_error(exc)
    except OSError as exc:
        return _classify_openai_oauth_tls_error(exc)


def _format_openai_oauth_tls_preflight_fix(result: dict[str, object]) -> str:
    message = _optional_cli_string(result.get("message")) or "unknown TLS failure"
    code = _optional_cli_string(result.get("code"))
    if _optional_cli_string(result.get("kind")) != "tls-cert":
        return "\n".join(
            [
                (
                    "OpenAI OAuth prerequisites check failed due to a network "
                    "error before the browser flow."
                ),
                f"Cause: {message}",
                "Verify DNS/firewall/proxy access to auth.openai.com and retry.",
            ]
        )
    cause = f"{code} ({message})" if code is not None else message
    return "\n".join(
        [
            (
                "OpenAI OAuth prerequisites check failed: Node/OpenSSL cannot "
                "validate TLS certificates."
            ),
            f"Cause: {cause}",
            "",
            "Fix (Homebrew Node/OpenSSL):",
            "- brew postinstall ca-certificates",
            "- brew postinstall openssl@3",
            "- Retry the OAuth login flow.",
        ]
    )


def _build_doctor_oauth_tls_payload(
    config_service: object | None,
) -> dict[str, object]:
    base_payload: dict[str, object] = {
        "source": "openzues-native",
        "openClawContribution": "doctor:oauth-tls",
        "repairAvailable": False,
        "warnings": [],
    }
    snapshot = _doctor_config_snapshot(config_service)
    if not _config_has_codex_oauth_profile(snapshot):
        return {
            **base_payload,
            "status": "ok",
            "summary": "OpenAI Codex OAuth TLS preflight skipped.",
            "checked": False,
        }
    result = _run_openai_oauth_tls_preflight(timeout_seconds=4.0)
    warning = (
        _format_openai_oauth_tls_preflight_fix(result)
        if result.get("ok") is not True and result.get("kind") == "tls-cert"
        else None
    )
    return {
        **base_payload,
        "status": "warning" if warning else "ok",
        "summary": (
            "OpenAI OAuth TLS prerequisites need attention."
            if warning
            else "OpenAI OAuth TLS prerequisites passed or had no certificate warning."
        ),
        "checked": True,
        "result": result,
        "warnings": [warning] if warning else [],
    }


def _with_doctor_oauth_tls_payload(
    payload: dict[str, object],
    config_service: object | None,
) -> dict[str, object]:
    oauth_tls = _build_doctor_oauth_tls_payload(config_service)
    next_payload = dict(payload)
    next_payload["oauthTls"] = oauth_tls
    warnings = [
        str(warning)
        for warning in _object_list(oauth_tls.get("warnings"))
    ]
    return _with_doctor_added_warnings(next_payload, warnings)


def _doctor_hooks_gmail_model(snapshot: dict[str, object]) -> str | None:
    hooks = _dict_config(snapshot.get("hooks"))
    gmail = _dict_config(hooks.get("gmail"))
    return _optional_cli_string(gmail.get("model"))


def _doctor_model_key_from_parts(provider: str | None, model: str | None) -> str | None:
    normalized_model = _optional_cli_string(model)
    if normalized_model is None:
        return None
    if "/" in normalized_model:
        return normalized_model
    normalized_provider = _optional_cli_string(provider) or "openai"
    return f"{normalized_provider}/{normalized_model}"


def _doctor_model_key_from_entry(
    entry: object,
    *,
    default_provider: str = "openai",
) -> str | None:
    if isinstance(entry, str):
        return _doctor_model_key_from_parts(default_provider, entry)
    if not isinstance(entry, dict):
        return None
    raw_id = (
        _optional_cli_string(entry.get("id"))
        or _optional_cli_string(entry.get("model"))
        or _optional_cli_string(entry.get("name"))
    )
    raw_provider = _optional_cli_string(entry.get("provider")) or default_provider
    return _doctor_model_key_from_parts(raw_provider, raw_id)


def _doctor_default_model_entries(snapshot: dict[str, object]) -> list[object]:
    agents = _dict_config(snapshot.get("agents"))
    defaults = _dict_config(agents.get("defaults"))
    models = defaults.get("models")
    if isinstance(models, list):
        return list(models)
    if isinstance(models, dict):
        return list(models.values())
    return []


def _doctor_hooks_model_alias_index(snapshot: dict[str, object]) -> dict[str, str]:
    aliases: dict[str, str] = {}
    for entry in _doctor_default_model_entries(snapshot):
        if not isinstance(entry, dict):
            continue
        alias = _optional_cli_string(entry.get("alias"))
        key = _doctor_model_key_from_entry(entry)
        if alias is not None and key is not None:
            aliases[alias] = key
    return aliases


def _doctor_resolve_hooks_model_key(
    snapshot: dict[str, object],
    raw_model: str,
) -> str | None:
    alias_key = _doctor_hooks_model_alias_index(snapshot).get(raw_model)
    if alias_key is not None:
        return alias_key
    return _doctor_model_key_from_parts("openai", raw_model)


def _doctor_allowed_model_keys(snapshot: dict[str, object]) -> set[str]:
    keys: set[str] = set()
    for entry in _doctor_default_model_entries(snapshot):
        key = _doctor_model_key_from_entry(entry)
        if key is not None:
            keys.add(key)
    return keys


def _doctor_catalog_model_keys(snapshot: dict[str, object]) -> set[str]:
    models = _dict_config(snapshot.get("models"))
    providers = _dict_config(models.get("providers"))
    keys: set[str] = set()
    for provider_id, provider_payload in providers.items():
        provider = _optional_cli_string(str(provider_id))
        if provider is None or not isinstance(provider_payload, dict):
            continue
        raw_models = provider_payload.get("models")
        model_entries = raw_models if isinstance(raw_models, list) else []
        for entry in model_entries:
            key = _doctor_model_key_from_entry(entry, default_provider=provider)
            if key is not None:
                keys.add(key)
    return keys


def _build_doctor_hooks_model_payload(
    config_service: object | None,
) -> dict[str, object] | None:
    snapshot = _doctor_config_snapshot(config_service)
    raw_model = _doctor_hooks_gmail_model(snapshot)
    if raw_model is None:
        return None
    model_key = _doctor_resolve_hooks_model_key(snapshot, raw_model)
    if model_key is None:
        warning = f'- hooks.gmail.model "{raw_model}" could not be resolved'
        return {
            "status": "warning",
            "summary": "hooks.gmail.model could not be resolved.",
            "source": "openzues-native",
            "openClawContribution": "doctor:hooks-model",
            "model": raw_model,
            "warnings": [warning],
        }
    allowed_keys = _doctor_allowed_model_keys(snapshot)
    catalog_keys = _doctor_catalog_model_keys(snapshot)
    warnings: list[str] = []
    if allowed_keys and model_key not in allowed_keys:
        warnings.append(
            f'- hooks.gmail.model "{model_key}" not in agents.defaults.models '
            "allowlist (will use primary instead)"
        )
    if catalog_keys and model_key not in catalog_keys:
        warnings.append(
            f'- hooks.gmail.model "{model_key}" not in the model catalog '
            "(may fail at runtime)"
        )
    return {
        "status": "warning" if warnings else "ok",
        "summary": (
            "hooks.gmail.model has warnings."
            if warnings
            else "hooks.gmail.model resolves to an allowed catalog model."
        ),
        "source": "openzues-native",
        "openClawContribution": "doctor:hooks-model",
        "model": raw_model,
        "modelKey": model_key,
        "allowed": not allowed_keys or model_key in allowed_keys,
        "inCatalog": not catalog_keys or model_key in catalog_keys,
        "warnings": warnings,
    }


def _with_doctor_hooks_model_payload(
    payload: dict[str, object],
    config_service: object | None,
) -> dict[str, object]:
    hooks_model = _build_doctor_hooks_model_payload(config_service)
    if hooks_model is None:
        return payload
    next_payload = dict(payload)
    next_payload["hooksModel"] = hooks_model
    warnings = [
        str(warning)
        for warning in _object_list(hooks_model.get("warnings"))
    ]
    return _with_doctor_added_warnings(next_payload, warnings)


def _doctor_bootstrap_workspace_dir(snapshot: dict[str, object]) -> Path | None:
    agents = _dict_config(snapshot.get("agents"))
    defaults = _dict_config(agents.get("defaults"))
    raw_workspace = (
        _optional_cli_string(defaults.get("workspaceDir"))
        or _optional_cli_string(agents.get("workspaceDir"))
        or _optional_cli_string(snapshot.get("workspaceDir"))
    )
    if raw_workspace is None:
        workspace = _dict_config(snapshot.get("workspace"))
        raw_workspace = _optional_cli_string(workspace.get("dir"))
    if raw_workspace is None:
        return None
    expanded = os.path.expandvars(os.path.expanduser(raw_workspace))
    try:
        return Path(expanded).resolve(strict=False)
    except OSError:
        return Path(expanded)


def _doctor_bootstrap_limit(snapshot: dict[str, object], key: str, default: int) -> int:
    agents = _dict_config(snapshot.get("agents"))
    defaults = _dict_config(agents.get("defaults"))
    value = defaults.get(key)
    if isinstance(value, int) and not isinstance(value, bool) and value > 0:
        return value
    return default


def _doctor_format_int(value: int) -> str:
    return f"{max(0, int(value)):,}"


def _doctor_format_percent(numerator: int, denominator: int) -> str:
    if denominator <= 0:
        return "0%"
    pct = min(100, max(0, round((numerator / denominator) * 100)))
    return f"{pct}%"


def _doctor_int_record_value(record: dict[str, object], key: str) -> int:
    value = record.get(key)
    if isinstance(value, bool):
        return 0
    if isinstance(value, int):
        return value
    if isinstance(value, float) and value.is_integer():
        return int(value)
    return 0


def _doctor_bootstrap_file_record(
    path: Path,
    *,
    max_chars: int,
) -> dict[str, object] | None:
    if not path.is_file():
        return None
    try:
        content = path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return None
    raw_chars = len(content)
    injected_chars = min(raw_chars, max_chars)
    truncated = raw_chars > injected_chars
    near_limit = not truncated and raw_chars >= int(max_chars * 0.9)
    causes = ["per-file-limit"] if truncated else []
    return {
        "name": path.name,
        "path": str(path),
        "rawChars": raw_chars,
        "injectedChars": injected_chars,
        "truncated": truncated,
        "nearLimit": near_limit,
        "causes": causes,
    }


def _doctor_bootstrap_warning(
    *,
    truncated_files: list[dict[str, object]],
    near_limit_files: list[dict[str, object]],
    injected_total: int,
    raw_total: int,
    max_chars: int,
    total_max_chars: int,
    total_near_limit: bool,
) -> str | None:
    if not truncated_files and not near_limit_files and not total_near_limit:
        return None
    lines: list[str] = []
    if truncated_files:
        lines.append("Workspace bootstrap files exceed limits and will be truncated:")
        for file in truncated_files:
            raw_chars = _doctor_int_record_value(file, "rawChars")
            injected_chars = _doctor_int_record_value(file, "injectedChars")
            truncated_chars = max(0, raw_chars - injected_chars)
            lines.append(
                f"- {file.get('name')}: {_doctor_format_int(raw_chars)} raw / "
                f"{_doctor_format_int(injected_chars)} injected "
                f"({_doctor_format_percent(truncated_chars, raw_chars)} truncated; max/file)"
            )
    else:
        lines.append("Workspace bootstrap files are near configured limits:")
    for file in near_limit_files:
        raw_chars = _doctor_int_record_value(file, "rawChars")
        lines.append(
            f"- {file.get('name')}: {_doctor_format_int(raw_chars)} chars "
            f"({_doctor_format_percent(raw_chars, max_chars)} of max/file "
            f"{_doctor_format_int(max_chars)})"
        )
    lines.append(
        f"Total bootstrap injected chars: {_doctor_format_int(injected_total)} "
        f"({_doctor_format_percent(injected_total, total_max_chars)} of max/total "
        f"{_doctor_format_int(total_max_chars)})."
    )
    lines.append(
        f"Total bootstrap raw chars (before truncation): {_doctor_format_int(raw_total)}."
    )
    lines.append("")
    if truncated_files or near_limit_files:
        lines.append("- Tip: tune `agents.defaults.bootstrapMaxChars` for per-file limits.")
    if total_near_limit:
        lines.append(
            "- Tip: tune `agents.defaults.bootstrapTotalMaxChars` for total-budget limits."
        )
    return "\n".join(lines)


def _build_doctor_bootstrap_size_payload(
    config_service: object | None,
) -> dict[str, object]:
    base_payload: dict[str, object] = {
        "source": "openzues-native",
        "openClawContribution": "doctor:bootstrap-size",
        "repairAvailable": False,
        "warnings": [],
    }
    snapshot = _doctor_config_snapshot(config_service)
    workspace_dir = _doctor_bootstrap_workspace_dir(snapshot)
    if workspace_dir is None:
        return {
            **base_payload,
            "status": "ok",
            "summary": "No workspace directory configured for bootstrap size checks.",
            "checked": False,
        }
    max_chars = _doctor_bootstrap_limit(snapshot, "bootstrapMaxChars", 20_000)
    total_max_chars = _doctor_bootstrap_limit(
        snapshot,
        "bootstrapTotalMaxChars",
        150_000,
    )
    files = [
        record
        for filename in ("AGENTS.md",)
        if (
            record := _doctor_bootstrap_file_record(
                workspace_dir / filename,
                max_chars=max_chars,
            )
        )
        is not None
    ]
    raw_total = sum(_doctor_int_record_value(file, "rawChars") for file in files)
    injected_total = min(
        sum(_doctor_int_record_value(file, "injectedChars") for file in files),
        total_max_chars,
    )
    truncated_files = [file for file in files if file.get("truncated") is True]
    near_limit_files = [file for file in files if file.get("nearLimit") is True]
    total_near_limit = injected_total >= int(total_max_chars * 0.9)
    warning = _doctor_bootstrap_warning(
        truncated_files=truncated_files,
        near_limit_files=near_limit_files,
        injected_total=injected_total,
        raw_total=raw_total,
        max_chars=max_chars,
        total_max_chars=total_max_chars,
        total_near_limit=total_near_limit,
    )
    return {
        **base_payload,
        "status": "warning" if warning else "ok",
        "summary": (
            "Workspace bootstrap files exceed or approach configured limits."
            if warning
            else "Workspace bootstrap files are within configured limits."
        ),
        "checked": True,
        "workspaceDir": str(workspace_dir),
        "maxChars": max_chars,
        "totalMaxChars": total_max_chars,
        "files": files,
        "truncatedFiles": truncated_files,
        "nearLimitFiles": near_limit_files,
        "totals": {
            "rawChars": raw_total,
            "injectedChars": injected_total,
        },
        "warnings": [warning] if warning else [],
    }


def _with_doctor_bootstrap_size_payload(
    payload: dict[str, object],
    config_service: object | None,
) -> dict[str, object]:
    bootstrap_size = _build_doctor_bootstrap_size_payload(config_service)
    next_payload = dict(payload)
    next_payload["bootstrapSize"] = bootstrap_size
    warnings = [
        str(warning)
        for warning in _object_list(bootstrap_size.get("warnings"))
    ]
    return _with_doctor_added_warnings(next_payload, warnings)


def _doctor_workspace_plugin_summary(
    records: Sequence[dict[str, object]],
) -> dict[str, object]:
    loaded = [record for record in records if record.get("status") == "loaded"]
    imported = [record for record in records if record.get("imported") is True]
    disabled = [record for record in records if record.get("status") == "disabled"]
    errored = [record for record in records if record.get("status") == "error"]
    bundle_plugins = [
        record
        for record in loaded
        if record.get("format") == "bundle" and _object_list(record.get("bundleCapabilities"))
    ]
    return {
        "loaded": len(loaded),
        "imported": len(imported),
        "disabled": len(disabled),
        "errors": len(errored),
        "bundlePlugins": len(bundle_plugins),
        "records": [
            {
                "id": str(record.get("id") or ""),
                "status": str(record.get("status") or "unknown"),
                "format": str(record.get("format") or "unknown"),
                "imported": record.get("imported") is True,
            }
            for record in records
            if str(record.get("id") or "")
        ],
    }


def _doctor_task_flow_recovery_findings(
    task_flows: Sequence[Mapping[str, object]],
) -> list[str]:
    findings: list[str] = []
    for flow in task_flows:
        flow_id = _optional_cli_string(flow.get("flowId"))
        if flow_id is None:
            continue
        raw_tasks = flow.get("tasks")
        tasks = [
            cast("Mapping[str, object]", task)
            for task in raw_tasks
            if isinstance(task, Mapping)
        ] if isinstance(raw_tasks, list) else []
        status = _optional_cli_string(flow.get("status"))
        if (
            _optional_cli_string(flow.get("syncMode")) == "managed"
            and status == "running"
            and not tasks
            and flow.get("waitJson") is None
        ):
            findings.append(
                f"{flow_id}: running managed TaskFlow has no linked tasks or wait state; "
                "inspect or cancel it manually."
            )
        blocked_task_id = _optional_cli_string(flow.get("blockedTaskId"))
        if (
            status == "blocked"
            and blocked_task_id is not None
            and not any(task.get("taskId") == blocked_task_id for task in tasks)
        ):
            findings.append(
                f"{flow_id}: blocked TaskFlow points at missing task {blocked_task_id}; "
                "inspect before retrying."
            )
    return findings


def _doctor_task_flow_recovery_payload(
    task_flows: Sequence[Mapping[str, object]],
) -> dict[str, object]:
    findings = _doctor_task_flow_recovery_findings(task_flows)
    inspect_command = "openclaw tasks flow show <flow-id>"
    cancel_command = "openclaw tasks flow cancel <flow-id>"
    warnings: list[str] = []
    if findings:
        lines = [
            *findings[:5],
            f"...and {len(findings) - 5} more." if len(findings) > 5 else None,
            f"Inspect: {inspect_command}",
            f"Cancel: {cancel_command}",
        ]
        warnings.append("\n".join(line for line in lines if line is not None))
    return {
        "status": "warning" if findings else "ok",
        "findings": findings,
        "inspectCommand": inspect_command,
        "cancelCommand": cancel_command,
        "warnings": warnings,
    }


def _build_doctor_workspace_status_payload(
    config_service: object | None,
    *,
    task_flows: Sequence[Mapping[str, object]] | None = None,
    runtime_specs: tuple[GatewayPluginRuntimeExecutorSpec, ...] = (),
) -> dict[str, object]:
    snapshot = _doctor_config_snapshot(config_service)
    records = _plugin_records_from_config_snapshot(snapshot)
    _mark_plugin_import_state(
        records,
        runtime_specs,
        loaded_non_bundle_imported=True,
    )
    plugin_summary = _doctor_workspace_plugin_summary(records)
    errors = _doctor_int_record_value(plugin_summary, "errors")
    task_flow_recovery = _doctor_task_flow_recovery_payload(task_flows or ())
    warnings = [str(warning) for warning in _object_list(task_flow_recovery.get("warnings"))]
    return {
        "status": "warning" if errors or warnings else "ok",
        "summary": (
            "Workspace plugin status has errors."
            if errors
            else "Workspace TaskFlow recovery has warnings."
            if warnings
            else "Workspace plugin status is available."
        ),
        "source": "openzues-native",
        "openClawContribution": "doctor:workspace-status",
        "workspaceDir": (
            str(workspace_dir)
            if (workspace_dir := _doctor_bootstrap_workspace_dir(snapshot)) is not None
            else None
        ),
        "skills": {
            "eligible": 0,
            "missingRequirements": 0,
            "blockedByAllowlist": 0,
        },
        "plugins": plugin_summary,
        "taskFlowRecovery": task_flow_recovery,
        "warnings": warnings,
    }


def _with_doctor_workspace_status_payload(
    payload: dict[str, object],
    config_service: object | None,
    *,
    task_flows: Sequence[Mapping[str, object]] | None = None,
    runtime_specs: tuple[GatewayPluginRuntimeExecutorSpec, ...] = (),
) -> dict[str, object]:
    next_payload = dict(payload)
    workspace_status = _build_doctor_workspace_status_payload(
        config_service,
        task_flows=task_flows,
        runtime_specs=runtime_specs,
    )
    next_payload["workspaceStatus"] = workspace_status
    return _with_doctor_added_warnings(
        next_payload,
        [str(warning) for warning in _object_list(workspace_status.get("warnings"))],
    )


def _build_doctor_provider_overrides_payload(
    config_service: object | None,
    data_dir: Path | None = None,
) -> dict[str, object]:
    snapshot = _doctor_config_snapshot(config_service)
    models = snapshot.get("models")
    models_payload = models if isinstance(models, dict) else {}
    providers = models_payload.get("providers")
    provider_payload = providers if isinstance(providers, dict) else {}
    opencode_paths = [
        f"models.providers.{provider_id}"
        for provider_id in ("opencode", "opencode-go")
        if isinstance(provider_payload.get(provider_id), dict)
    ]
    payload: dict[str, object] = {}
    if opencode_paths:
        payload["opencode"] = {
            "ok": False,
            "paths": opencode_paths,
            "warnings": [
                (
                    "OpenCode provider overrides shadow bundled defaults: "
                    + ", ".join(opencode_paths)
                )
            ],
        }
    codex_provider_override = provider_payload.get(_OPENAI_CODEX_PROVIDER_ID)
    if _has_legacy_codex_transport_override(codex_provider_override) and (
        _config_has_codex_oauth_profile(snapshot)
        or _stored_has_codex_oauth_profile(snapshot, data_dir)
    ):
        payload["openaiCodex"] = {
            "ok": False,
            "paths": [f"models.providers.{_OPENAI_CODEX_PROVIDER_ID}"],
            "warnings": [
                _build_codex_provider_override_warning(codex_provider_override)
            ],
        }
    return payload


def _with_doctor_provider_override_warnings(
    payload: dict[str, object],
    config_service: object | None,
    data_dir: Path | None = None,
) -> dict[str, object]:
    provider_overrides = _build_doctor_provider_overrides_payload(config_service, data_dir)
    if not provider_overrides:
        return payload
    next_payload = dict(payload)
    next_payload["providerOverrides"] = provider_overrides
    warnings: list[str] = []
    for provider_payload in provider_overrides.values():
        if not isinstance(provider_payload, dict):
            continue
        warnings.extend(str(warning) for warning in _object_list(provider_payload.get("warnings")))
    return _with_doctor_added_warnings(next_payload, warnings)


async def _build_doctor_startup_channel_maintenance_payload(
    config_service: object | None,
    maintenance_adapter: object | None,
    *,
    should_repair: bool,
) -> dict[str, object]:
    base_payload: dict[str, object] = {
        "source": "openzues-native",
        "openClawContribution": "doctor:startup-channel-maintenance",
        "repairRequested": should_repair,
        "trigger": "doctor-fix",
        "logPrefix": "doctor",
    }
    if not should_repair:
        return {
            **base_payload,
            "status": "skipped",
            "summary": "Startup channel maintenance only runs during doctor --fix.",
        }
    run = getattr(maintenance_adapter, "run", None)
    if not callable(run):
        return {
            **base_payload,
            "status": "unavailable",
            "summary": "Channel startup maintenance runtime is unavailable.",
        }
    try:
        result = await run(
            config=_doctor_config_snapshot(config_service),
            trigger="doctor-fix",
            log_prefix="doctor",
        )
    except Exception as exc:  # pragma: no cover - defensive adapter boundary
        return {
            **base_payload,
            "status": "error",
            "summary": f"Channel startup maintenance failed: {exc}",
        }
    result_payload = dict(result) if isinstance(result, dict) else {"result": result}
    summary = _optional_cli_string(result_payload.get("summary")) or (
        "Channel startup maintenance completed."
    )
    return {
        **base_payload,
        "status": "ok",
        "summary": summary,
        "result": result_payload,
    }


async def _with_doctor_startup_channel_maintenance_payload(
    payload: dict[str, object],
    config_service: object | None,
    maintenance_adapter: object | None,
    *,
    should_repair: bool,
) -> dict[str, object]:
    next_payload = dict(payload)
    next_payload["startupChannelMaintenance"] = (
        await _build_doctor_startup_channel_maintenance_payload(
            config_service,
            maintenance_adapter,
            should_repair=should_repair,
        )
    )
    return next_payload


def _with_doctor_contribution_surfaces(payload: dict[str, object]) -> dict[str, object]:
    next_payload = dict(payload)
    next_payload.setdefault("security", _build_doctor_security_payload())
    next_payload.setdefault("shellCompletion", _build_doctor_shell_completion_payload())
    return next_payload


def _doctor_sandbox_config_from_snapshot(
    snapshot: dict[str, Any],
) -> dict[str, object] | None:
    resolved: dict[str, object] = {}
    for agents_config in _doctor_agents_config_roots(snapshot):
        defaults_config = agents_config.get("defaults")
        if not isinstance(defaults_config, dict):
            continue
        sandbox_config = defaults_config.get("sandbox")
        if isinstance(sandbox_config, dict):
            resolved.update(sandbox_config)
    if not resolved:
        return None
    return resolved


def _doctor_agents_config_roots(snapshot: dict[str, Any]) -> tuple[dict[str, Any], ...]:
    roots: list[dict[str, Any]] = []
    gateway_config = snapshot.get("gateway")
    if isinstance(gateway_config, dict):
        gateway_agents = gateway_config.get("agents")
        if isinstance(gateway_agents, dict):
            roots.append(gateway_agents)
    top_level_agents = snapshot.get("agents")
    if isinstance(top_level_agents, dict):
        roots.append(top_level_agents)
    return tuple(roots)


def _doctor_sandbox_mode(value: object) -> Literal["off", "non-main", "all"]:
    text = str(value or "").strip()
    if text in {"non-main", "all"}:
        return cast(Literal["non-main", "all"], text)
    return "off"


def _doctor_sandbox_scope(
    value: object,
    *,
    per_session: object = None,
) -> Literal["shared", "session", "agent"]:
    text = str(value or "").strip()
    if text in {"shared", "session", "agent"}:
        return cast(Literal["shared", "session", "agent"], text)
    if isinstance(per_session, bool):
        return "session" if per_session else "shared"
    return "agent"


def _doctor_sandbox_backend(value: object) -> str:
    backend = str(value or "").strip()
    return backend or "docker"


def _emit_update_status(payload: dict[str, object], *, json_output: bool) -> None:
    if json_output:
        _emit_payload(payload, json_output=True)
        return

    _emit_payload(payload, json_output=False)
    update_hint = _openclaw_update_available_hint(payload)
    if update_hint is not None:
        typer.echo(update_hint)
    repo_root = str(payload.get("repo_root") or "").strip()
    if repo_root:
        typer.echo("repo: " + repo_root)
    current_revision = str(payload.get("current_revision") or "").strip()
    if current_revision:
        typer.echo("current revision: " + current_revision)
    pending_revision = str(payload.get("pending_revision") or "").strip()
    if pending_revision:
        typer.echo("pending revision: " + pending_revision)
    if payload.get("pending_restart"):
        typer.echo(
            "restart posture: "
            + ("safe now" if payload.get("safe_to_restart") else "waiting for a safe boundary")
        )


def _openclaw_update_available_hint(payload: Mapping[str, object]) -> str | None:
    availability = payload.get("availability")
    if not isinstance(availability, Mapping) or availability.get("available") is not True:
        return None
    details: list[str] = []
    git_behind = availability.get("gitBehind")
    if isinstance(git_behind, int):
        details.append(f"git behind {git_behind}")
    latest_version = _optional_cli_string(availability.get("latestVersion"))
    if latest_version is not None:
        details.append(f"npm {latest_version}")
    suffix = f" ({', '.join(details)})" if details else ""
    return f"Update available{suffix}. Run: openzues update"


_OPENCLAW_UPDATE_CHANNELS = {"stable", "beta", "dev"}
_OPENCLAW_UPDATE_PACKAGE_MANAGERS = {"pnpm", "bun", "npm"}


def _openclaw_update_config_channel(config_snapshot: object) -> str | None:
    if not isinstance(config_snapshot, Mapping):
        return None
    update = config_snapshot.get("update")
    if not isinstance(update, Mapping):
        return None
    channel = str(update.get("channel") or "").strip().lower()
    return channel if channel in _OPENCLAW_UPDATE_CHANNELS else None


def _openclaw_update_install_kind(root: Path) -> str:
    if _doctor_path_exists(root / ".git"):
        return "git"
    if _doctor_path_exists(root):
        return "package"
    return "unknown"


def _openclaw_update_package_manager(root: Path) -> str:
    package_json = root / "package.json"
    if _doctor_path_exists(package_json):
        try:
            parsed = json.loads(package_json.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            parsed = None
        if isinstance(parsed, Mapping):
            raw_manager = str(parsed.get("packageManager") or "").strip()
            manager = raw_manager.split("@", maxsplit=1)[0].strip().lower()
            if manager in _OPENCLAW_UPDATE_PACKAGE_MANAGERS:
                return manager

    lockfile_managers = (
        ("pnpm-lock.yaml", "pnpm"),
        ("bun.lock", "bun"),
        ("bun.lockb", "bun"),
        ("package-lock.json", "npm"),
    )
    for filename, manager in lockfile_managers:
        if _doctor_path_exists(root / filename):
            return manager
    return "unknown"


def _openclaw_update_deps_marker(root: Path, manager: str) -> tuple[Path | None, Path | None]:
    if manager == "pnpm":
        return root / "pnpm-lock.yaml", root / "node_modules" / ".modules.yaml"
    if manager == "bun":
        return root / "bun.lockb", root / "node_modules"
    if manager == "npm":
        return root / "package-lock.json", root / "node_modules"
    return None, None


def _openclaw_update_deps_status(root: Path, manager: str) -> dict[str, object]:
    lockfile_path, marker_path = _openclaw_update_deps_marker(root, manager)
    payload: dict[str, object] = {
        "manager": manager,
        "status": "unknown",
        "lockfilePath": str(lockfile_path) if lockfile_path is not None else None,
        "markerPath": str(marker_path) if marker_path is not None else None,
    }
    if lockfile_path is None or marker_path is None:
        payload["reason"] = "unknown package manager"
        return payload
    if not _doctor_path_exists(lockfile_path):
        payload["reason"] = "lockfile missing"
        return payload
    if not _doctor_path_exists(marker_path):
        payload["status"] = "missing"
        payload["reason"] = "node_modules marker missing"
        return payload
    try:
        lock_mtime_ms = lockfile_path.stat().st_mtime * 1000
        marker_mtime_ms = marker_path.stat().st_mtime * 1000
    except OSError:
        return payload
    if lock_mtime_ms > marker_mtime_ms + 1000:
        payload["status"] = "stale"
        payload["reason"] = "lockfile newer than install marker"
        return payload
    payload["status"] = "ok"
    return payload


def _openclaw_update_git_branch(root: Path) -> str | None:
    head_path = root / ".git" / "HEAD"
    if not _doctor_path_exists(head_path):
        return None
    try:
        head = head_path.read_text(encoding="utf-8").strip()
    except OSError:
        return None
    prefix = "ref: refs/heads/"
    if not head.startswith(prefix):
        return None
    branch = head.removeprefix(prefix).strip()
    if not branch or branch == "HEAD":
        return None
    return branch


def _openclaw_update_git_head_sha(root: Path) -> str | None:
    git_dir = root / ".git"
    head_path = git_dir / "HEAD"
    if not _doctor_path_exists(head_path):
        return None
    try:
        head = head_path.read_text(encoding="utf-8").strip()
    except OSError:
        return None
    ref_prefix = "ref: "
    if head.startswith(ref_prefix):
        ref_path = git_dir / head.removeprefix(ref_prefix).strip()
        if not _doctor_path_exists(ref_path):
            return None
        try:
            head = ref_path.read_text(encoding="utf-8").strip()
        except OSError:
            return None
    return head if re.fullmatch(r"[0-9a-fA-F]{40}", head) else None


def _openclaw_update_git_tag(root: Path) -> str | None:
    head_sha = _openclaw_update_git_head_sha(root)
    if head_sha is None:
        return None
    refs_tags = root / ".git" / "refs" / "tags"
    if _doctor_path_exists(refs_tags):
        try:
            tag_refs = sorted(path for path in refs_tags.rglob("*") if path.is_file())
        except OSError:
            tag_refs = []
        for tag_ref in tag_refs:
            try:
                tag_sha = tag_ref.read_text(encoding="utf-8").strip()
            except OSError:
                continue
            if tag_sha == head_sha:
                return tag_ref.relative_to(refs_tags).as_posix()
    packed_tag = _openclaw_update_packed_git_tag(root, head_sha)
    if packed_tag is not None:
        return packed_tag
    return None


def _openclaw_update_packed_git_tag(root: Path, head_sha: str) -> str | None:
    packed_refs_path = root / ".git" / "packed-refs"
    if not _doctor_path_exists(packed_refs_path):
        return None
    try:
        lines = packed_refs_path.read_text(encoding="utf-8").splitlines()
    except OSError:
        return None
    tag_prefix = "refs/tags/"
    for raw_line in lines:
        line = raw_line.strip()
        if not line or line.startswith("#") or line.startswith("^"):
            continue
        parts = line.split()
        if len(parts) < 2:
            continue
        sha, ref = parts[0], parts[1]
        if sha == head_sha and ref.startswith(tag_prefix):
            return ref.removeprefix(tag_prefix)
    return None


def _openclaw_update_channel_from_git_tag(tag: str) -> str:
    return "beta" if re.search(r"(?:^|[.-])beta(?:[.-]|$)", tag, flags=re.IGNORECASE) else "stable"


def _openclaw_update_git_payload(
    root: Path,
    *,
    git_tag: str | None,
    git_branch: str | None,
    raw_update_payload: object,
) -> dict[str, object]:
    raw_git = raw_update_payload.get("git") if isinstance(raw_update_payload, Mapping) else None
    git_payload: dict[str, object] = {
        "root": str(root),
        "sha": _openclaw_update_git_head_sha(root),
        "tag": git_tag,
        "branch": git_branch,
        "upstream": None,
        "dirty": None,
        "ahead": None,
        "behind": None,
        "fetchOk": None,
    }
    if isinstance(raw_git, Mapping):
        for key in ("upstream", "dirty", "ahead", "behind", "fetchOk"):
            if key in raw_git:
                git_payload[key] = raw_git[key]
    return git_payload


def _openclaw_update_semver_tuple(value: object) -> tuple[int, int, int] | None:
    text = _optional_cli_string(value)
    if text is None:
        return None
    match = re.match(r"^v?(\d+)\.(\d+)\.(\d+)", text)
    if match is None:
        return None
    return (int(match.group(1)), int(match.group(2)), int(match.group(3)))


def _openclaw_update_registry_payload(raw_update_payload: object) -> dict[str, object] | None:
    if not isinstance(raw_update_payload, Mapping):
        return None
    raw_registry = raw_update_payload.get("registry")
    if not isinstance(raw_registry, Mapping):
        return None
    registry: dict[str, object] = {}
    latest_version = _optional_cli_string(raw_registry.get("latestVersion"))
    if latest_version is not None:
        registry["latestVersion"] = latest_version
    error = _optional_cli_string(raw_registry.get("error"))
    if error is not None:
        registry["error"] = error
    return registry if registry else None


def _openclaw_update_availability_payload(
    update_payload: Mapping[str, object],
) -> dict[str, object]:
    raw_registry = update_payload.get("registry")
    latest_version = (
        _optional_cli_string(raw_registry.get("latestVersion"))
        if isinstance(raw_registry, Mapping)
        else None
    )
    current_semver = _openclaw_update_semver_tuple(__version__)
    latest_semver = _openclaw_update_semver_tuple(latest_version)
    has_registry_update = (
        current_semver is not None and latest_semver is not None and current_semver < latest_semver
    )

    raw_git = update_payload.get("git")
    raw_git_behind = raw_git.get("behind") if isinstance(raw_git, Mapping) else None
    git_behind = raw_git_behind if isinstance(raw_git_behind, int) else None
    has_git_update = git_behind is not None and git_behind > 0
    return {
        "available": has_git_update or has_registry_update,
        "hasGitUpdate": has_git_update,
        "hasRegistryUpdate": has_registry_update,
        "latestVersion": latest_version if has_registry_update else None,
        "gitBehind": git_behind,
    }


def _openclaw_update_channel_payload(
    *,
    config_channel: str | None,
    install_kind: str,
    git_tag: str | None,
    git_branch: str | None,
) -> dict[str, object]:
    if config_channel is not None:
        channel = config_channel
        source = "config"
        label = f"{channel} (config)"
    elif install_kind == "git" and git_tag is not None:
        channel = _openclaw_update_channel_from_git_tag(git_tag)
        source = "git-tag"
        label = f"{channel} ({git_tag})"
    elif install_kind == "git" and git_branch is not None:
        channel = "dev"
        source = "git-branch"
        label = f"{channel} ({git_branch})"
    elif install_kind == "git":
        channel = "dev"
        source = "default"
        label = f"{channel} ({source})"
    else:
        channel = "stable"
        source = "default"
        label = f"{channel} ({source})"
    return {
        "value": channel,
        "source": source,
        "label": label,
        "config": config_channel,
    }


def _with_openclaw_update_status_projection(
    payload: dict[str, object],
    *,
    config_snapshot: object,
) -> dict[str, object]:
    root = _openzues_package_root()
    install_kind = _openclaw_update_install_kind(root)
    git_tag = _openclaw_update_git_tag(root) if install_kind == "git" else None
    git_branch = _openclaw_update_git_branch(root) if install_kind == "git" else None
    config_channel = _openclaw_update_config_channel(config_snapshot)
    raw_update_payload = payload.get("update") if isinstance(payload, Mapping) else None
    package_manager = (
        _openclaw_update_package_manager(root) if install_kind != "unknown" else "unknown"
    )
    next_payload = dict(payload)
    update_payload: dict[str, object] = {
        "root": str(root),
        "installKind": install_kind,
        "packageManager": package_manager,
    }
    if install_kind == "git":
        update_payload["git"] = _openclaw_update_git_payload(
            root,
            git_tag=git_tag,
            git_branch=git_branch,
            raw_update_payload=raw_update_payload,
        )
    registry_payload = _openclaw_update_registry_payload(raw_update_payload)
    if registry_payload is not None:
        update_payload["registry"] = registry_payload
    if install_kind != "unknown":
        update_payload["deps"] = _openclaw_update_deps_status(root, package_manager)
    next_payload["update"] = update_payload
    next_payload["channel"] = _openclaw_update_channel_payload(
        config_channel=config_channel,
        install_kind=install_kind,
        git_tag=git_tag,
        git_branch=git_branch,
    )
    next_payload["availability"] = _openclaw_update_availability_payload(update_payload)
    return next_payload


