@dataclass
class _PluginRuntimeDependencyBucket:
    plugin_ids: set[str]
    install_roots: dict[str, set[str]]


def _plugin_manifest_string_list(value: object) -> list[str]:
    if not isinstance(value, list):
        return []
    return [text for item in value if (text := _optional_cli_string(item)) is not None]


def _plugin_doctor_contract_api_artifact(root_dir: Path) -> dict[str, object] | None:
    for basename in ("doctor-contract-api", "contract-api"):
        for extension in _OPENCLAW_CONTRACT_API_EXTENSIONS:
            candidate = root_dir / f"{basename}{extension}"
            if not candidate.exists():
                continue
            return {
                "path": str(candidate),
                "artifact": candidate.name,
                "kind": basename,
            }
    return None


def _has_legacy_elevenlabs_talk_fields(raw: Mapping[object, object]) -> bool:
    talk = raw.get("talk")
    if not isinstance(talk, Mapping):
        return False
    return any(
        key in talk
        for key in ("voiceId", "voiceAliases", "modelId", "outputFormat", "apiKey")
    )


def _collect_relevant_doctor_plugin_ids(raw: object) -> list[str]:
    if not isinstance(raw, Mapping):
        return []
    ids: set[str] = set()
    channels = raw.get("channels")
    if isinstance(channels, Mapping):
        for channel_id in channels:
            text = str(channel_id)
            if text != "defaults":
                ids.add(text)
    plugins = raw.get("plugins")
    plugin_entries = plugins.get("entries") if isinstance(plugins, Mapping) else None
    if isinstance(plugin_entries, Mapping):
        ids.update(str(plugin_id) for plugin_id in plugin_entries)
    if _has_legacy_elevenlabs_talk_fields(raw):
        ids.add("elevenlabs")
    return sorted(ids)


def _collect_relevant_doctor_plugin_ids_for_touched_paths(
    raw: object,
    touched_paths: Sequence[Sequence[object]],
) -> list[str]:
    if not isinstance(raw, Mapping):
        return []
    ids: set[str] = set()
    for touched_path in touched_paths:
        parts = [str(part) for part in touched_path]
        first = parts[0] if parts else None
        second = parts[1] if len(parts) > 1 else None
        third = parts[2] if len(parts) > 2 else None
        if first == "channels":
            if not second:
                return _collect_relevant_doctor_plugin_ids(raw)
            if second != "defaults":
                ids.add(second)
            continue
        if first == "plugins":
            if second != "entries" or not third:
                return _collect_relevant_doctor_plugin_ids(raw)
            ids.add(third)
            continue
        if first == "talk" and _has_legacy_elevenlabs_talk_fields(raw):
            ids.add("elevenlabs")
    return sorted(ids)


def _plugin_manifest_string_list_record(value: object) -> dict[str, object]:
    if not isinstance(value, dict):
        return {}
    normalized: dict[str, object] = {}
    for raw_key, raw_values in value.items():
        normalized_key = _optional_cli_string(raw_key)
        if normalized_key is None:
            continue
        values = _plugin_manifest_string_list(raw_values)
        if values:
            normalized[normalized_key] = values
    return normalized


def _plugin_manifest_string_record(value: object) -> dict[str, object]:
    if not isinstance(value, dict):
        return {}
    normalized: dict[str, object] = {}
    for raw_key, raw_value in value.items():
        normalized_key = _optional_cli_string(raw_key)
        normalized_value = _optional_cli_string(raw_value)
        if normalized_key is not None and normalized_value is not None:
            normalized[normalized_key] = normalized_value
    return normalized


def _plugin_manifest_command_aliases(value: object) -> list[dict[str, object]]:
    if not isinstance(value, list):
        return []
    aliases: list[dict[str, object]] = []
    for entry in value:
        if isinstance(entry, str):
            string_alias_name = entry.strip()
            if string_alias_name:
                aliases.append({"name": string_alias_name})
            continue
        if not isinstance(entry, dict):
            continue
        alias_name = _optional_cli_string(entry.get("name"))
        if alias_name is None:
            continue
        alias: dict[str, object] = {"name": alias_name}
        if entry.get("kind") == "runtime-slash":
            alias["kind"] = "runtime-slash"
        cli_command = _optional_cli_string(entry.get("cliCommand"))
        if cli_command is not None:
            alias["cliCommand"] = cli_command
        aliases.append(alias)
    return aliases


def _plugin_manifest_activation(value: object) -> dict[str, object]:
    if not isinstance(value, dict):
        return {}
    activation: dict[str, object] = {}
    for key in (
        "onProviders",
        "onAgentHarnesses",
        "onCommands",
        "onChannels",
        "onRoutes",
    ):
        values = _plugin_manifest_string_list(value.get(key))
        if values:
            activation[key] = values
    capabilities = [
        capability
        for capability in _plugin_manifest_string_list(value.get("onCapabilities"))
        if capability in {"provider", "channel", "tool", "hook"}
    ]
    if capabilities:
        activation["onCapabilities"] = capabilities
    return activation


def _plugin_manifest_setup_providers(value: object) -> list[dict[str, object]]:
    if not isinstance(value, list):
        return []
    providers: list[dict[str, object]] = []
    for entry in value:
        if not isinstance(entry, dict):
            continue
        provider_id = _optional_cli_string(entry.get("id"))
        if provider_id is None:
            continue
        provider: dict[str, object] = {"id": provider_id}
        auth_methods = _plugin_manifest_string_list(entry.get("authMethods"))
        if auth_methods:
            provider["authMethods"] = auth_methods
        env_vars = _plugin_manifest_string_list(entry.get("envVars"))
        if env_vars:
            provider["envVars"] = env_vars
        providers.append(provider)
    return providers


def _plugin_manifest_setup(value: object) -> dict[str, object]:
    if not isinstance(value, dict):
        return {}
    setup: dict[str, object] = {}
    providers = _plugin_manifest_setup_providers(value.get("providers"))
    if providers:
        setup["providers"] = providers
    cli_backends = _plugin_manifest_string_list(value.get("cliBackends"))
    if cli_backends:
        setup["cliBackends"] = cli_backends
    config_migrations = _plugin_manifest_string_list(value.get("configMigrations"))
    if config_migrations:
        setup["configMigrations"] = config_migrations
    requires_runtime = value.get("requiresRuntime")
    if isinstance(requires_runtime, bool):
        setup["requiresRuntime"] = requires_runtime
    return setup


def _plugin_manifest_provider_endpoints(value: object) -> list[dict[str, object]]:
    if not isinstance(value, list):
        return []
    endpoints: list[dict[str, object]] = []
    for raw_endpoint in value:
        if not isinstance(raw_endpoint, dict):
            continue
        endpoint_class = _optional_cli_string(raw_endpoint.get("endpointClass"))
        if endpoint_class is None:
            continue
        hosts = [
            host.lower()
            for host in _plugin_manifest_string_list(raw_endpoint.get("hosts"))
        ]
        host_suffixes = [
            host.lower()
            for host in _plugin_manifest_string_list(raw_endpoint.get("hostSuffixes"))
        ]
        base_urls = _plugin_manifest_string_list(raw_endpoint.get("baseUrls"))
        if not hosts and not host_suffixes and not base_urls:
            continue
        endpoint: dict[str, object] = {"endpointClass": endpoint_class}
        if hosts:
            endpoint["hosts"] = hosts
        if host_suffixes:
            endpoint["hostSuffixes"] = host_suffixes
        if base_urls:
            endpoint["baseUrls"] = base_urls
        google_vertex_region = _optional_cli_string(raw_endpoint.get("googleVertexRegion"))
        if google_vertex_region is not None:
            endpoint["googleVertexRegion"] = google_vertex_region
        google_vertex_region_host_suffix = _optional_cli_string(
            raw_endpoint.get("googleVertexRegionHostSuffix")
        )
        if google_vertex_region_host_suffix is not None:
            endpoint["googleVertexRegionHostSuffix"] = (
                google_vertex_region_host_suffix.lower()
            )
        endpoints.append(endpoint)
    return endpoints


def _plugin_manifest_owned_provider_ids(manifest: Mapping[str, object]) -> set[str]:
    return {
        provider.lower()
        for provider in _plugin_manifest_string_list(manifest.get("providers"))
    }


def _plugin_manifest_model_id_prefix_rules(value: object) -> list[dict[str, object]]:
    if not isinstance(value, list):
        return []
    rules: list[dict[str, object]] = []
    for entry in value:
        if not isinstance(entry, dict):
            continue
        model_prefix = _optional_cli_string(entry.get("modelPrefix"))
        prefix = _optional_cli_string(entry.get("prefix"))
        if model_prefix is None or prefix is None:
            continue
        rules.append({"modelPrefix": model_prefix, "prefix": prefix})
    return rules


def _plugin_manifest_model_id_normalization_provider(
    value: object,
) -> dict[str, object] | None:
    if not isinstance(value, dict):
        return None
    policy: dict[str, object] = {}
    aliases = _plugin_manifest_string_record(value.get("aliases"))
    if aliases:
        policy["aliases"] = aliases
    strip_prefixes = _plugin_manifest_string_list(value.get("stripPrefixes"))
    if strip_prefixes:
        policy["stripPrefixes"] = strip_prefixes
    prefix_when_bare = _optional_cli_string(value.get("prefixWhenBare"))
    if prefix_when_bare is not None:
        policy["prefixWhenBare"] = prefix_when_bare
    prefix_rules = _plugin_manifest_model_id_prefix_rules(
        value.get("prefixWhenBareAfterAliasStartsWith")
    )
    if prefix_rules:
        policy["prefixWhenBareAfterAliasStartsWith"] = prefix_rules
    return policy or None


def _plugin_manifest_model_id_normalization(
    value: object,
    *,
    owned_provider_ids: set[str],
) -> dict[str, object]:
    if not isinstance(value, dict):
        return {}
    raw_providers = value.get("providers")
    if not isinstance(raw_providers, dict):
        return {}
    providers: dict[str, object] = {}
    for raw_provider, raw_policy in raw_providers.items():
        provider_id = _optional_cli_string(raw_provider)
        if provider_id is None:
            continue
        normalized_provider_id = provider_id.lower()
        if normalized_provider_id not in owned_provider_ids:
            continue
        policy = _plugin_manifest_model_id_normalization_provider(raw_policy)
        if policy:
            providers[normalized_provider_id] = policy
    return {"providers": providers} if providers else {}


def _plugin_manifest_provider_request_provider(value: object) -> dict[str, object] | None:
    if not isinstance(value, dict):
        return None
    request: dict[str, object] = {}
    family = _optional_cli_string(value.get("family"))
    if family is not None:
        request["family"] = family
    compatibility_family = _optional_cli_string(value.get("compatibilityFamily"))
    if compatibility_family == "moonshot":
        request["compatibilityFamily"] = compatibility_family
    openai_completions = value.get("openAICompletions")
    if isinstance(openai_completions, dict):
        supports_streaming_usage = openai_completions.get("supportsStreamingUsage")
        if isinstance(supports_streaming_usage, bool):
            request["openAICompletions"] = {
                "supportsStreamingUsage": supports_streaming_usage
            }
    return request or None


def _plugin_manifest_provider_request(
    value: object,
    *,
    owned_provider_ids: set[str],
) -> dict[str, object]:
    if not isinstance(value, dict):
        return {}
    raw_providers = value.get("providers")
    if not isinstance(raw_providers, dict):
        return {}
    providers: dict[str, object] = {}
    for raw_provider, raw_policy in raw_providers.items():
        provider_id = _optional_cli_string(raw_provider)
        if provider_id is None:
            continue
        normalized_provider_id = provider_id.lower()
        if normalized_provider_id not in owned_provider_ids:
            continue
        policy = _plugin_manifest_provider_request_provider(raw_policy)
        if policy:
            providers[normalized_provider_id] = policy
    return {"providers": providers} if providers else {}


def _plugin_manifest_provider_auth_choices(value: object) -> list[dict[str, object]]:
    if not isinstance(value, list):
        return []
    choices: list[dict[str, object]] = []
    for entry in value:
        if not isinstance(entry, dict):
            continue
        provider = _optional_cli_string(entry.get("provider"))
        method = _optional_cli_string(entry.get("method"))
        choice_id = _optional_cli_string(entry.get("choiceId"))
        if provider is None or method is None or choice_id is None:
            continue
        choice: dict[str, object] = {
            "provider": provider,
            "method": method,
            "choiceId": choice_id,
        }
        for key in (
            "choiceLabel",
            "choiceHint",
            "groupId",
            "groupLabel",
            "groupHint",
            "optionKey",
            "cliFlag",
            "cliOption",
            "cliDescription",
        ):
            text = _optional_cli_string(entry.get(key))
            if text is not None:
                choice[key] = text
        assistant_priority = entry.get("assistantPriority")
        if isinstance(assistant_priority, int | float) and not isinstance(
            assistant_priority,
            bool,
        ):
            choice["assistantPriority"] = assistant_priority
        assistant_visibility = entry.get("assistantVisibility")
        if assistant_visibility in {"visible", "manual-only"}:
            choice["assistantVisibility"] = assistant_visibility
        deprecated_choice_ids = _plugin_manifest_string_list(
            entry.get("deprecatedChoiceIds")
        )
        if deprecated_choice_ids:
            choice["deprecatedChoiceIds"] = deprecated_choice_ids
        onboarding_scopes = [
            scope
            for scope in _plugin_manifest_string_list(entry.get("onboardingScopes"))
            if scope in {"text-inference", "image-generation"}
        ]
        if onboarding_scopes:
            choice["onboardingScopes"] = onboarding_scopes
        choices.append(choice)
    return choices


def _plugin_manifest_auth_env_metadata(manifest: dict[str, object]) -> dict[str, object]:
    metadata: dict[str, object] = {}
    owned_provider_ids = _plugin_manifest_owned_provider_ids(manifest)
    for key in ("providerAuthEnvVars", "channelEnvVars"):
        value = _plugin_manifest_string_list_record(manifest.get(key))
        if value:
            metadata[key] = value
    for key in ("syntheticAuthRefs", "nonSecretAuthMarkers"):
        values = _plugin_manifest_string_list(manifest.get(key))
        if values:
            metadata[key] = values
    provider_auth_aliases = _plugin_manifest_string_record(
        manifest.get("providerAuthAliases")
    )
    if provider_auth_aliases:
        metadata["providerAuthAliases"] = provider_auth_aliases
    provider_endpoints = _plugin_manifest_provider_endpoints(
        manifest.get("providerEndpoints")
    )
    if provider_endpoints:
        metadata["providerEndpoints"] = provider_endpoints
    model_id_normalization = _plugin_manifest_model_id_normalization(
        manifest.get("modelIdNormalization"),
        owned_provider_ids=owned_provider_ids,
    )
    if model_id_normalization:
        metadata["modelIdNormalization"] = model_id_normalization
    provider_request = _plugin_manifest_provider_request(
        manifest.get("providerRequest"),
        owned_provider_ids=owned_provider_ids,
    )
    if provider_request:
        metadata["providerRequest"] = provider_request
    provider_auth_choices = _plugin_manifest_provider_auth_choices(
        manifest.get("providerAuthChoices")
    )
    if provider_auth_choices:
        metadata["providerAuthChoices"] = provider_auth_choices
    return metadata


def _plugin_manifest_qa_runners(value: object) -> list[dict[str, object]]:
    if not isinstance(value, list):
        return []
    runners: list[dict[str, object]] = []
    for entry in value:
        if not isinstance(entry, dict):
            continue
        command_name = _optional_cli_string(entry.get("commandName"))
        if command_name is None:
            continue
        runner: dict[str, object] = {"commandName": command_name}
        description = _optional_cli_string(entry.get("description"))
        if description is not None:
            runner["description"] = description
        runners.append(runner)
    return runners


def _plugin_manifest_channel_configs(value: object) -> dict[str, object]:
    if not isinstance(value, dict):
        return {}
    configs: dict[str, object] = {}
    for raw_channel_id, raw_config in value.items():
        channel_id = _optional_cli_string(raw_channel_id)
        if channel_id is None or not isinstance(raw_config, dict):
            continue
        schema = raw_config.get("schema")
        if not isinstance(schema, dict):
            continue
        config: dict[str, object] = {"schema": dict(schema)}
        ui_hints = raw_config.get("uiHints")
        if isinstance(ui_hints, dict):
            config["uiHints"] = dict(ui_hints)
        label = _optional_cli_string(raw_config.get("label"))
        if label is not None:
            config["label"] = label
        description = _optional_cli_string(raw_config.get("description"))
        if description is not None:
            config["description"] = description
        prefer_over = _plugin_manifest_string_list(raw_config.get("preferOver"))
        if prefer_over:
            config["preferOver"] = prefer_over
        configs[channel_id] = config
    return configs


def _plugin_manifest_model_support(value: object) -> dict[str, object]:
    if not isinstance(value, dict):
        return {}
    model_support: dict[str, object] = {}
    model_prefixes = _plugin_manifest_string_list(value.get("modelPrefixes"))
    if model_prefixes:
        model_support["modelPrefixes"] = model_prefixes
    model_patterns = _plugin_manifest_string_list(value.get("modelPatterns"))
    if model_patterns:
        model_support["modelPatterns"] = model_patterns
    return model_support


def _plugin_manifest_kind(value: object) -> str | list[str] | None:
    if isinstance(value, str):
        return _optional_cli_string(value)
    if not isinstance(value, list):
        return None
    values = _plugin_manifest_string_list(value)
    if len(values) == 1:
        return values[0]
    return values if values else None


def _plugin_manifest_root_metadata(
    source: dict[str, object],
    *,
    root_dir: Path | None = None,
) -> dict[str, object]:
    metadata: dict[str, object] = {}
    if source.get("enabledByDefault") is True:
        metadata["enabledByDefault"] = True
    for key in (
        "legacyPluginIds",
        "autoEnableWhenConfiguredProviders",
        "channels",
        "providers",
        "cliBackends",
        "skills",
    ):
        values = _plugin_manifest_string_list(source.get(key))
        if values:
            metadata[key] = values
    kind = _plugin_manifest_kind(source.get("kind"))
    if kind is not None:
        metadata["kind"] = kind
    provider_discovery_source = _optional_cli_string(
        source.get("providerDiscoverySource")
    )
    if provider_discovery_source is not None:
        metadata["providerDiscoverySource"] = provider_discovery_source
    else:
        provider_discovery_entry = _optional_cli_string(
            source.get("providerDiscoveryEntry")
        )
        if provider_discovery_entry is not None and root_dir is not None:
            metadata["providerDiscoverySource"] = str(
                (root_dir / provider_discovery_entry).resolve(strict=False)
            )
    ui_hints = source.get("uiHints")
    if isinstance(ui_hints, dict):
        metadata["configUiHints"] = dict(ui_hints)
    return metadata


def _plugin_manifest_config_literal(value: object) -> bool:
    return value is None or isinstance(value, str | int | float | bool)


def _plugin_manifest_dangerous_config_flags(value: object) -> list[dict[str, object]]:
    if not isinstance(value, list):
        return []
    flags: list[dict[str, object]] = []
    for entry in value:
        if not isinstance(entry, dict):
            continue
        path = _optional_cli_string(entry.get("path"))
        if path is None or "equals" not in entry:
            continue
        equals = entry.get("equals")
        if not _plugin_manifest_config_literal(equals):
            continue
        flags.append({"path": path, "equals": equals})
    return flags


def _plugin_manifest_secret_input_paths(value: object) -> list[dict[str, object]]:
    if not isinstance(value, list):
        return []
    paths: list[dict[str, object]] = []
    for entry in value:
        if not isinstance(entry, dict):
            continue
        path = _optional_cli_string(entry.get("path"))
        if path is None:
            continue
        secret_input: dict[str, object] = {"path": path}
        if entry.get("expected") == "string":
            secret_input["expected"] = "string"
        paths.append(secret_input)
    return paths


def _plugin_manifest_config_contracts(value: object) -> dict[str, object]:
    if not isinstance(value, dict):
        return {}
    contracts: dict[str, object] = {}
    migration_paths = _plugin_manifest_string_list(
        value.get("compatibilityMigrationPaths")
    )
    if migration_paths:
        contracts["compatibilityMigrationPaths"] = migration_paths
    runtime_paths = _plugin_manifest_string_list(value.get("compatibilityRuntimePaths"))
    if runtime_paths:
        contracts["compatibilityRuntimePaths"] = runtime_paths
    dangerous_flags = _plugin_manifest_dangerous_config_flags(
        value.get("dangerousFlags")
    )
    if dangerous_flags:
        contracts["dangerousFlags"] = dangerous_flags
    raw_secret_inputs = value.get("secretInputs")
    if isinstance(raw_secret_inputs, dict):
        secret_input_paths = _plugin_manifest_secret_input_paths(
            raw_secret_inputs.get("paths")
        )
        if secret_input_paths:
            secret_inputs: dict[str, object] = {"paths": secret_input_paths}
            bundled_default_enabled = raw_secret_inputs.get("bundledDefaultEnabled")
            if isinstance(bundled_default_enabled, bool):
                secret_inputs["bundledDefaultEnabled"] = bundled_default_enabled
            contracts["secretInputs"] = secret_inputs
    return contracts


def _plugin_manifest_tool_metadata(value: object) -> dict[str, object]:
    if not isinstance(value, dict):
        return {}
    metadata: dict[str, object] = {}
    for raw_tool_name, raw_metadata in value.items():
        tool_name = _optional_cli_string(raw_tool_name)
        if tool_name is None or not isinstance(raw_metadata, dict):
            continue
        entry: dict[str, object] = {}
        auth_signals = _plugin_manifest_auth_signals(raw_metadata.get("authSignals"))
        if auth_signals:
            entry["authSignals"] = auth_signals
        for key in ("authProviders", "aliases"):
            values = _plugin_manifest_string_list(raw_metadata.get(key))
            if values:
                entry[key] = values
        config_signals = _plugin_manifest_config_signals(
            raw_metadata.get("configSignals")
        )
        if config_signals:
            entry["configSignals"] = config_signals
        if entry:
            metadata[tool_name] = entry
    return metadata


def _plugin_manifest_auth_signals(value: object) -> list[dict[str, object]]:
    if not isinstance(value, list):
        return []
    signals: list[dict[str, object]] = []
    for raw_signal in value:
        if not isinstance(raw_signal, dict):
            continue
        provider = _optional_cli_string(raw_signal.get("provider"))
        if provider is None:
            continue
        signal: dict[str, object] = {"provider": provider}
        provider_base_url = _plugin_manifest_provider_base_url_guard(
            raw_signal.get("providerBaseUrl")
        )
        if provider_base_url:
            signal["providerBaseUrl"] = provider_base_url
        signals.append(signal)
    return signals


def _plugin_manifest_provider_base_url_guard(value: object) -> dict[str, object]:
    if not isinstance(value, dict):
        return {}
    provider = _optional_cli_string(value.get("provider"))
    allowed_base_urls = _plugin_manifest_string_list(value.get("allowedBaseUrls"))
    if provider is None or not allowed_base_urls:
        return {}
    guard: dict[str, object] = {
        "provider": provider,
        "allowedBaseUrls": allowed_base_urls,
    }
    default_base_url = _optional_cli_string(value.get("defaultBaseUrl"))
    if default_base_url is not None:
        guard["defaultBaseUrl"] = default_base_url
    return guard


def _plugin_manifest_config_signals(value: object) -> list[dict[str, object]]:
    if not isinstance(value, list):
        return []
    signals: list[dict[str, object]] = []
    for raw_signal in value:
        if not isinstance(raw_signal, dict):
            continue
        root_path = _optional_cli_string(raw_signal.get("rootPath"))
        if root_path is None:
            continue
        signal: dict[str, object] = {"rootPath": root_path}
        overlay_path = _optional_cli_string(raw_signal.get("overlayPath"))
        if overlay_path is not None:
            signal["overlayPath"] = overlay_path
        required = _plugin_manifest_string_list(raw_signal.get("required"))
        if required:
            signal["required"] = required
        required_any = _plugin_manifest_string_list(raw_signal.get("requiredAny"))
        if required_any:
            signal["requiredAny"] = required_any
        mode = _plugin_manifest_config_signal_mode(raw_signal.get("mode"))
        if mode:
            signal["mode"] = mode
        signals.append(signal)
    return signals


def _plugin_manifest_config_signal_mode(value: object) -> dict[str, object]:
    if not isinstance(value, dict):
        return {}
    mode: dict[str, object] = {}
    path_value = _optional_cli_string(value.get("path"))
    if path_value is not None:
        mode["path"] = path_value
    default = _optional_cli_string(value.get("default"))
    if default is not None:
        mode["default"] = default
    allowed = _plugin_manifest_string_list(value.get("allowed"))
    if allowed:
        mode["allowed"] = allowed
    disallowed = _plugin_manifest_string_list(value.get("disallowed"))
    if disallowed:
        mode["disallowed"] = disallowed
    return mode


def _read_cli_json_object(path: Path) -> dict[str, object] | None:
    try:
        parsed = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return None
    return parsed if isinstance(parsed, dict) else None


def _strip_cli_json5_comments(text: str) -> str:
    result: list[str] = []
    in_string: str | None = None
    escaped = False
    index = 0
    while index < len(text):
        char = text[index]
        next_char = text[index + 1] if index + 1 < len(text) else ""
        if in_string is not None:
            result.append(char)
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == in_string:
                in_string = None
            index += 1
            continue
        if char in {'"', "'"}:
            in_string = char
            result.append('"' if char == "'" else char)
            index += 1
            continue
        if char == "/" and next_char == "/":
            index += 2
            while index < len(text) and text[index] not in "\r\n":
                index += 1
            continue
        if char == "/" and next_char == "*":
            index += 2
            while index + 1 < len(text) and not (text[index] == "*" and text[index + 1] == "/"):
                index += 1
            index += 2 if index + 1 < len(text) else 0
            continue
        result.append(char)
        index += 1
    return "".join(result)


def _normalize_cli_json5_subset(text: str) -> str:
    without_comments = _strip_cli_json5_comments(text)
    quoted_keys = re.sub(
        r'([{\[,]\s*)([A-Za-z_$][A-Za-z0-9_$]*)\s*:',
        r'\1"\2":',
        without_comments,
    )
    return re.sub(r",(\s*[}\]])", r"\1", quoted_keys)


def _read_cli_json5_object(path: Path) -> dict[str, object] | None:
    try:
        text = path.read_text(encoding="utf-8")
    except OSError:
        return None
    for candidate in (text, _normalize_cli_json5_subset(text)):
        try:
            parsed = json.loads(candidate)
        except ValueError:
            continue
        if isinstance(parsed, dict):
            return parsed
    return None


def _plugin_package_json_metadata(plugin_root: Path) -> dict[str, object]:
    package_json = _read_cli_json_object(plugin_root / "package.json")
    if package_json is None:
        return {}
    metadata: dict[str, object] = {}
    for key in ("name", "version", "description"):
        value = _optional_cli_string(package_json.get(key))
        if value is not None:
            metadata[key] = value
    openclaw = package_json.get("openclaw")
    if isinstance(openclaw, dict):
        metadata["openclaw"] = openclaw
    return metadata


def _plugin_package_channel_catalog_meta(value: object) -> dict[str, object]:
    if not isinstance(value, dict):
        return {}
    channel_id = _optional_cli_string(value.get("id"))
    if channel_id is None:
        return {}
    metadata: dict[str, object] = {"id": channel_id}
    label = _optional_cli_string(value.get("label"))
    if label is not None:
        metadata["label"] = label
    blurb = _optional_cli_string(value.get("blurb"))
    if blurb is not None:
        metadata["blurb"] = blurb
    prefer_over = _plugin_manifest_string_list(value.get("preferOver"))
    if prefer_over:
        metadata["preferOver"] = prefer_over
    return metadata


def _plugin_rewrite_public_surface_artifact(name: str) -> str:
    stem = name.rsplit(".", 1)[0]
    return f"{stem}.js"


def _plugin_is_public_surface_source(name: str) -> bool:
    if name.startswith(".") or name.startswith("test-") or ".test-" in name:
        return False
    if name.endswith(".d.ts"):
        return False
    if re.match(r"^config-api(\.[cm]?[jt]s)$", name):
        return False
    if re.search(r"(\.test|\.spec)(\.[cm]?[jt]s)$", name):
        return False
    return Path(name).suffix in _OPENCLAW_PUBLIC_SURFACE_SOURCE_EXTENSIONS


def _plugin_public_surface_artifacts(
    plugin_root: Path,
    package_openclaw: dict[str, object],
) -> dict[str, list[str]]:
    excluded: set[str] = set()
    raw_extensions = package_openclaw.get("extensions")
    for entry in raw_extensions if isinstance(raw_extensions, list) else []:
        text = _optional_cli_string(entry)
        if text is not None:
            excluded.add(Path(text).name)
    setup_entry = _optional_cli_string(package_openclaw.get("setupEntry"))
    if setup_entry is not None:
        excluded.add(Path(setup_entry).name)
    try:
        entries = list(plugin_root.iterdir())
    except OSError:
        return {}
    public_artifacts = sorted(
        {
            _plugin_rewrite_public_surface_artifact(entry.name)
            for entry in entries
            if entry.is_file()
            and entry.name not in excluded
            and _plugin_is_public_surface_source(entry.name)
        }
    )
    metadata: dict[str, list[str]] = {}
    if public_artifacts:
        metadata["publicSurfaceArtifacts"] = public_artifacts
    runtime_sidecars = [
        artifact
        for artifact in public_artifacts
        if artifact in _OPENCLAW_RUNTIME_SIDECAR_ARTIFACTS
    ]
    if runtime_sidecars:
        metadata["runtimeSidecarArtifacts"] = runtime_sidecars
    return metadata


def _plugin_runtime_entry_sources(
    plugin_root: Path,
    package_openclaw: dict[str, object],
) -> list[str]:
    raw_extensions = package_openclaw.get("extensions")
    raw_entries = raw_extensions if isinstance(raw_extensions, list) else []
    entries = [
        text
        for entry in raw_entries
        if (text := _optional_cli_string(entry)) is not None
    ]
    if not entries:
        entries = [
            candidate
            for candidate in _OPENCLAW_DEFAULT_PLUGIN_ENTRY_CANDIDATES
            if (plugin_root / candidate).is_file()
        ][:1]

    sources: list[str] = []
    seen: set[str] = set()
    for entry in entries:
        entry_path = plugin_root / entry
        if entry_path.suffix not in _OPENCLAW_PUBLIC_SURFACE_SOURCE_EXTENSIONS:
            continue
        if not entry_path.is_file():
            continue
        resolved = str(entry_path.resolve(strict=False))
        if resolved in seen:
            continue
        seen.add(resolved)
        sources.append(resolved)
    return sources


def _plugin_runtime_entry_sdk_imports(runtime_entry_sources: Sequence[str]) -> list[str]:
    imports: list[str] = []
    seen: set[str] = set()
    for source in runtime_entry_sources:
        try:
            text = Path(source).read_text(encoding="utf-8", errors="ignore")
        except OSError:
            continue
        for match in _OPENCLAW_PLUGIN_SDK_IMPORT_RE.finditer(text):
            specifier = match.group(1)
            if specifier in seen:
                continue
            seen.add(specifier)
            imports.append(specifier)
    return imports


def _plugin_package_openclaw_record_metadata(
    value: object,
    *,
    plugin_root: Path,
) -> dict[str, object]:
    if not isinstance(value, dict):
        return {}
    metadata: dict[str, object] = {}
    setup_entry = _optional_cli_string(value.get("setupEntry"))
    if setup_entry is not None:
        metadata["setupSource"] = str((plugin_root / setup_entry).resolve(strict=False))
    runtime_entry_sources = _plugin_runtime_entry_sources(plugin_root, value)
    if runtime_entry_sources:
        metadata["runtimeEntrySource"] = runtime_entry_sources[0]
        metadata["runtimeEntrySources"] = runtime_entry_sources
        plugin_sdk_imports = _plugin_runtime_entry_sdk_imports(runtime_entry_sources)
        if plugin_sdk_imports:
            metadata["pluginSdkImports"] = plugin_sdk_imports
            metadata.update(
                _plugin_runtime_entry_sdk_alias_metadata(
                    plugin_root,
                    plugin_sdk_imports,
                )
            )
    metadata.update(_plugin_public_surface_artifacts(plugin_root, value))
    startup = value.get("startup")
    if (
        isinstance(startup, dict)
        and startup.get("deferConfiguredChannelFullLoadUntilAfterListen") is True
    ):
        metadata["startupDeferConfiguredChannelFullLoadUntilAfterListen"] = True
    channel_catalog_meta = _plugin_package_channel_catalog_meta(value.get("channel"))
    if channel_catalog_meta:
        metadata["channelCatalogMeta"] = channel_catalog_meta
    return metadata


def _plugin_runtime_entry_sdk_alias_metadata(
    plugin_root: Path,
    plugin_sdk_imports: Sequence[str],
) -> dict[str, object]:
    if not plugin_sdk_imports:
        return {}
    dist_root = _plugin_runtime_entry_dist_root(plugin_root)
    if dist_root is not None:
        plugin_sdk_root = dist_root / "plugin-sdk"
        if plugin_sdk_root.is_dir():
            alias_root = (
                dist_root / "extensions" / "node_modules" / "openclaw" / "plugin-sdk"
            )
            return {
                "pluginSdkResolution": "dist",
                "pluginSdkPackageRoot": str(dist_root.parent.resolve(strict=False)),
                "pluginSdkDistRoot": str(dist_root.resolve(strict=False)),
                "pluginSdkAliasRoot": str(alias_root.resolve(strict=False)),
            }
    source_alias_map = _plugin_runtime_entry_source_sdk_alias_map(
        plugin_root,
        plugin_sdk_imports,
    )
    if not source_alias_map:
        return {}
    source_root = plugin_root / "plugin-sdk"
    return {
        "pluginSdkResolution": "src",
        "pluginSdkSourceRoot": str(source_root.resolve(strict=False)),
        "pluginSdkAliasMap": source_alias_map,
    }


def _plugin_runtime_entry_source_sdk_alias_map(
    plugin_root: Path,
    plugin_sdk_imports: Sequence[str],
) -> dict[str, object]:
    source_root = plugin_root / "plugin-sdk"
    if not source_root.is_dir():
        return {}
    alias_map: dict[str, object] = {}
    for specifier in plugin_sdk_imports:
        subpath = _plugin_sdk_import_subpath(specifier)
        if subpath is None:
            continue
        target = _plugin_source_sdk_alias_target(source_root, subpath)
        if target is None:
            continue
        if subpath:
            aliases = (
                f"openclaw/plugin-sdk/{subpath}",
                f"@openclaw/plugin-sdk/{subpath}",
            )
        else:
            aliases = ("openclaw/plugin-sdk", "@openclaw/plugin-sdk")
        for alias in aliases:
            alias_map[alias] = str(target.resolve(strict=False))
    return alias_map


def _plugin_sdk_import_subpath(specifier: str) -> str | None:
    for package_name in ("openclaw/plugin-sdk", "@openclaw/plugin-sdk"):
        if specifier == package_name:
            return ""
        prefix = f"{package_name}/"
        if specifier.startswith(prefix):
            subpath = specifier[len(prefix) :].strip("/")
            if subpath and ".." not in Path(subpath).parts:
                return subpath
    return None


def _plugin_source_sdk_alias_target(source_root: Path, subpath: str) -> Path | None:
    candidates: list[Path]
    if subpath:
        candidates = [
            source_root / f"{subpath}{extension}"
            for extension in _OPENCLAW_PUBLIC_SURFACE_SOURCE_EXTENSIONS
        ]
    else:
        candidates = [
            source_root / "root-alias.cjs",
            *(
                source_root / f"index{extension}"
                for extension in _OPENCLAW_PUBLIC_SURFACE_SOURCE_EXTENSIONS
            ),
        ]
    for candidate in candidates:
        if candidate.is_file():
            return candidate
    return None


def _plugin_runtime_entry_dist_root(plugin_root: Path) -> Path | None:
    extensions_root = plugin_root.parent
    if extensions_root.name.lower() != "extensions":
        return None
    bundle_root = extensions_root.parent
    bundle_root_name = bundle_root.name.lower()
    if bundle_root_name == "dist":
        return bundle_root
    if bundle_root_name == "dist-runtime":
        return bundle_root.parent / "dist"
    return None


def _plugin_semver_tuple(value: object) -> tuple[int, int, int] | None:
    text = _optional_cli_string(value)
    if text is None:
        return None
    match = re.match(r"^(\d+)\.(\d+)\.(\d+)$", text)
    if match is None:
        return None
    return (int(match.group(1)), int(match.group(2)), int(match.group(3)))


def _plugin_min_host_version_diagnostic(
    package_openclaw: object,
    *,
    current_version: str,
    plugin_id: str,
    source: str,
) -> dict[str, object] | None:
    if not isinstance(package_openclaw, dict):
        return None
    install = package_openclaw.get("install")
    if not isinstance(install, dict) or "minHostVersion" not in install:
        return None
    raw_min_host_version = install.get("minHostVersion")
    min_host_text = _optional_cli_string(raw_min_host_version)
    match = (
        _OPENCLAW_MIN_HOST_VERSION_RE.match(min_host_text)
        if min_host_text is not None
        else None
    )
    if match is None:
        return {
            "level": "error",
            "message": f"plugin manifest invalid | {_OPENCLAW_MIN_HOST_VERSION_FORMAT}",
            "pluginId": plugin_id,
            "source": source,
        }
    minimum_label = f"{match.group(1)}.{match.group(2)}.{match.group(3)}"
    current_semver = _plugin_semver_tuple(current_version)
    if current_semver is None:
        return {
            "level": "warn",
            "message": (
                f"plugin requires OpenClaw >={minimum_label}, but host version "
                "could not be determined"
            ),
            "pluginId": plugin_id,
            "source": source,
        }
    minimum_semver = (int(match.group(1)), int(match.group(2)), int(match.group(3)))
    if current_semver < minimum_semver:
        return {
            "level": "error",
            "message": (
                f"plugin requires OpenClaw >={minimum_label}, but this host is "
                f"{current_version}"
            ),
            "pluginId": plugin_id,
            "source": source,
        }
    return None


def _merge_package_channel_meta(
    channel_configs: dict[str, object],
    package_openclaw: object,
) -> dict[str, object]:
    if not isinstance(package_openclaw, dict):
        return channel_configs
    channel = package_openclaw.get("channel")
    if not isinstance(channel, dict):
        return channel_configs
    channel_id = _optional_cli_string(channel.get("id"))
    if channel_id is None:
        return channel_configs
    raw_config = channel_configs.get(channel_id)
    if not isinstance(raw_config, dict):
        return channel_configs
    merged_configs = dict(channel_configs)
    config = dict(raw_config)
    if _optional_cli_string(config.get("label")) is None:
        label = _optional_cli_string(channel.get("label"))
        if label is not None:
            config["label"] = label
    if _optional_cli_string(config.get("description")) is None:
        blurb = _optional_cli_string(channel.get("blurb"))
        if blurb is not None:
            config["description"] = blurb
    if not _plugin_manifest_string_list(config.get("preferOver")):
        prefer_over = _plugin_manifest_string_list(channel.get("preferOver"))
        if prefer_over:
            config["preferOver"] = prefer_over
    merged_configs[channel_id] = config
    return merged_configs


def _plugin_manifest_contracts(manifest: dict[str, object]) -> dict[str, object]:
    raw_contracts = manifest.get("contracts")
    contracts = raw_contracts if isinstance(raw_contracts, dict) else {}
    result: dict[str, object] = {}
    for key in _OPENCLAW_PLUGIN_CONTRACT_CAPABILITY_LABELS:
        values = _plugin_manifest_string_list(contracts.get(key))
        if values:
            result[key] = values
    return result


def _plugin_manifest_capabilities(
    manifest: dict[str, object],
    contracts: dict[str, object],
) -> list[str]:
    capabilities: list[str] = []
    for key, label in _OPENCLAW_PLUGIN_CONTRACT_CAPABILITY_LABELS.items():
        values = contracts.get(key)
        if isinstance(values, list):
            capabilities.extend(f"{label}:{value}" for value in values)
    for key, label in (
        ("channels", "channel"),
        ("providers", "text-inference"),
        ("cliBackends", "cli-backend"),
        ("skills", "skill"),
    ):
        capabilities.extend(
            f"{label}:{value}" for value in _plugin_manifest_string_list(manifest.get(key))
        )
    seen: set[str] = set()
    unique: list[str] = []
    for capability in capabilities:
        if capability in seen:
            continue
        seen.add(capability)
        unique.append(capability)
    return unique


def _plugin_manifest_has_enabled_channel(
    manifest: dict[str, object],
    config_snapshot: dict[str, object] | None,
) -> bool:
    if config_snapshot is None:
        return False
    raw_channels_config = config_snapshot.get("channels")
    channels_config = raw_channels_config if isinstance(raw_channels_config, dict) else {}
    if not channels_config:
        return False
    for channel_id in _plugin_manifest_string_list(manifest.get("channels")):
        normalized_channel = _normalize_openclaw_channel_plugin_id(
            channel_id
        ) or channel_id.strip().lower()
        if normalized_channel is None:
            continue
        channel_config = channels_config.get(normalized_channel)
        if isinstance(channel_config, dict) and channel_config.get("enabled") is True:
            return True
    return False


def _plugin_manifest_configured_channel_auto_reason(
    manifest: dict[str, object],
    config_snapshot: dict[str, object] | None,
) -> str | None:
    raw_channels_config = (
        config_snapshot.get("channels") if config_snapshot is not None else None
    )
    channels_config = raw_channels_config if isinstance(raw_channels_config, dict) else {}
    channel_env_vars = _plugin_manifest_string_list_record(
        manifest.get("channelEnvVars")
    )
    env_by_lower = {key.lower(): value for key, value in os.environ.items()}
    for channel_id in _plugin_manifest_string_list(manifest.get("channels")):
        normalized_channel = _normalize_openclaw_channel_plugin_id(
            channel_id
        ) or channel_id.strip().lower()
        if normalized_channel is None:
            continue
        channel_config = channels_config.get(normalized_channel)
        if isinstance(channel_config, dict) and channel_config.get("enabled") is False:
            continue
        if isinstance(channel_config, dict) and any(
            str(key) != "enabled" for key in channel_config
        ):
            return f"{normalized_channel} configured"
        env_vars = _plugin_manifest_string_list(
            channel_env_vars.get(normalized_channel)
        )
        for env_var in env_vars:
            env_value = os.environ.get(env_var)
            if env_value is None:
                env_value = env_by_lower.get(env_var.lower())
            if isinstance(env_value, str) and env_value.strip():
                return f"{normalized_channel} configured"
    return None


def _plugin_runtime_dependency_entries_from_package_json(
    package_json: dict[str, object],
) -> list[dict[str, object]]:
    raw_runtime_deps: dict[str, object] = {}
    for key in ("dependencies", "optionalDependencies"):
        raw_value = package_json.get(key)
        if isinstance(raw_value, dict):
            raw_runtime_deps.update(raw_value)
    entries: list[dict[str, object]] = []
    for raw_name, raw_version in raw_runtime_deps.items():
        name = _optional_cli_string(raw_name)
        version = _optional_cli_string(raw_version)
        if name is None or version is None:
            continue
        entries.append({"name": name, "version": version})
    return sorted(entries, key=lambda entry: str(entry["name"]))


def _is_openclaw_source_checkout_root(path: Path) -> bool:
    return (
        (path / ".git").exists()
        and (path / "src").exists()
        and (path / "extensions").exists()
    )


def _is_source_checkout_bundled_plugin_root(plugin_root: Path) -> bool:
    extensions_dir = plugin_root.parent
    return extensions_dir.name == "extensions" and _is_openclaw_source_checkout_root(
        extensions_dir.parent
    )


def _plugin_runtime_dependency_install_root(plugin_root: Path) -> Path:
    extensions_dir = plugin_root.parent
    build_dir = extensions_dir.parent
    if extensions_dir.name == "extensions" and build_dir.name in {"dist", "dist-runtime"}:
        return build_dir.parent
    return extensions_dir


def _plugin_manifest_runtime_dependencies(
    manifest_path: Path,
) -> tuple[list[dict[str, object]], Path | None]:
    plugin_root = manifest_path.parent
    install_root = _plugin_runtime_dependency_install_root(plugin_root)
    if _is_openclaw_source_checkout_root(install_root) or _is_source_checkout_bundled_plugin_root(
        plugin_root
    ):
        return [], None
    package_json = _read_cli_json_object(plugin_root / "package.json")
    if package_json is None:
        return [], None
    return _plugin_runtime_dependency_entries_from_package_json(package_json), install_root


def _plugin_record_runtime_dependencies(plugin: dict[str, object]) -> list[dict[str, object]]:
    raw_dependencies = plugin.get("runtimeDependencies")
    dependencies = raw_dependencies if isinstance(raw_dependencies, list) else []
    result: list[dict[str, object]] = []
    for raw_dependency in dependencies:
        if not isinstance(raw_dependency, dict):
            continue
        name = _optional_cli_string(raw_dependency.get("name"))
        version = _optional_cli_string(raw_dependency.get("version"))
        if name is None or version is None:
            continue
        result.append({"name": name, "version": version})
    return result


def _dependency_sentinel_path(dep_name: str) -> Path | None:
    parts = [part for part in dep_name.split("/") if part]
    if not parts:
        return None
    return Path("node_modules", *parts, "package.json")


def _dependency_sentinel_exists(install_root: str, dep_name: str) -> bool:
    sentinel_path = _dependency_sentinel_path(dep_name)
    if sentinel_path is None:
        return False
    return (Path(install_root) / sentinel_path).exists()


def _build_plugin_runtime_dependency_doctor_payload(
    plugin_rows: list[object],
) -> tuple[dict[str, object], list[dict[str, object]]]:
    version_map: dict[str, dict[str, _PluginRuntimeDependencyBucket]] = {}
    for plugin in plugin_rows:
        if not isinstance(plugin, dict):
            continue
        if _optional_cli_string(plugin.get("status")) != "loaded":
            continue
        plugin_id = _optional_cli_string(plugin.get("id"))
        install_root = _optional_cli_string(plugin.get("runtimeDependencyInstallRoot"))
        if plugin_id is None or install_root is None:
            continue
        for dependency in _plugin_record_runtime_dependencies(plugin):
            name = _optional_cli_string(dependency.get("name"))
            version = _optional_cli_string(dependency.get("version"))
            if name is None or version is None:
                continue
            versions = version_map.setdefault(name, {})
            bucket = versions.setdefault(
                version,
                _PluginRuntimeDependencyBucket(plugin_ids=set(), install_roots={}),
            )
            bucket.plugin_ids.add(plugin_id)
            bucket.install_roots.setdefault(install_root, set()).add(plugin_id)

    conflicts: list[dict[str, object]] = []
    conflicted_names: set[str] = set()
    for name in sorted(version_map):
        versions = version_map[name]
        if len(versions) <= 1:
            continue
        sorted_versions = sorted(versions)
        conflicted_names.add(name)
        conflicts.append(
            {
                "name": name,
                "versions": sorted_versions,
                "pluginIdsByVersion": {
                    version: sorted(versions[version].plugin_ids)
                    for version in sorted_versions
                },
            }
        )

    missing: list[dict[str, object]] = []
    for name in sorted(version_map):
        if name in conflicted_names:
            continue
        versions = version_map[name]
        for version in sorted(versions):
            bucket = versions[version]
            for install_root in sorted(bucket.install_roots):
                if _dependency_sentinel_exists(install_root, name):
                    continue
                missing.append(
                    {
                        "name": name,
                        "version": version,
                        "pluginIds": sorted(bucket.install_roots[install_root]),
                        "installRoot": install_root,
                        "spec": f"{name}@{version}",
                    }
                )

    diagnostics: list[dict[str, object]] = []
    if conflicts:
        diagnostics.append(
            {
                "level": "error",
                "category": "runtimeDependencies",
                "code": "bundled_plugin_runtime_dependency_conflict",
                "message": "Bundled plugin runtime deps use conflicting versions.",
                "conflicts": conflicts,
                "action": "Update bundled plugins and rerun openzues plugins doctor.",
            }
        )
    if missing:
        diagnostics.append(
            {
                "level": "error",
                "category": "runtimeDependencies",
                "code": "bundled_plugin_runtime_dependency_missing",
                "message": "Bundled plugin runtime deps are missing.",
                "missing": missing,
                "action": "Fix: run openzues doctor --fix to install them.",
            }
        )
    return {"missing": missing, "conflicts": conflicts}, diagnostics


def _plugin_manifest_load_paths(plugins_config: dict[str, object]) -> list[Path]:
    load = plugins_config.get("load")
    load_payload = load if isinstance(load, dict) else {}
    raw_paths = load_payload.get("paths")
    paths = raw_paths if isinstance(raw_paths, list) else []
    result: list[Path] = []
    for raw_path in paths:
        path_text = _optional_cli_string(raw_path)
        if path_text is None:
            continue
        expanded = os.path.expandvars(os.path.expanduser(path_text))
        try:
            result.append(Path(expanded).resolve(strict=False))
        except OSError:
            result.append(Path(expanded))
    return result


def _plugin_manifest_path_for_load_path(load_path: Path) -> Path | None:
    manifest_path = (
        load_path
        if load_path.name == _OPENCLAW_PLUGIN_MANIFEST_FILENAME
        else load_path / _OPENCLAW_PLUGIN_MANIFEST_FILENAME
    )
    return manifest_path if manifest_path.is_file() else None


def _plugin_bundle_manifest_path_for_load_path(
    load_path: Path,
) -> tuple[str, Path, Path] | None:
    if load_path.is_file():
        for bundle_format, relative_path in _OPENCLAW_BUNDLE_MANIFEST_RELATIVE_PATHS.items():
            if (
                load_path.name == relative_path.name
                and load_path.parent.name == relative_path.parent.name
            ):
                return bundle_format, load_path, load_path.parent.parent
        return None
    for bundle_format, relative_path in _OPENCLAW_BUNDLE_MANIFEST_RELATIVE_PATHS.items():
        manifest_path = load_path / relative_path
        if manifest_path.is_file():
            return bundle_format, manifest_path, load_path
    if _plugin_manifestless_claude_bundle_root(load_path):
        return "claude", load_path / _OPENCLAW_BUNDLE_MANIFEST_RELATIVE_PATHS["claude"], load_path
    return None


def _plugin_manifestless_claude_bundle_root(load_path: Path) -> bool:
    if not load_path.is_dir():
        return False
    if (load_path / _OPENCLAW_PLUGIN_MANIFEST_FILENAME).exists():
        return False
    if any(
        (load_path / candidate).exists()
        for candidate in _OPENCLAW_DEFAULT_PLUGIN_ENTRY_CANDIDATES
    ):
        return False
    return any((load_path / marker).exists() for marker in _OPENCLAW_MANIFESTLESS_CLAUDE_MARKERS)


def _plugin_bundle_path_list(value: object) -> list[str]:
    if isinstance(value, str):
        text = value.strip()
        return [text] if text else []
    return _plugin_manifest_string_list(value)


def _plugin_bundle_merge_path_lists(*groups: list[str]) -> list[str]:
    return _dedupe_cli_strings([entry for group in groups for entry in group])


def _plugin_bundle_has_inline_capability(value: object) -> bool:
    if isinstance(value, str):
        return bool(value.strip())
    if isinstance(value, list):
        return bool(value)
    if isinstance(value, dict):
        return bool(value)
    return value is True


def _plugin_bundle_existing_defaults(root_dir: Path, defaults: list[str]) -> list[str]:
    return [relative for relative in defaults if (root_dir / relative).exists()]


def _plugin_bundle_slug_id(raw_name: str | None, root_dir: Path) -> str:
    source = (raw_name or root_dir.name).strip().lower()
    slug = re.sub(r"[^a-z0-9]+", "-", source)
    slug = re.sub(r"-+", "-", slug).strip("-")
    return slug or "bundle-plugin"


def _plugin_bundle_codex_skills(manifest: dict[str, object], root_dir: Path) -> list[str]:
    declared = _plugin_bundle_path_list(manifest.get("skills"))
    if declared:
        return declared
    return ["skills"] if (root_dir / "skills").exists() else []


def _plugin_bundle_codex_hooks(manifest: dict[str, object], root_dir: Path) -> list[str]:
    declared = _plugin_bundle_path_list(manifest.get("hooks"))
    if declared:
        return declared
    return ["hooks"] if (root_dir / "hooks").exists() else []


def _plugin_bundle_claude_component_paths(
    manifest: dict[str, object],
    root_dir: Path,
    key: str,
    defaults: list[str],
) -> list[str]:
    declared = _plugin_bundle_path_list(manifest.get(key))
    return _plugin_bundle_merge_path_lists(
        _plugin_bundle_existing_defaults(root_dir, defaults),
        declared,
    )


def _plugin_bundle_claude_skill_paths(
    manifest: dict[str, object],
    root_dir: Path,
) -> list[str]:
    return _plugin_bundle_merge_path_lists(
        _plugin_bundle_claude_component_paths(manifest, root_dir, "skills", ["skills"]),
        _plugin_bundle_claude_component_paths(manifest, root_dir, "commands", ["commands"]),
        _plugin_bundle_claude_component_paths(manifest, root_dir, "agents", ["agents"]),
        _plugin_bundle_claude_component_paths(
            manifest,
            root_dir,
            "outputStyles",
            ["output-styles"],
        ),
    )


def _plugin_bundle_markdown_files(root_dir: Path) -> list[Path]:
    files: list[Path] = []
    if not root_dir.is_dir():
        return files
    for current, dirs, filenames in os.walk(root_dir):
        dirs[:] = [dirname for dirname in dirs if not dirname.startswith(".")]
        current_path = Path(current)
        for filename in filenames:
            if filename.startswith(".") or not filename.lower().endswith(".md"):
                continue
            files.append(current_path / filename)
    return sorted(files, key=lambda path: str(path).lower())


def _plugin_bundle_frontmatter(raw: str) -> tuple[dict[str, str], str]:
    normalized = raw.replace("\r\n", "\n").replace("\r", "\n")
    if not normalized.startswith("---"):
        return {}, normalized.strip()
    end_index = normalized.find("\n---", 3)
    if end_index == -1:
        return {}, normalized.strip()
    frontmatter: dict[str, str] = {}
    for line in normalized[3:end_index].splitlines():
        key, separator, value = line.partition(":")
        if not separator:
            continue
        normalized_key = key.strip()
        normalized_value = value.strip().strip("\"'")
        if normalized_key:
            frontmatter[normalized_key] = normalized_value
    return frontmatter, normalized[end_index + 4 :].strip()


def _plugin_bundle_frontmatter_bool(value: str | None, fallback: bool = False) -> bool:
    normalized = (value or "").strip().lower()
    if normalized in {"true", "yes", "1"}:
        return True
    if normalized in {"false", "no", "0"}:
        return False
    return fallback


def _plugin_bundle_default_command_name(command_root: Path, file_path: Path) -> str:
    relative = file_path.relative_to(command_root)
    without_suffix = relative.with_suffix("")
    return ":".join(without_suffix.parts)


def _plugin_bundle_claude_commands(
    manifest: dict[str, object],
    root_dir: Path,
) -> list[str]:
    commands: list[str] = []
    for relative_root in _plugin_bundle_claude_component_paths(
        manifest,
        root_dir,
        "commands",
        ["commands"],
    ):
        command_root = root_dir / relative_root
        if not command_root.is_dir():
            continue
        for file_path in _plugin_bundle_markdown_files(command_root):
            try:
                raw = file_path.read_text(encoding="utf-8")
            except OSError:
                continue
            frontmatter, prompt = _plugin_bundle_frontmatter(raw)
            if _plugin_bundle_frontmatter_bool(frontmatter.get("disable-model-invocation")):
                continue
            if not prompt:
                continue
            command_name = (
                _optional_cli_string(frontmatter.get("name"))
                or _plugin_bundle_default_command_name(command_root, file_path)
            )
            if command_name:
                commands.append(command_name)
    return _dedupe_cli_strings(commands)


def _plugin_bundle_server_names_from_payload(
    raw: object,
    *,
    key: str,
) -> list[str]:
    if not isinstance(raw, dict):
        return []
    nested = raw.get(key)
    if isinstance(nested, dict):
        source = nested
    elif key == "mcpServers" and isinstance(raw.get("servers"), dict):
        source = raw["servers"]
    else:
        source = raw
    return [
        server_name
        for raw_name, raw_config in source.items()
        if (server_name := _optional_cli_string(raw_name)) is not None
        and isinstance(raw_config, dict)
    ]


def _plugin_bundle_server_config_paths(
    bundle_format: str,
    manifest: dict[str, object],
    root_dir: Path,
    *,
    key: str,
) -> list[str]:
    declared = _plugin_bundle_path_list(manifest.get(key))
    default_path = ".mcp.json" if key == "mcpServers" else ".lsp.json"
    if key == "lspServers" and bundle_format != "claude":
        return declared
    return _plugin_bundle_merge_path_lists(
        _plugin_bundle_existing_defaults(root_dir, [default_path]),
        declared,
    )


def _plugin_bundle_server_names(
    bundle_format: str,
    manifest: dict[str, object],
    root_dir: Path,
    *,
    key: str,
) -> list[str]:
    names: list[str] = []
    raw_inline = manifest.get(key)
    if isinstance(raw_inline, dict):
        names.extend(_plugin_bundle_server_names_from_payload(raw_inline, key=key))
    for relative_path in _plugin_bundle_server_config_paths(
        bundle_format,
        manifest,
        root_dir,
        key=key,
    ):
        loaded = _read_cli_json5_object(root_dir / relative_path)
        if loaded is None:
            continue
        names.extend(_plugin_bundle_server_names_from_payload(loaded, key=key))
    return _dedupe_cli_strings(names)


def _plugin_bundle_cursor_skill_paths(
    manifest: dict[str, object],
    root_dir: Path,
) -> list[str]:
    return _plugin_bundle_merge_path_lists(
        _plugin_bundle_existing_defaults(root_dir, ["skills"]),
        _plugin_bundle_path_list(manifest.get("skills")),
        _plugin_bundle_existing_defaults(root_dir, [".cursor/commands"]),
        _plugin_bundle_path_list(manifest.get("commands")),
    )


def _plugin_bundle_capabilities(
    bundle_format: str,
    manifest: dict[str, object],
    root_dir: Path,
    *,
    skills: list[str],
    hooks: list[str],
    settings_files: list[str],
) -> list[str]:
    capabilities: list[str] = []
    if skills:
        capabilities.append("skills")
    if bundle_format == "codex":
        if hooks:
            capabilities.append("hooks")
        if _plugin_bundle_has_inline_capability(manifest.get("mcpServers")) or (
            root_dir / ".mcp.json"
        ).exists():
            capabilities.append("mcpServers")
        if _plugin_bundle_has_inline_capability(manifest.get("apps")) or (
            root_dir / ".app.json"
        ).exists():
            capabilities.append("apps")
        return capabilities
    if bundle_format == "claude":
        if _plugin_bundle_claude_component_paths(
            manifest,
            root_dir,
            "commands",
            ["commands"],
        ):
            capabilities.append("commands")
        if _plugin_bundle_claude_component_paths(manifest, root_dir, "agents", ["agents"]):
            capabilities.append("agents")
        if hooks:
            capabilities.append("hooks")
        if _plugin_bundle_has_inline_capability(manifest.get("mcpServers")) or (
            _plugin_bundle_claude_component_paths(
                manifest,
                root_dir,
                "mcpServers",
                [".mcp.json"],
            )
        ):
            capabilities.append("mcpServers")
        if _plugin_bundle_has_inline_capability(manifest.get("lspServers")) or (
            _plugin_bundle_claude_component_paths(
                manifest,
                root_dir,
                "lspServers",
                [".lsp.json"],
            )
        ):
            capabilities.append("lspServers")
        if _plugin_bundle_claude_component_paths(
            manifest,
            root_dir,
            "outputStyles",
            ["output-styles"],
        ):
            capabilities.append("outputStyles")
        if settings_files:
            capabilities.append("settings")
        return capabilities
    if _plugin_bundle_existing_defaults(root_dir, [".cursor/commands"]) or _plugin_bundle_path_list(
        manifest.get("commands")
    ):
        capabilities.append("commands")
    if _plugin_bundle_existing_defaults(root_dir, [".cursor/agents"]) or _plugin_bundle_path_list(
        manifest.get("subagents") or manifest.get("agents")
    ):
        capabilities.append("agents")
    if _plugin_bundle_has_inline_capability(manifest.get("hooks")) or (
        root_dir / ".cursor" / "hooks.json"
    ).exists():
        capabilities.append("hooks")
    if _plugin_bundle_has_inline_capability(manifest.get("rules")) or (
        root_dir / ".cursor" / "rules"
    ).exists():
        capabilities.append("rules")
    if _plugin_bundle_has_inline_capability(manifest.get("mcpServers")) or (
        root_dir / ".mcp.json"
    ).exists():
        capabilities.append("mcpServers")
    return capabilities


def _plugin_bundle_manifest_record(
    bundle_format: str,
    manifest_path: Path,
    root_dir: Path,
    *,
    plugins_config: dict[str, object],
    config_snapshot: dict[str, object] | None = None,
) -> dict[str, object] | None:
    manifest = _read_cli_json5_object(manifest_path)
    if manifest is None:
        if bundle_format != "claude" or manifest_path.exists():
            return None
        manifest = {}
    interface_record = manifest.get("interface")
    interface_payload = interface_record if isinstance(interface_record, dict) else {}
    name = _optional_cli_string(manifest.get("name"))
    plugin_id = _plugin_bundle_slug_id(name, root_dir)
    description = (
        _optional_cli_string(manifest.get("description"))
        or _optional_cli_string(manifest.get("shortDescription"))
        or _optional_cli_string(interface_payload.get("shortDescription"))
        or ""
    )
    settings_files: list[str] = []
    if bundle_format == "codex":
        skills = _plugin_bundle_codex_skills(manifest, root_dir)
        hooks = _plugin_bundle_codex_hooks(manifest, root_dir)
    elif bundle_format == "claude":
        skills = _plugin_bundle_claude_skill_paths(manifest, root_dir)
        hooks = _plugin_bundle_claude_component_paths(
            manifest,
            root_dir,
            "hooks",
            ["hooks/hooks.json"],
        )
        settings_files = _plugin_bundle_existing_defaults(root_dir, ["settings.json"])
    else:
        skills = _plugin_bundle_cursor_skill_paths(manifest, root_dir)
        hooks = []
    bundle_capabilities = _plugin_bundle_capabilities(
        bundle_format,
        manifest,
        root_dir,
        skills=skills,
        hooks=hooks,
        settings_files=settings_files,
    )
    record: dict[str, object] = {
        "id": plugin_id,
        "name": name or plugin_id,
        "status": _plugin_manifest_status(
            {},
            plugin_id=plugin_id,
            plugins_config=plugins_config,
            config_snapshot=config_snapshot,
        ),
        "format": "bundle",
        "source": str(root_dir),
        "origin": "config",
        "description": description,
        "capabilities": [f"bundle:{capability}" for capability in bundle_capabilities],
        "parityStatus": "metadata",
        "rootDir": str(root_dir),
        "manifestPath": str(manifest_path),
        "bundleFormat": bundle_format,
        "bundleCapabilities": bundle_capabilities,
        "skills": skills,
        "hooks": hooks,
    }
    version = _optional_cli_string(manifest.get("version"))
    if version is not None:
        record["version"] = version
    if settings_files:
        record["settingsFiles"] = settings_files
    if bundle_format == "claude":
        commands = _plugin_bundle_claude_commands(manifest, root_dir)
        if commands:
            record["commands"] = commands
    mcp_servers = _plugin_bundle_server_names(
        bundle_format,
        manifest,
        root_dir,
        key="mcpServers",
    )
    if mcp_servers:
        record["mcpServers"] = mcp_servers
    lsp_servers = _plugin_bundle_server_names(
        bundle_format,
        manifest,
        root_dir,
        key="lspServers",
    )
    if lsp_servers:
        record["lspServers"] = lsp_servers
    return record


def _plugin_manifest_status(
    manifest: dict[str, object],
    *,
    plugin_id: str,
    plugins_config: dict[str, object],
    config_snapshot: dict[str, object] | None = None,
    origin: str = "config",
) -> str:
    if plugins_config.get("enabled") is False:
        return "disabled"
    deny = plugins_config.get("deny")
    deny_values = {str(value) for value in deny} if isinstance(deny, list) else set()
    if plugin_id in deny_values:
        return "disabled"
    entries = plugins_config.get("entries")
    entry_records = entries if isinstance(entries, dict) else {}
    entry = entry_records.get(plugin_id)
    entry_payload = entry if isinstance(entry, dict) else {}
    if entry_payload.get("enabled") is False:
        return "disabled"
    if entry_payload.get("enabled") is True:
        return "loaded"
    allow = plugins_config.get("allow")
    allow_values = {str(value) for value in allow} if isinstance(allow, list) else set()
    if origin == "bundled":
        if _plugin_manifest_has_enabled_channel(manifest, config_snapshot):
            return "loaded"
        if _plugin_manifest_configured_channel_auto_reason(
            manifest,
            config_snapshot,
        ) is not None:
            return "loaded"
        if allow_values and plugin_id not in allow_values:
            return "disabled"
        return "loaded" if manifest.get("enabledByDefault") is True else "disabled"
    if plugin_id in allow_values:
        return "loaded"
    if _plugin_manifest_has_enabled_channel(manifest, config_snapshot):
        return "loaded"
    return "loaded" if manifest.get("enabledByDefault") is True else "disabled"


def _plugin_config_entry_payload(
    plugins_config: dict[str, object],
    plugin_id: str,
) -> dict[str, object]:
    entries = plugins_config.get("entries")
    entry_records = entries if isinstance(entries, dict) else {}
    entry = entry_records.get(plugin_id)
    return entry if isinstance(entry, dict) else {}


def _plugin_config_string_set(
    plugins_config: dict[str, object],
    key: str,
) -> set[str]:
    value = plugins_config.get(key)
    if not isinstance(value, list):
        return set()
    return {
        text
        for item in value
        if (text := _optional_cli_string(item)) is not None
    }


def _plugin_config_slot_reason(
    plugins_config: dict[str, object],
    plugin_id: str,
) -> str | None:
    slots = plugins_config.get("slots")
    slot_payload = slots if isinstance(slots, dict) else {}
    if _optional_cli_string(slot_payload.get("memory")) == plugin_id:
        return "selected memory slot"
    if _optional_cli_string(slot_payload.get("contextEngine")) == plugin_id:
        return "selected context engine slot"
    return None


def _plugin_configured_record_status(
    *,
    plugin_id: str,
    plugins_config: dict[str, object],
) -> str:
    if plugins_config.get("enabled") is False:
        return "disabled"
    if plugin_id in _plugin_config_string_set(plugins_config, "deny"):
        return "disabled"
    entry_payload = _plugin_config_entry_payload(plugins_config, plugin_id)
    if entry_payload.get("enabled") is False:
        return "disabled"
    if _plugin_config_slot_reason(plugins_config, plugin_id) is not None:
        return "loaded"
    allow_values = _plugin_config_string_set(plugins_config, "allow")
    if allow_values and plugin_id not in allow_values:
        return "disabled"
    return "loaded"


def _plugin_activation_state_payload(
    *,
    plugin_id: str,
    plugins_config: dict[str, object],
    status: str,
    origin: str = "config",
    enabled_by_default: bool | None = None,
    channel_enabled_by_config: bool = False,
    auto_enabled_reason: str | None = None,
) -> dict[str, object]:
    entry_payload = _plugin_config_entry_payload(plugins_config, plugin_id)
    allow_values = _plugin_config_string_set(plugins_config, "allow")
    slot_reason = _plugin_config_slot_reason(plugins_config, plugin_id)
    explicitly_enabled = (
        entry_payload.get("enabled") is True
        or (origin == "bundled" and channel_enabled_by_config)
        or (origin != "bundled" and plugin_id in allow_values)
        or slot_reason is not None
    )
    activated = status == "loaded"
    source = "explicit" if activated and explicitly_enabled else "default"
    reason: str | None = None
    if plugins_config.get("enabled") is False:
        activated = False
        source = "disabled"
        reason = "plugins disabled"
    elif plugin_id in _plugin_config_string_set(plugins_config, "deny"):
        activated = False
        source = "disabled"
        reason = "blocked by denylist"
    elif entry_payload.get("enabled") is False:
        activated = False
        source = "disabled"
        reason = "disabled in config"
    elif activated and slot_reason is not None:
        reason = slot_reason
    elif allow_values and plugin_id not in allow_values and not (
        origin == "bundled" and (channel_enabled_by_config or auto_enabled_reason is not None)
    ):
        activated = False
        source = "disabled"
        reason = "not in allowlist"
    elif activated and entry_payload.get("enabled") is True:
        reason = "enabled in config"
    elif activated and origin == "bundled" and channel_enabled_by_config:
        reason = "channel enabled in config"
    elif activated and auto_enabled_reason is not None:
        source = "auto"
        reason = auto_enabled_reason
    elif activated and origin != "bundled" and plugin_id in allow_values:
        reason = "selected in allowlist"
    elif origin == "bundled" and activated and enabled_by_default is True:
        reason = "bundled default enablement"
    elif origin == "bundled" and not activated:
        source = "disabled"
        reason = "bundled (disabled by default)"
    elif not activated:
        source = "disabled"

    payload: dict[str, object] = {
        "activated": activated,
        "explicitlyEnabled": explicitly_enabled,
        "activationSource": source,
    }
    if reason is not None:
        payload["activationReason"] = reason
    return payload


def _plugin_record_from_openclaw_manifest(
    manifest_path: Path,
    *,
    plugins_config: dict[str, object],
    config_snapshot: dict[str, object] | None = None,
    diagnostics: list[dict[str, object]] | None = None,
    origin: str = "config",
) -> dict[str, object] | None:
    try:
        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return None
    if not isinstance(manifest, dict):
        return None
    plugin_id = _optional_cli_string(manifest.get("id"))
    config_schema = manifest.get("configSchema")
    if plugin_id is None or not isinstance(config_schema, dict):
        return None
    contracts = _plugin_manifest_contracts(manifest)
    capabilities = _plugin_manifest_capabilities(manifest, contracts)
    package_metadata = _plugin_package_json_metadata(manifest_path.parent)
    package_openclaw = package_metadata.get("openclaw")
    current_version = (
        _optional_cli_string(config_snapshot.get("serverVersion"))
        if config_snapshot is not None
        else None
    ) or __version__
    min_host_diagnostic = _plugin_min_host_version_diagnostic(
        package_openclaw,
        current_version=current_version,
        plugin_id=plugin_id,
        source=str(manifest_path),
    )
    if min_host_diagnostic is not None:
        if diagnostics is not None:
            diagnostics.append(min_host_diagnostic)
        return None
    description = (
        _optional_cli_string(manifest.get("description"))
        or _optional_cli_string(package_metadata.get("description"))
        or ""
    )
    channel_enabled_by_config = _plugin_manifest_has_enabled_channel(
        manifest,
        config_snapshot,
    )
    auto_enabled_reason = _plugin_manifest_configured_channel_auto_reason(
        manifest,
        config_snapshot,
    )
    status = _plugin_manifest_status(
        manifest,
        plugin_id=plugin_id,
        plugins_config=plugins_config,
        config_snapshot=config_snapshot,
        origin=origin,
    )
    record: dict[str, object] = {
        "id": plugin_id,
        "name": (
            _optional_cli_string(manifest.get("name"))
            or _optional_cli_string(package_metadata.get("name"))
            or plugin_id
        ),
        "status": status,
        "format": "openclaw",
        "source": str(manifest_path),
        "origin": origin,
        "description": description,
        "capabilities": capabilities,
        "parityStatus": "metadata",
        "rootDir": str(manifest_path.parent),
        "manifestPath": str(manifest_path),
        "configSchema": True,
    }
    record.update(
        _plugin_activation_state_payload(
            plugin_id=plugin_id,
            plugins_config=plugins_config,
            status=status,
            origin=origin,
            enabled_by_default=manifest.get("enabledByDefault") is True,
            channel_enabled_by_config=channel_enabled_by_config,
            auto_enabled_reason=auto_enabled_reason,
        )
    )
    version = _optional_cli_string(manifest.get("version")) or _optional_cli_string(
        package_metadata.get("version")
    )
    if version is not None:
        record["version"] = version
    for metadata_key, metadata_value in _plugin_package_openclaw_record_metadata(
        package_openclaw,
        plugin_root=manifest_path.parent,
    ).items():
        record[metadata_key] = metadata_value
    for metadata_key, metadata_value in _plugin_manifest_root_metadata(
        manifest,
        root_dir=manifest_path.parent,
    ).items():
        record[metadata_key] = metadata_value
    doctor_contract_api = _plugin_doctor_contract_api_artifact(manifest_path.parent)
    if doctor_contract_api is not None:
        record["doctorContractApi"] = doctor_contract_api
    if contracts:
        record["contracts"] = contracts
    tool_names = contracts.get("tools")
    if isinstance(tool_names, list):
        record["toolNames"] = list(tool_names)
    command_aliases = _plugin_manifest_command_aliases(manifest.get("commandAliases"))
    if command_aliases:
        record["commandAliases"] = command_aliases
    activation = _plugin_manifest_activation(manifest.get("activation"))
    if activation:
        record["activation"] = activation
    setup = _plugin_manifest_setup(manifest.get("setup"))
    if setup:
        record["setup"] = setup
    qa_runners = _plugin_manifest_qa_runners(manifest.get("qaRunners"))
    if qa_runners:
        record["qaRunners"] = qa_runners
    channel_configs = _plugin_manifest_channel_configs(manifest.get("channelConfigs"))
    channel_configs = _merge_package_channel_meta(channel_configs, package_openclaw)
    if channel_configs:
        record["channelConfigs"] = channel_configs
    model_support = _plugin_manifest_model_support(manifest.get("modelSupport"))
    if model_support:
        record["modelSupport"] = model_support
    config_contracts = _plugin_manifest_config_contracts(manifest.get("configContracts"))
    if config_contracts:
        record["configContracts"] = config_contracts
    tool_metadata = _plugin_manifest_tool_metadata(manifest.get("toolMetadata"))
    if tool_metadata:
        record["toolMetadata"] = tool_metadata
    for metadata_key, metadata_value in _plugin_manifest_auth_env_metadata(manifest).items():
        record[metadata_key] = metadata_value
    for key in (
        "commands",
        "cliCommands",
        "services",
        "gatewayMethods",
        "bundleCapabilities",
    ):
        values = _plugin_record_string_list(manifest, key)
        if values:
            record[key] = values
    route_count = _plugin_record_http_route_count(manifest)
    if route_count:
        record["httpRoutes"] = route_count
    runtime_dependencies, install_root = _plugin_manifest_runtime_dependencies(manifest_path)
    if runtime_dependencies:
        record["runtimeDependencies"] = runtime_dependencies
        if install_root is not None:
            record["runtimeDependencyInstallRoot"] = str(install_root)
    return record


def _plugin_manifest_records_from_config_snapshot(
    plugins_config: dict[str, object],
    *,
    config_snapshot: dict[str, object],
    diagnostics: list[dict[str, object]] | None = None,
) -> list[dict[str, object]]:
    records: list[dict[str, object]] = []
    seen_ids: set[str] = set()
    for load_path in _plugin_manifest_load_paths(plugins_config):
        manifest_path = _plugin_manifest_path_for_load_path(load_path)
        if manifest_path is not None:
            record = _plugin_record_from_openclaw_manifest(
                manifest_path,
                plugins_config=plugins_config,
                config_snapshot=config_snapshot,
                diagnostics=diagnostics,
            )
        elif bundle_match := _plugin_bundle_manifest_path_for_load_path(load_path):
            bundle_format, bundle_manifest_path, bundle_root_dir = bundle_match
            record = _plugin_bundle_manifest_record(
                bundle_format,
                bundle_manifest_path,
                bundle_root_dir,
                plugins_config=plugins_config,
                config_snapshot=config_snapshot,
            )
        else:
            continue
        if record is None:
            continue
        plugin_id = str(record.get("id") or "")
        if not plugin_id or plugin_id in seen_ids:
            continue
        seen_ids.add(plugin_id)
        records.append(record)
    return records


def _plugin_bundled_manifest_records_from_env(
    plugins_config: dict[str, object],
    *,
    config_snapshot: dict[str, object],
    diagnostics: list[dict[str, object]] | None = None,
) -> list[dict[str, object]]:
    records: list[dict[str, object]] = []
    seen_ids: set[str] = set()
    seen_paths: set[Path] = set()
    for bundled_root in _cli_bundled_plugin_roots():
        try:
            children = sorted(bundled_root.iterdir(), key=lambda path: path.name.lower())
        except OSError:
            continue
        for child in children:
            if not child.is_dir():
                continue
            try:
                resolved_child = child.resolve(strict=False)
            except OSError:
                resolved_child = child
            if resolved_child in seen_paths:
                continue
            seen_paths.add(resolved_child)
            manifest_path = _plugin_manifest_path_for_load_path(child)
            if manifest_path is None:
                continue
            record = _plugin_record_from_openclaw_manifest(
                manifest_path,
                plugins_config=plugins_config,
                config_snapshot=config_snapshot,
                diagnostics=diagnostics,
                origin="bundled",
            )
            if record is None:
                continue
            plugin_id = str(record.get("id") or "")
            if not plugin_id or plugin_id in seen_ids:
                continue
            seen_ids.add(plugin_id)
            records.append(record)
    return records


def _plugin_manifest_record_from_install_path(
    plugin_id: str,
    install_path: str | None,
    *,
    plugins_config: dict[str, object],
    config_snapshot: dict[str, object],
    diagnostics: list[dict[str, object]] | None,
) -> dict[str, object] | None:
    if install_path is None:
        return None
    expanded = os.path.expandvars(os.path.expanduser(install_path))
    try:
        load_path = Path(expanded).resolve(strict=False)
    except OSError:
        load_path = Path(expanded)
    manifest_path = _plugin_manifest_path_for_load_path(load_path)
    if manifest_path is not None:
        record = _plugin_record_from_openclaw_manifest(
            manifest_path,
            plugins_config=plugins_config,
            config_snapshot=config_snapshot,
            diagnostics=diagnostics,
        )
    elif bundle_match := _plugin_bundle_manifest_path_for_load_path(load_path):
        bundle_format, bundle_manifest_path, bundle_root_dir = bundle_match
        record = _plugin_bundle_manifest_record(
            bundle_format,
            bundle_manifest_path,
            bundle_root_dir,
            plugins_config=plugins_config,
            config_snapshot=config_snapshot,
        )
    else:
        return None
    if record is None or str(record.get("id") or "") != plugin_id:
        return None
    return record


def _plugin_records_from_config_snapshot(
    snapshot: dict[str, object],
    *,
    diagnostics: list[dict[str, object]] | None = None,
) -> list[dict[str, object]]:
    plugins = snapshot.get("plugins")
    plugins_config = dict(plugins) if isinstance(plugins, dict) else {}
    manifest_records = _plugin_manifest_records_from_config_snapshot(
        plugins_config,
        config_snapshot=snapshot,
        diagnostics=diagnostics,
    )
    bundled_manifest_records = _plugin_bundled_manifest_records_from_env(
        plugins_config,
        config_snapshot=snapshot,
        diagnostics=diagnostics,
    )
    records_by_id = {
        str(record.get("id") or ""): dict(record)
        for record in manifest_records
        if str(record.get("id") or "")
    }
    for bundled_record in bundled_manifest_records:
        plugin_id = str(bundled_record.get("id") or "")
        if plugin_id and plugin_id not in records_by_id:
            records_by_id[plugin_id] = dict(bundled_record)
    entries = plugins_config.get("entries")
    entry_records = entries if isinstance(entries, dict) else {}
    installs = plugins_config.get("installs")
    install_records = installs if isinstance(installs, dict) else {}
    plugin_ids = sorted(
        {
            *(str(key) for key in entry_records),
            *(str(key) for key in install_records),
        }
    )
    for plugin_id in plugin_ids:
        entry = entry_records.get(plugin_id)
        entry_payload = entry if isinstance(entry, dict) else {}
        install = install_records.get(plugin_id)
        install_payload = install if isinstance(install, dict) else {}
        install_source = _optional_cli_string(install_payload.get("source"))
        install_path = _optional_cli_string(install_payload.get("installPath"))
        source_path = _optional_cli_string(install_payload.get("sourcePath"))
        version = _optional_cli_string(install_payload.get("version"))
        if plugin_id not in records_by_id:
            for candidate_path in (install_path, source_path):
                install_manifest_record = _plugin_manifest_record_from_install_path(
                    plugin_id,
                    candidate_path,
                    plugins_config=plugins_config,
                    config_snapshot=snapshot,
                    diagnostics=diagnostics,
                )
                if install_manifest_record is not None:
                    records_by_id[plugin_id] = install_manifest_record
                    break
        status = _plugin_configured_record_status(
            plugin_id=plugin_id,
            plugins_config=plugins_config,
        )
        description = (
            f"Installed {install_source} plugin."
            if install_source is not None
            else "Configured plugin."
        )
        record: dict[str, object] = {
            "id": plugin_id,
            "name": plugin_id,
            "status": status,
            "format": "openclaw-native",
            "source": install_path or source_path or f"plugins.entries.{plugin_id}",
            "origin": "config",
            "description": description,
            "capabilities": [],
            "parityStatus": "configured",
        }
        record.update(
            _plugin_activation_state_payload(
                plugin_id=plugin_id,
                plugins_config=plugins_config,
                status=status,
            )
        )
        if version is not None:
            record["version"] = version
        if install_payload:
            record["install"] = dict(install_payload)
        shape = _optional_cli_string(entry_payload.get("shape"))
        if shape is not None:
            record["shape"] = shape
        if entry_payload.get("usesLegacyBeforeAgentStart") is True:
            record["usesLegacyBeforeAgentStart"] = True
        existing = records_by_id.get(plugin_id)
        if existing is not None:
            merged = dict(existing)
            status = (
                _plugin_configured_record_status(
                    plugin_id=plugin_id,
                    plugins_config=plugins_config,
                )
                if install_payload
                else _plugin_manifest_status(
                    merged,
                    plugin_id=plugin_id,
                    plugins_config=plugins_config,
                    config_snapshot=snapshot,
                    origin=_optional_cli_string(merged.get("origin")) or "config",
                )
            )
            merged["status"] = status
            merged.update(
                _plugin_activation_state_payload(
                    plugin_id=plugin_id,
                    plugins_config=plugins_config,
                    status=status,
                    origin=_optional_cli_string(merged.get("origin")) or "config",
                    enabled_by_default=merged.get("enabledByDefault") is True,
                )
            )
            if version is not None:
                merged["version"] = version
            if install_payload:
                merged["install"] = dict(install_payload)
            if shape is not None:
                merged["shape"] = shape
            if entry_payload.get("usesLegacyBeforeAgentStart") is True:
                merged["usesLegacyBeforeAgentStart"] = True
            records_by_id[plugin_id] = merged
        else:
            records_by_id[plugin_id] = record
    return [records_by_id[plugin_id] for plugin_id in sorted(records_by_id)]


def _openclaw_plugin_status(parity_status: str) -> str:
    normalized = parity_status.strip().lower()
    if normalized in {"ready", "partial"}:
        return "loaded"
    if normalized == "error":
        return "error"
    return "disabled"


def _first_text_line(value: object, *, limit: int = 220) -> str:
    text = str(value or "").strip()
    if not text:
        return ""
    first_line = next((line.strip() for line in text.splitlines() if line.strip()), "")
    if len(first_line) <= limit:
        return first_line
    return first_line[: max(0, limit - 3)].rstrip() + "..."


def _watch_base_url(*, url: str | None, host: str, port: int) -> str:
    if url:
        return str(url).rstrip("/")
    return f"http://{host}:{port}"


def _watch_decode_error_body(exc: HTTPError) -> str:
    try:
        body = exc.read().decode("utf-8", errors="replace").strip()
    except OSError:
        body = ""
    if not body:
        return exc.reason or "request failed"
    try:
        payload = json.loads(body)
    except json.JSONDecodeError:
        return body
    if isinstance(payload, dict):
        detail = payload.get("detail")
        if isinstance(detail, str) and detail.strip():
            return detail.strip()
    return body


def _watch_api_json(
    base_url: str,
    path: str,
    *,
    method: str = "GET",
    payload: object | None = None,
    timeout_seconds: float = 60.0,
    allow_timeout: bool = False,
) -> Any:
    body: bytes | None = None
    headers = {"Accept": "application/json"}
    if payload is not None:
        body = json.dumps(payload).encode("utf-8")
        headers["Content-Type"] = "application/json"
    elif method != "GET":
        body = b""
    request = Request(f"{base_url}{path}", data=body, headers=headers, method=method)
    try:
        with urlopen(request, timeout=timeout_seconds) as response:
            response_text = response.read().decode("utf-8", errors="replace")
    except HTTPError as exc:
        detail = _watch_decode_error_body(exc)
        raise RuntimeError(f"{method} {path} failed ({exc.code}): {detail}") from exc
    except TimeoutError as exc:
        if allow_timeout:
            return {"timed_out": True}
        raise RuntimeError(f"{method} {path} timed out against {base_url}") from exc
    except URLError as exc:
        reason = getattr(exc, "reason", exc)
        if allow_timeout and isinstance(reason, TimeoutError):
            return {"timed_out": True}
        raise RuntimeError(f"Could not reach OpenZues at {base_url}: {reason}") from exc

    if not response_text.strip():
        return None
    return json.loads(response_text)


def _browser_command() -> str:
    command = shutil.which("agent-browser.cmd") or shutil.which("agent-browser")
    if command is None:
        raise RuntimeError(
            "agent-browser is not installed or not on PATH. Install it before using --browser."
        )
    return command


def _run_browser_command(
    args: list[str],
    *,
    session_name: str,
    timeout_seconds: float = 60.0,
    allow_failure: bool = False,
) -> str:
    command = _browser_command()
    invocation = [command, "--session", session_name, *args]
    process_args = invocation
    if os.name == "nt":
        if _browser_command_expects_output(args):
            return _run_windows_browser_command_direct(
                invocation,
                args=args,
                timeout_seconds=timeout_seconds,
                allow_failure=allow_failure,
            )
        return _run_windows_browser_command(
            invocation,
            args=args,
            timeout_seconds=timeout_seconds,
            allow_failure=allow_failure,
        )
    try:
        completed = subprocess.run(
            process_args,
            capture_output=True,
            text=True,
            timeout=timeout_seconds,
            check=False,
        )
    except subprocess.TimeoutExpired as exc:
        raise RuntimeError(
            f"agent-browser {' '.join(args)} timed out after {timeout_seconds:.0f}s."
        ) from exc
    output = (completed.stdout or "").strip()
    error_output = (completed.stderr or "").strip()
    if completed.returncode != 0 and not allow_failure:
        detail = error_output or output or "browser command failed"
        raise RuntimeError(f"agent-browser {' '.join(args)} failed: {detail}")
    return output or error_output


def _powershell_single_quote(value: str) -> str:
    return "'" + value.replace("'", "''") + "'"


def _browser_command_expects_output(args: list[str]) -> bool:
    if not args:
        return False
    if args[0] in {"get", "eval", "snapshot"}:
        return True
    if args[0] in {"errors", "console"} and "--clear" not in args[1:]:
        return True
    return False


def _decode_browser_capture_bytes(data: bytes) -> str:
    if not data:
        return ""
    if data.startswith(codecs.BOM_UTF8):
        return data.decode("utf-8-sig", errors="replace").strip()
    if (
        data.startswith(codecs.BOM_UTF16_LE)
        or data.startswith(codecs.BOM_UTF16_BE)
        or b"\x00" in data
    ):
        for encoding in ("utf-16", "utf-16-le", "utf-16-be"):
            try:
                return data.decode(encoding).strip()
            except UnicodeDecodeError:
                continue
    return data.decode("utf-8", errors="replace").strip()


def _read_browser_capture_text(path: Path) -> str:
    try:
        data = path.read_bytes()
    except OSError:
        return ""
    return _decode_browser_capture_bytes(data)


def _run_windows_browser_command_direct(
    invocation: list[str],
    *,
    args: list[str],
    timeout_seconds: float,
    allow_failure: bool,
) -> str:
    try:
        completed = subprocess.run(
            invocation,
            capture_output=True,
            text=False,
            timeout=timeout_seconds,
            check=False,
        )
    except subprocess.TimeoutExpired as exc:
        raise RuntimeError(
            f"agent-browser {' '.join(args)} timed out after {timeout_seconds:.0f}s."
        ) from exc
    output = _decode_browser_capture_bytes(completed.stdout or b"")
    error_output = _decode_browser_capture_bytes(completed.stderr or b"")
    if completed.returncode != 0 and not allow_failure:
        detail = error_output or output or "browser command failed"
        raise RuntimeError(f"agent-browser {' '.join(args)} failed: {detail}")
    return output or error_output


def _run_windows_browser_command(
    invocation: list[str],
    *,
    args: list[str],
    timeout_seconds: float,
    allow_failure: bool,
) -> str:
    argument_list = ", ".join(_powershell_single_quote(item) for item in invocation[1:])
    stdout_capture = Path(tempfile.mkstemp(prefix="openzues-browser-out-", suffix=".log")[1])
    stderr_capture = Path(tempfile.mkstemp(prefix="openzues-browser-err-", suffix=".log")[1])
    process_script = [
        "$ErrorActionPreference = 'Stop'",
        "$startArgs = @{",
        f"  FilePath = {_powershell_single_quote(invocation[0])}",
        "  PassThru = $true",
        "  WindowStyle = 'Hidden'",
        f"  RedirectStandardOutput = {_powershell_single_quote(str(stdout_capture))}",
        f"  RedirectStandardError = {_powershell_single_quote(str(stderr_capture))}",
        "}",
    ]
    if argument_list:
        process_script.append(f"$startArgs.ArgumentList = @({argument_list})")
    process_script.extend(
        [
            "$process = Start-Process @startArgs",
            f"if (-not $process.WaitForExit({int(timeout_seconds * 1000)})) {{",
            "  try { $process.Kill() } catch {}",
            "  exit 124",
            "}",
            "exit $process.ExitCode",
        ]
    )
    ps_command = "\n".join(process_script)
    try:
        completed = subprocess.run(
            ["powershell.exe", "-NoProfile", "-Command", ps_command],
            capture_output=True,
            text=True,
            timeout=timeout_seconds + 5.0,
            check=False,
        )
    except subprocess.TimeoutExpired as exc:
        raise RuntimeError(
            f"agent-browser {' '.join(args)} timed out after {timeout_seconds:.0f}s."
        ) from exc
    try:
        wrapper_output = ((completed.stdout or "") + "\n" + (completed.stderr or "")).strip()
        child_stdout = _read_browser_capture_text(stdout_capture)
        child_stderr = _read_browser_capture_text(stderr_capture)
        child_output = "\n".join(
            part for part in (child_stdout, child_stderr) if str(part).strip()
        ).strip()
        if completed.returncode == 124 and not allow_failure:
            raise RuntimeError(
                f"agent-browser {' '.join(args)} timed out after {timeout_seconds:.0f}s."
            )
        if completed.returncode != 0 and not allow_failure:
            detail = child_output or wrapper_output or "browser command failed"
            raise RuntimeError(f"agent-browser {' '.join(args)} failed: {detail}")
        return child_output or wrapper_output
    finally:
        for capture_path in (stdout_capture, stderr_capture):
            try:
                capture_path.unlink(missing_ok=True)
            except OSError:
                pass


def _try_browser_command(
    args: list[str],
    *,
    session_name: str,
    timeout_seconds: float = 10.0,
) -> str:
    try:
        return _run_browser_command(
            args,
            session_name=session_name,
            timeout_seconds=timeout_seconds,
            allow_failure=True,
        )
    except RuntimeError:
        return ""


def _strip_browser_value(value: str) -> str:
    text = value.strip()
    if text.startswith('"') and text.endswith('"') and len(text) >= 2:
        return text[1:-1]
    return text


def _browser_url_value(value: str) -> str:
    text = _strip_browser_value(value)
    if re.match(r"^[a-zA-Z][a-zA-Z0-9+.-]*://", text):
        return text
    return ""


def _browser_title_value(value: str) -> str:
    text = _strip_browser_value(value)
    if not text or "\x00" in text or "HRESULT" in text or "failed" in text.lower():
        return ""
    return text


def _browser_probe_status(value: str, *, allowed: set[str]) -> str:
    text = _strip_browser_value(value)
    return text if text in allowed else ""


def _browser_screenshot_path(output: str) -> str | None:
    marker = "Screenshot saved to "
    for line in output.splitlines():
        line = line.strip()
        if marker in line:
            return line.split(marker, 1)[1].strip()
    return None


def _browser_screenshot_signal(path_text: str | None) -> tuple[str | None, int | None]:
    if not path_text:
        return None, None
    try:
        size_bytes = Path(path_text).expanduser().stat().st_size
    except OSError:
        return None, None
    if size_bytes >= _BROWSER_RENDERED_SCREENSHOT_MIN_BYTES:
        return "rendered", size_bytes
    if size_bytes <= _BROWSER_BLANK_SCREENSHOT_MAX_BYTES:
        return "likely_blank", size_bytes
    return "unknown", size_bytes


def _watch_http_content_signal(browser_url: str, *, timeout_seconds: float = 20.0) -> bool:
    request = Request(browser_url, headers={"Accept": "text/html"})
    try:
        with urlopen(request, timeout=timeout_seconds) as response:
            response_text = response.read().decode("utf-8", errors="replace")
    except (HTTPError, URLError, TimeoutError):
        return False
    normalized = response_text.lower()
    return len(response_text.strip()) >= 200 and "<body" in normalized


def _summarize_browser_snapshot(output: str, *, limit: int = 8) -> str:
    truncated_output = output[:_BROWSER_SNAPSHOT_CHAR_LIMIT]
    lines: list[str] = []
    for raw_line in truncated_output.splitlines():
        line = raw_line.strip()
        if not line:
            continue
        lines.append(line)
        if len(lines) >= _BROWSER_SNAPSHOT_LINE_LIMIT:
            break
    if not lines:
        return "No interactive browser snapshot lines were returned."
    interesting = [
        line
        for line in lines
        if line.startswith("- ")
        or line.startswith("[")
        or 'heading "' in line
        or 'button "' in line
        or 'textbox "' in line
    ]
    sample = interesting[:limit] if interesting else lines[:limit]
    summary = " | ".join(sample)
    if len(output) > len(truncated_output) or len(lines) >= _BROWSER_SNAPSHOT_LINE_LIMIT:
        summary += " | [snapshot truncated]"
    return summary


def _watch_browser_verify(
    *,
    browser_url: str,
    session_name: str,
) -> dict[str, Any]:
    # Watch sessions are unique by default, so clearing prior error/console state is usually
    # redundant and has proven flaky on some Windows agent-browser installs.
    _run_browser_command(["open", browser_url], session_name=session_name, timeout_seconds=15.0)
    _run_browser_command(
        ["wait", "2000"],
        session_name=session_name,
        timeout_seconds=5.0,
        allow_failure=True,
    )

    page_url = _browser_url_value(
        _try_browser_command(["get", "url"], session_name=session_name, timeout_seconds=3.0)
    )
    title = _browser_title_value(
        _try_browser_command(["get", "title"], session_name=session_name, timeout_seconds=3.0)
    )
    has_content = _browser_probe_status(
        _try_browser_command(
            [
                "eval",
                (
                    "document.body && document.body.innerText.trim().length > 0 "
                    "? 'HAS_CONTENT' : 'BLANK'"
                ),
            ],
            session_name=session_name,
            timeout_seconds=3.0,
        ),
        allowed={"HAS_CONTENT", "BLANK"},
    )
    overlay_status = _browser_probe_status(
        _try_browser_command(
            [
                "eval",
                "document.querySelector('[data-nextjs-dialog], .vite-error-overlay, "
                "#webpack-dev-server-client-overlay') ? 'ERROR_OVERLAY' : 'OK'",
            ],
            session_name=session_name,
            timeout_seconds=3.0,
        ),
        allowed={"OK", "ERROR_OVERLAY"},
    )
    screenshot_path: str | None = None
    screenshot_error: str | None = None
    try:
        screenshot_target = (
            Path(tempfile.gettempdir())
            / f"openzues-watch-{session_name}-{int(time.time() * 1000)}.png"
        )
        screenshot_output = _run_browser_command(
            ["--annotate", "screenshot", str(screenshot_target)],
            session_name=session_name,
            timeout_seconds=12.0,
        )
        screenshot_path = _browser_screenshot_path(screenshot_output) or str(screenshot_target)
    except RuntimeError as exc:
        screenshot_error = str(exc)
    screenshot_signal, screenshot_bytes = _browser_screenshot_signal(screenshot_path)
    http_content_visible = _watch_http_content_signal(browser_url)

    snapshot_summary = "Browser snapshot unavailable."
    snapshot_error: str | None = None
    try:
        snapshot_output = _run_browser_command(
            ["snapshot", "-i"],
            session_name=session_name,
            timeout_seconds=4.0,
            allow_failure=True,
        )
        if snapshot_output:
            snapshot_summary = _summarize_browser_snapshot(snapshot_output)
    except RuntimeError as exc:
        snapshot_error = str(exc)
    errors_output = _try_browser_command(
        ["errors"],
        session_name=session_name,
        timeout_seconds=3.0,
    )
    console_output = _try_browser_command(
        ["console"],
        session_name=session_name,
        timeout_seconds=3.0,
    )
    error_count = len([line for line in errors_output.splitlines() if line.strip()])
    console_count = len([line for line in console_output.splitlines() if line.strip()])
    content_source = "agent-browser"
    content_visible = has_content == "HAS_CONTENT"
    if has_content not in {"HAS_CONTENT", "BLANK"}:
        if screenshot_signal == "rendered":
            content_visible = True
            content_source = "screenshot"
        elif http_content_visible:
            content_visible = True
            content_source = "http"
        else:
            content_visible = False
            content_source = "unknown"
    elif has_content == "BLANK" and screenshot_signal == "rendered" and http_content_visible:
        content_visible = True
        content_source = "screenshot_override"
    overlay_ok = overlay_status == "OK"
    if not overlay_status and error_count == 0 and screenshot_signal == "rendered":
        overlay_ok = True
    ok = content_visible and overlay_ok and error_count == 0
    content_summary = "content visible" if content_visible else "page looks blank"
    if content_source == "screenshot":
        content_summary = "content visible (screenshot-backed fallback)"
    elif content_source == "http":
        content_summary = "content visible (HTTP fallback)"
    elif content_source == "screenshot_override":
        content_summary = "content visible (screenshot overrode a blank probe)"
    overlay_summary = "no overlay" if overlay_ok else "error overlay present"
    if not overlay_status and overlay_ok:
        overlay_summary = "no overlay (probe unavailable)"
    summary_parts = [
        f"url {page_url or browser_url}",
        content_summary,
        overlay_summary,
        f"{error_count} page error(s)",
        f"{console_count} console line(s)",
    ]
    if screenshot_signal == "rendered" and screenshot_bytes is not None:
        summary_parts.append(f"screenshot {screenshot_bytes} bytes")
    elif screenshot_signal == "likely_blank" and screenshot_bytes is not None:
        summary_parts.append(f"screenshot looks blank at {screenshot_bytes} bytes")
    return {
        "ok": ok,
        "status": "ready" if ok else "warn",
        "summary": ", ".join(summary_parts) + ".",
        "url": page_url or browser_url,
        "title": title or None,
        "has_content": content_visible,
        "content_source": content_source,
        "http_content_visible": http_content_visible,
        "overlay_status": overlay_status or "unknown",
        "error_count": error_count,
        "console_count": console_count,
        "screenshot_path": screenshot_path,
        "screenshot_signal": screenshot_signal,
        "screenshot_bytes": screenshot_bytes,
        "screenshot_error": screenshot_error,
        "snapshot_summary": snapshot_summary,
        "snapshot_error": snapshot_error,
        "errors_excerpt": _first_text_line(errors_output, limit=280) or None,
        "console_excerpt": _first_text_line(console_output, limit=280) or None,
    }


def _watch_browser_verify_guarded(
    *,
    browser_url: str,
    session_name: str,
    timeout_seconds: float = 45.0,
) -> dict[str, Any]:
    if os.name != "nt":
        return _watch_browser_verify(browser_url=browser_url, session_name=session_name)
    worker_code = "\n".join(
        [
            "import json",
            "from openzues.cli import _watch_browser_verify",
            (
                "payload = _watch_browser_verify("
                f"browser_url={json.dumps(browser_url)}, "
                f"session_name={json.dumps(session_name)})"
            ),
            "print(json.dumps(payload, separators=(',', ':')))",
        ]
    )
    try:
        completed = subprocess.run(
            [sys.executable, "-c", worker_code],
            capture_output=True,
            text=True,
            timeout=timeout_seconds,
            check=False,
        )
    except subprocess.TimeoutExpired as exc:
        raise RuntimeError(
            f"browser verification timed out after {timeout_seconds:.0f}s."
        ) from exc
    stdout = (completed.stdout or "").strip()
    stderr = (completed.stderr or "").strip()
    if completed.returncode != 0:
        detail = _first_text_line(stderr or stdout, limit=280) or "browser verification failed."
        raise RuntimeError(detail)
    lines = [line.strip() for line in stdout.splitlines() if line.strip()]
    if not lines:
        raise RuntimeError("browser verification returned no payload.")
    try:
        payload = json.loads(lines[-1])
    except json.JSONDecodeError as exc:
        detail = _first_text_line(stdout, limit=280) or "browser verification payload invalid."
        raise RuntimeError(detail) from exc
    if not isinstance(payload, dict):
        raise RuntimeError("browser verification returned an unexpected payload.")
    return payload


def _watch_target_payload(
    dashboard: dict[str, Any],
    handoff: dict[str, Any],
    *,
    mission_id: int | None,
    task_name: str | None,
) -> dict[str, Any]:
    missions = [item for item in dashboard.get("missions", []) if isinstance(item, dict)]
    brief = dashboard.get("brief")
    task_blueprint = (
        handoff.get("task_blueprint") if isinstance(handoff.get("task_blueprint"), dict) else None
    )
    task_blueprint_id = (
        int(task_blueprint["id"])
        if isinstance(task_blueprint, dict) and task_blueprint.get("id") is not None
        else None
    )
    resolved_task_name = str(task_name or "").strip() or (
        str(task_blueprint.get("label") or "").strip() if isinstance(task_blueprint, dict) else ""
    )
    if not resolved_task_name:
        resolved_task_name = _DEFAULT_WATCH_TASK_NAME

    def _mission_sort_key(mission: dict[str, Any]) -> tuple[int, float, int]:
        status_priority = {
            "active": 0,
            "blocked": 1,
            "paused": 2,
            "failed": 3,
            "completed": 4,
        }.get(str(mission.get("status") or "").strip().lower(), 5)
        updated_text = str(mission.get("updated_at") or mission.get("created_at") or "").strip()
        updated_at = 0.0
        if updated_text:
            try:
                updated_at = datetime.fromisoformat(updated_text.replace("Z", "+00:00")).timestamp()
            except ValueError:
                updated_at = 0.0
        return (
            status_priority,
            -updated_at,
            -int(mission.get("id") or 0),
        )

    watched_mission: dict[str, Any] | None = None
    if mission_id is not None:
        watched_mission = next(
            (mission for mission in missions if int(mission.get("id") or 0) == mission_id),
            None,
        )
    if watched_mission is None and task_blueprint_id is not None:
        candidates = [
            mission
            for mission in missions
            if int(mission.get("task_blueprint_id") or 0) == task_blueprint_id
        ]
        if candidates:
            watched_mission = sorted(candidates, key=_mission_sort_key)[0]
    if watched_mission is None and resolved_task_name:
        candidates = [
            mission
            for mission in missions
            if str(mission.get("name") or "").strip() == resolved_task_name
        ]
        if candidates:
            watched_mission = sorted(candidates, key=_mission_sort_key)[0]
    if (
        watched_mission is None
        and isinstance(brief, dict)
        and brief.get("focus_mission_id") is not None
    ):
        focus_mission_id = int(brief["focus_mission_id"])
        watched_mission = next(
            (mission for mission in missions if int(mission.get("id") or 0) == focus_mission_id),
            None,
        )
    return {
        "task_name": resolved_task_name,
        "task_blueprint_id": task_blueprint_id,
        "mission": watched_mission,
    }


def _watch_is_runnable(status: object) -> bool:
    return str(status or "").strip().lower() in {"paused", "failed"}


def _watch_is_terminal(status: object) -> bool:
    return str(status or "").strip().lower() in {"completed", "failed"}


def _watch_auto_action_summary(action: dict[str, Any] | None) -> str:
    if not isinstance(action, dict):
        return ""
    return _first_text_line(action.get("summary"))


def _watch_observer_posture(dashboard: dict[str, Any]) -> dict[str, Any] | None:
    control_chat = dashboard.get("control_chat")
    attention_queue = dashboard.get("attention_queue")
    candidate_sections = [
        section
        for section in (control_chat, attention_queue)
        if isinstance(section, dict)
    ]
    observer_section = next(
        (
            section
            for section in candidate_sections
            if str(section.get("headline") or "").strip() == "Observer mode is active"
        ),
        None,
    )
    if observer_section is None:
        return None

    summary = str(observer_section.get("summary") or "").strip()
    if not summary:
        summary = next(
            (
                str(section.get("summary") or "").strip()
                for section in candidate_sections
                if str(section.get("summary") or "").strip()
            ),
            "",
        )
    leader_pid: int | None = None
    if summary:
        match = _WATCH_LEADER_PID_RE.search(summary)
        if match is not None:
            leader_pid = int(match.group("pid"))
    return {
        "active": True,
        "summary": summary or "Observer mode is active in this window.",
        "leader_pid": leader_pid,
    }


def _maybe_launch_watch_target(
    base_url: str,
    *,
    dashboard: dict[str, Any],
    handoff: dict[str, Any],
    mission_id: int | None,
    task_name: str | None,
) -> dict[str, Any] | None:
    target = _watch_target_payload(
        dashboard,
        handoff,
        mission_id=mission_id,
        task_name=task_name,
    )
    watched_mission = target.get("mission")
    if isinstance(watched_mission, dict) and watched_mission.get("id") is not None:
        watched_mission_id = int(watched_mission["id"])
        watched_mission_name = str(
            watched_mission.get("name") or f"mission {watched_mission_id}"
        ).strip()
        if _watch_is_runnable(watched_mission.get("status")):
            _watch_api_json(
                base_url,
                f"/api/missions/{watched_mission_id}/start",
                method="POST",
                timeout_seconds=5.0,
                allow_timeout=True,
            )
            return {
                "action": "resume_mission",
                "mission_id": watched_mission_id,
                "summary": (
                    f"Sent a resume request for mission #{watched_mission_id} "
                    f"({watched_mission_name}) and switched to live polling."
                ),
            }
        return {
            "action": "observe_existing_mission",
            "mission_id": watched_mission_id,
            "summary": f"Watching mission #{watched_mission_id} ({watched_mission_name}).",
        }

    recommended_action = str(handoff.get("recommended_action") or "").strip()
    instance = handoff.get("instance")
    if (
        recommended_action == "connect_lane"
        and isinstance(instance, dict)
        and instance.get("id") is not None
    ):
        instance_id = int(instance["id"])
        _watch_api_json(base_url, f"/api/instances/{instance_id}/connect", method="POST")
        return {
            "action": "connect_lane",
            "instance_id": instance_id,
            "summary": f"Reconnected lane #{instance_id} so the saved launch handoff can run.",
        }

    mission_draft = handoff.get("mission_draft")
    if isinstance(mission_draft, dict):
        created = _watch_api_json(base_url, "/api/missions", method="POST", payload=mission_draft)
        if isinstance(created, dict):
            created_id = int(created.get("id") or 0)
            created_name = str(created.get("name") or f"mission {created_id}").strip()
            if created_id and _watch_is_runnable(created.get("status")):
                _watch_api_json(
                    base_url,
                    f"/api/missions/{created_id}/start",
                    method="POST",
                    timeout_seconds=5.0,
                    allow_timeout=True,
                )
                return {
                    "action": "resume_mission",
                    "mission_id": created_id,
                    "summary": (
                        f"Sent a resume request for saved mission #{created_id} "
                        f"({created_name}) from the launch handoff and switched to live polling."
                    ),
                }
            return {
                "action": "create_mission",
                "mission_id": created_id if created_id else None,
                "summary": (
                    f"Launched mission #{created_id} ({created_name}) from the saved handoff."
                ),
            }

    next_entrypoint = _first_text_line(
        handoff.get("next_entrypoint")
        or handoff.get("summary")
        or "No launchable mission is saved yet."
    )
    return {
        "action": "observe_handoff",
        "summary": next_entrypoint,
    }


def _build_watch_payload(
    *,
    base_url: str,
    dashboard: dict[str, Any],
    handoff: dict[str, Any],
    mission_id: int | None,
    task_name: str | None,
    auto_action: dict[str, Any] | None,
    browser_verification: dict[str, Any] | None,
) -> dict[str, Any]:
    target = _watch_target_payload(
        dashboard,
        handoff,
        mission_id=mission_id,
        task_name=task_name,
    )
    missions = [item for item in dashboard.get("missions", []) if isinstance(item, dict)]
    instances = [item for item in dashboard.get("instances", []) if isinstance(item, dict)]
    observer_posture = _watch_observer_posture(dashboard)
    return {
        "headline": str(dashboard.get("brief", {}).get("headline") or "").strip(),
        "summary": str(dashboard.get("brief", {}).get("summary") or "").strip(),
        "checked_at": datetime.now(UTC).isoformat().replace("+00:00", "Z"),
        "base_url": base_url,
        "watch_target": {
            "mission_id": mission_id,
            "task_name": target["task_name"],
            "task_blueprint_id": target["task_blueprint_id"],
        },
        "auto_action": auto_action,
        "browser_verification": browser_verification,
        "observer_posture": observer_posture,
        "setup_launch_handoff": handoff,
        "mission_summary": {
            "active_count": sum(str(item.get("status") or "") == "active" for item in missions),
            "blocked_count": sum(str(item.get("status") or "") == "blocked" for item in missions),
            "paused_count": sum(str(item.get("status") or "") == "paused" for item in missions),
            "failed_count": sum(str(item.get("status") or "") == "failed" for item in missions),
        },
        "instance_summary": {
            "connected_count": sum(bool(item.get("connected")) for item in instances),
            "total_count": len(instances),
        },
        "gateway_capability": dashboard.get("gateway_capability"),
        "watched_mission": target["mission"],
    }


def _watch_lines(payload: dict[str, object]) -> list[str]:
    lines: list[str] = []
    checked_at = str(payload.get("checked_at") or "").strip()
    base_url = str(payload.get("base_url") or "").strip()
    prefix = f"[{checked_at}] " if checked_at else ""
    lines.append(f"{prefix}OpenZues watch @ {base_url or 'live server'}")
    observer_posture = payload.get("observer_posture")
    observer_active = isinstance(observer_posture, dict) and bool(observer_posture.get("active"))

    headline = str(payload.get("headline") or "").strip()
    if headline:
        lines.append("brief: " + headline)
    summary = str(payload.get("summary") or "").strip()
    if summary:
        lines.append("summary: " + summary)
    if isinstance(observer_posture, dict) and observer_posture.get("active"):
        leader_pid = observer_posture.get("leader_pid")
        mode_line = "mode: observer"
        if isinstance(leader_pid, int):
            mode_line += f" / leader PID {leader_pid}"
        lines.append(mode_line)
        observer_summary = _first_text_line(observer_posture.get("summary"), limit=320)
        if observer_summary:
            lines.append("mode summary: " + observer_summary)
        lines.append(
            "mode note: Mission telemetry may be leader-owned while lane, gateway, and "
            "handoff posture below come from this observer window."
        )

    watch_target = payload.get("watch_target")
    if isinstance(watch_target, dict):
        task_name = str(watch_target.get("task_name") or "").strip()
        task_blueprint_id = watch_target.get("task_blueprint_id")
        target_parts: list[str] = []
        if task_name:
            target_parts.append(task_name)
        if task_blueprint_id is not None:
            target_parts.append(f"task #{task_blueprint_id}")
        mission_id = watch_target.get("mission_id")
        if mission_id is not None:
            target_parts.append(f"mission #{mission_id}")
        if target_parts:
            lines.append("target: " + " | ".join(target_parts))

    auto_action = payload.get("auto_action")
    if isinstance(auto_action, dict):
        auto_summary = _watch_auto_action_summary(auto_action)
        if auto_summary:
            lines.append("auto: " + auto_summary)

    browser_verification = payload.get("browser_verification")
    if isinstance(browser_verification, dict):
        browser_status = str(browser_verification.get("status") or "").strip()
        browser_summary = str(browser_verification.get("summary") or "").strip()
        if browser_status or browser_summary:
            lines.append(
                "browser: "
                + " / ".join(part for part in (browser_status, browser_summary) if part)
            )
        title = str(browser_verification.get("title") or "").strip()
        if title:
            lines.append("browser title: " + title)
        snapshot_summary = _first_text_line(browser_verification.get("snapshot_summary"), limit=320)
        if snapshot_summary:
            lines.append("browser snapshot: " + snapshot_summary)
        artifact_path = str(browser_verification.get("artifact_path") or "").strip()
        if artifact_path:
            lines.append("browser artifact: " + artifact_path)
        screenshot_path = str(browser_verification.get("screenshot_path") or "").strip()
        if screenshot_path:
            lines.append("browser screenshot: " + screenshot_path)
        screenshot_error = _first_text_line(browser_verification.get("screenshot_error"))
        if screenshot_error:
            lines.append("browser screenshot warning: " + screenshot_error)
        snapshot_error = _first_text_line(browser_verification.get("snapshot_error"))
        if snapshot_error:
            lines.append("browser snapshot warning: " + snapshot_error)
        errors_excerpt = _first_text_line(browser_verification.get("errors_excerpt"))
        if errors_excerpt:
            lines.append("browser errors: " + errors_excerpt)
        console_excerpt = _first_text_line(browser_verification.get("console_excerpt"))
        if console_excerpt:
            lines.append("browser console: " + console_excerpt)

    handoff = payload.get("setup_launch_handoff")
    if isinstance(handoff, dict):
        handoff_status = str(handoff.get("status") or "").strip()
        handoff_headline = str(handoff.get("headline") or "").strip()
        handoff_summary = _first_text_line(handoff.get("summary"))
        handoff_label = "observer handoff" if observer_active else "handoff"
        handoff_summary_label = (
            "observer handoff summary" if observer_active else "handoff summary"
        )
        next_label = "observer next" if observer_active else "next"
        if handoff_status or handoff_headline:
            lines.append(
                f"{handoff_label}: "
                + " / ".join(part for part in (handoff_status, handoff_headline) if part)
            )
        if handoff_summary:
            lines.append(f"{handoff_summary_label}: " + handoff_summary)
        next_entrypoint = _first_text_line(handoff.get("next_entrypoint"))
        if next_entrypoint:
            lines.append(f"{next_label}: " + next_entrypoint)

    instance_summary = payload.get("instance_summary")
    if isinstance(instance_summary, dict):
        lanes_label = "observer lanes" if observer_active else "lanes"
        lines.append(
            f"{lanes_label}: "
            f"{instance_summary.get('connected_count', 0)} connected / "
            f"{instance_summary.get('total_count', 0)} total"
        )

    mission_summary = payload.get("mission_summary")
    if isinstance(mission_summary, dict):
        lines.append(
            "missions: "
            f"{mission_summary.get('active_count', 0)} active, "
            f"{mission_summary.get('blocked_count', 0)} blocked, "
            f"{mission_summary.get('paused_count', 0)} paused, "
            f"{mission_summary.get('failed_count', 0)} failed"
        )

    gateway_capability = payload.get("gateway_capability")
    if isinstance(gateway_capability, dict):
        gateway_level = str(gateway_capability.get("level") or "").strip()
        gateway_headline = str(gateway_capability.get("headline") or "").strip()
        gateway_label = "observer gateway" if observer_active else "gateway"
        gateway_summary_label = (
            "observer gateway summary" if observer_active else "gateway summary"
        )
        if gateway_level or gateway_headline:
            lines.append(
                f"{gateway_label}: "
                + " / ".join(part for part in (gateway_level, gateway_headline) if part)
            )
        gateway_summary = _first_text_line(gateway_capability.get("summary"))
        if gateway_summary:
            lines.append(f"{gateway_summary_label}: " + gateway_summary)
        launch_policy = gateway_capability.get("launch_policy")
        if isinstance(launch_policy, dict):
            launch_route = launch_policy.get("launch_route")
            if isinstance(launch_route, dict):
                conversation_target = launch_route.get("conversation_target")
                if isinstance(conversation_target, dict):
                    target_summary = _first_text_line(conversation_target.get("summary"))
                    if target_summary:
                        target_label = (
                            "observer conversation target"
                            if observer_active
                            else "conversation target"
                        )
                        lines.append(f"{target_label}: " + target_summary)
                conversation_reuse = launch_route.get("conversation_reuse")
                if isinstance(conversation_reuse, dict):
                    reuse_summary = _first_text_line(conversation_reuse.get("summary"))
                    if reuse_summary:
                        reuse_label = (
                            "observer conversation reuse"
                            if observer_active
                            else "conversation reuse"
                        )
                        lines.append(f"{reuse_label}: " + reuse_summary)

    watched_mission = payload.get("watched_mission")
    if not isinstance(watched_mission, dict):
        lines.append("mission: No matching live mission yet.")
        return lines

    watched_mission_id = watched_mission.get("id")
    watched_name = str(watched_mission.get("name") or "Mission").strip()
    watched_status = str(watched_mission.get("status") or "").strip()
    watched_phase = str(watched_mission.get("phase") or "").strip()
    lines.append(
        "mission: "
        + f"#{watched_mission_id} {watched_name}"
        + (
            " [" + " / ".join(part for part in (watched_status, watched_phase) if part) + "]"
            if watched_status or watched_phase
            else ""
        )
    )

    live_telemetry = watched_mission.get("live_telemetry")
    if isinstance(live_telemetry, dict):
        live_summary = _first_text_line(live_telemetry.get("summary"))
        if live_summary:
            lines.append("live: " + live_summary)

    delegation_brief = watched_mission.get("delegation_brief")
    if isinstance(delegation_brief, dict):
        delegation_summary = _first_text_line(delegation_brief.get("summary"))
        if delegation_summary:
            lines.append("delegation: " + delegation_summary)

    toolsets = watched_mission.get("toolsets")
    if isinstance(toolsets, list) and toolsets:
        lines.append("toolsets: " + ", ".join(str(item) for item in toolsets[:8]))
    tool_evidence = watched_mission.get("tool_evidence")
    if isinstance(tool_evidence, dict):
        tool_evidence_summary = _first_text_line(tool_evidence.get("summary"))
        if tool_evidence_summary:
            lines.append("tool proof: " + tool_evidence_summary)

    current_command = _first_text_line(watched_mission.get("current_command"))
    if current_command:
        lines.append("command: " + current_command)

    commentary = _first_text_line(watched_mission.get("last_commentary"))
    if commentary:
        lines.append("commentary: " + commentary)

    checkpoint = _first_text_line(watched_mission.get("last_checkpoint"))
    if checkpoint:
        lines.append("checkpoint: " + checkpoint)

    last_error = _first_text_line(watched_mission.get("last_error"))
    if last_error:
        lines.append("error: " + last_error)
    return lines


def _watch_output(payload: dict[str, object], *, json_output: bool) -> str:
    if json_output:
        return json.dumps(payload, indent=2)
    return "\n".join(_watch_lines(payload))


def _emit_watch(payload: dict[str, object], *, json_output: bool) -> None:
    typer.echo(_watch_output(payload, json_output=json_output))


def _watch_log_path(path: Path, index: int) -> Path:
    return path.with_name(f"{path.name}.{index}")


def _rotate_watch_log(path: Path, *, max_bytes: int, backups: int) -> None:
    if max_bytes <= 0 or backups <= 0 or not path.exists():
        return
    try:
        size = path.stat().st_size
    except OSError:
        return
    if size < max_bytes:
        return
    oldest = _watch_log_path(path, backups)
    if oldest.exists():
        oldest.unlink()
    for index in range(backups - 1, 0, -1):
        source = _watch_log_path(path, index)
        destination = _watch_log_path(path, index + 1)
        if source.exists():
            source.replace(destination)
    path.replace(_watch_log_path(path, 1))


def _append_watch_log(
    path: Path,
    *,
    text: str,
    max_bytes: int,
    backups: int,
) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    _rotate_watch_log(path, max_bytes=max_bytes, backups=backups)
    if path.exists():
        try:
            existing_bytes = path.read_bytes()
        except OSError:
            existing_bytes = b""
        if existing_bytes and not existing_bytes.startswith(codecs.BOM_UTF8):
            path.write_bytes(codecs.BOM_UTF8 + existing_bytes)
    needs_bom = not path.exists()
    if not needs_bom:
        try:
            needs_bom = path.stat().st_size == 0
        except OSError:
            needs_bom = True
    with path.open("ab") as handle:
        if needs_bom:
            handle.write(codecs.BOM_UTF8)
        handle.write(text.encode("utf-8"))
        handle.write(b"\n\n")


def _copy_watch_screenshot(
    browser_verification: dict[str, Any] | None,
    *,
    artifact_path: Path,
) -> dict[str, Any] | None:
    if not isinstance(browser_verification, dict):
        return browser_verification
    screenshot_text = str(browser_verification.get("screenshot_path") or "").strip()
    if not screenshot_text:
        return browser_verification
    source = Path(screenshot_text)
    if not source.exists():
        return browser_verification
    artifact_path.parent.mkdir(parents=True, exist_ok=True)
    shutil.copyfile(source, artifact_path)
    updated = dict(browser_verification)
    updated["artifact_path"] = str(artifact_path)
    return updated


def _emit_executor_arm(payload: dict[str, object], *, json_output: bool) -> None:
    if json_output:
        _emit_payload(payload, json_output=True)
        return

    headline = str(payload.get("headline") or "").strip()
    if headline:
        typer.echo(headline)
    summary = str(payload.get("summary") or "").strip()
    if summary:
        typer.echo(summary)
    executor_label = str(payload.get("executor_label") or "").strip()
    if executor_label:
        typer.echo(f"executor: {executor_label}")
    cwd = str(payload.get("cwd") or "").strip()
    if cwd:
        typer.echo(f"cwd: {cwd}")
    derived_from = str(payload.get("derived_from") or "").strip()
    if derived_from:
        typer.echo(f"derived from: {derived_from}")
    image = str(payload.get("image") or "").strip()
    if image:
        typer.echo(f"image: {image}")
    if payload.get("mount_workspace") is not None:
        typer.echo(f"mount workspace: {bool(payload.get('mount_workspace'))}")
    typer.echo(f"created: {bool(payload.get('created'))}")
    typer.echo(f"connected: {bool(payload.get('connected'))}")
    instance = payload.get("instance")
    if isinstance(instance, dict):
        lane_name = str(instance.get("name") or "").strip()
        if lane_name:
            typer.echo(f"lane: {lane_name}")
        lane_id = instance.get("id")
        if lane_id is not None:
            typer.echo(f"instance: {lane_id}")


def _emit_executor_preflight(payload: dict[str, object], *, json_output: bool) -> None:
    if json_output:
        _emit_payload(payload, json_output=True)
        return

    headline = str(payload.get("headline") or "").strip()
    if headline:
        typer.echo(headline)
    summary = str(payload.get("summary") or "").strip()
    if summary:
        typer.echo(summary)
    typer.echo(f"ok: {bool(payload.get('ok'))}")
    status = str(payload.get("status") or "").strip()
    if status:
        typer.echo(f"status: {status}")
    cwd = str(payload.get("cwd") or "").strip()
    if cwd:
        typer.echo(f"cwd: {cwd}")
    image = str(payload.get("image") or "").strip()
    if image:
        typer.echo(f"image: {image}")
    command_path = str(payload.get("command_path") or "").strip()
    if command_path:
        typer.echo(f"docker path: {command_path}")
    docker_version = str(payload.get("docker_version") or "").strip()
    if docker_version:
        typer.echo(f"docker version: {docker_version}")
    daemon_version = str(payload.get("daemon_version") or "").strip()
    if daemon_version:
        typer.echo(f"daemon version: {daemon_version}")
    if payload.get("image_present") is not None:
        typer.echo(f"image present: {bool(payload.get('image_present'))}")


async def _run_control_chat_prompt(
    services: CliServices,
    *,
    prompt: str,
    plan_only: bool,
) -> dict[str, object]:
    dashboard = await _build_operator_dashboard(services)
    typed_dashboard = cast(DashboardView, dashboard)
    if plan_only:
        plan = plan_control_chat(prompt, typed_dashboard)
        return {
            "mode": "plan",
            "executed": False,
            "action_kind": plan.action_kind,
            "reply": plan.reply,
            "mission_id": plan.mission_id,
            "opportunity_id": plan.opportunity_id,
            "target_label": plan.target_label,
            "mission_payload": (
                plan.mission_payload.model_dump(mode="json")
                if plan.mission_payload is not None
                else None
            ),
        }
    result = await services.control_chat.submit(prompt, typed_dashboard)
    return {
        "mode": "executed",
        "executed": result.executed,
        "action_kind": result.action_kind,
        "reply": result.assistant.content,
        "mission_id": result.assistant.mission_id,
        "opportunity_id": result.assistant.opportunity_id,
        "target_label": result.assistant.target_label,
        "assistant_message_id": result.assistant.id,
        "user_message_id": result.user.id,
    }


def _control_chat_plan_payload(plan) -> dict[str, object]:
    return {
        "action_kind": plan.action_kind,
        "reply": plan.reply,
        "mission_id": plan.mission_id,
        "opportunity_id": plan.opportunity_id,
        "target_label": plan.target_label,
        "mission_payload": (
            plan.mission_payload.model_dump(mode="json")
            if plan.mission_payload is not None
            else None
        ),
    }


def _attention_queue_plan_payload(plan) -> dict[str, object] | None:
    if plan is None:
        return None
    return {
        "action_kind": plan.action_kind,
        "status": plan.status,
        "reply": plan.reply,
        "signal_id": plan.signal_id,
        "mission_id": plan.mission_id,
        "opportunity_id": plan.opportunity_id,
        "target_label": plan.target_label,
        "mission_payload": (
            plan.mission_payload.model_dump(mode="json")
            if plan.mission_payload is not None
            else None
        ),
    }


def _find_launchpad_opportunity(
    dashboard: DashboardView | SimpleNamespace,
    opportunity_id: str,
):
    wanted = opportunity_id.strip()
    if not wanted:
        return None
    return next(
        (
            opportunity
            for opportunity in dashboard.launchpad.opportunities
            if opportunity.id == wanted
        ),
        None,
    )


def _available_launchpad_ids(dashboard: DashboardView | SimpleNamespace) -> list[str]:
    return [opportunity.id for opportunity in dashboard.launchpad.opportunities]


def _attention_queue_idle_reply(*, signal_id: str | None = None) -> str:
    wanted = str(signal_id or "").strip()
    if wanted:
        return (
            f"The selected attention-queue signal `{wanted}` does not have a bounded move "
            "right now."
        )
    return _ATTENTION_QUEUE_IDLE_REPLY


def _build_status_payload(
    dashboard: DashboardView | SimpleNamespace,
) -> dict[str, object]:
    active_count = sum(1 for mission in dashboard.missions if mission.status == "active")
    blocked_count = len(operator_blocked_missions(dashboard.missions))
    paused_count = sum(1 for mission in dashboard.missions if mission.status == "paused")
    failed_count = sum(1 for mission in dashboard.missions if mission.status == "failed")
    connected_count = sum(1 for instance in dashboard.instances if instance.connected)
    typed_dashboard = cast(DashboardView, dashboard)
    browser_posture = (
        typed_dashboard.browser_posture
        if isinstance(typed_dashboard.browser_posture, BrowserPostureView)
        else None
    )
    status_plan = plan_control_chat("status", typed_dashboard)
    queue_plan = plan_attention_queue(typed_dashboard)
    return {
        "headline": dashboard.brief.headline,
        "summary": dashboard.brief.summary,
        "brief": dashboard.brief.model_dump(mode="json"),
        "status_plan": _control_chat_plan_payload(status_plan),
        "mission_summary": {
            "active_count": active_count,
            "blocked_count": blocked_count,
            "paused_count": paused_count,
            "failed_count": failed_count,
        },
        "instance_summary": {
            "connected_count": connected_count,
            "total_count": len(dashboard.instances),
        },
        "browser_posture": (
            browser_posture.model_dump(mode="json") if browser_posture is not None else None
        ),
        "gateway_capability": dashboard.gateway_capability.model_dump(mode="json"),
        "radar": dashboard.radar.model_dump(mode="json"),
        "launchpad": dashboard.launchpad.model_dump(mode="json"),
        "queue_plan": _attention_queue_plan_payload(queue_plan),
    }


def _build_channel_capabilities_report(
    *,
    channel_id: str,
    account_id: str,
    account_summary: dict[str, object] | None,
    timeout_ms: int,
) -> dict[str, object]:
    route_count = account_summary.get("routeCount") if account_summary is not None else None
    enabled_route_count = (
        account_summary.get("enabledRouteCount") if account_summary is not None else None
    )
    configured = (
        isinstance(route_count, int)
        and not isinstance(route_count, bool)
        and route_count > 0
    )
    enabled = (
        isinstance(enabled_route_count, int)
        and not isinstance(enabled_route_count, bool)
        and enabled_route_count > 0
    )
    support = dict(_CHANNEL_CAPABILITY_SUPPORT.get(channel_id, {"chatTypes": ["direct"]}))
    actions = ["send", "broadcast"]
    if support.get("polls") is True:
        actions.append("poll")
    probe = account_summary.get("probe") if account_summary is not None else None
    if not isinstance(probe, dict):
        probe = {
            "status": "unavailable",
            "reason": "native_probe_runtime_unavailable",
            "summary": "Native channel capability probes are not available yet.",
            "timeoutMs": timeout_ms,
        }
    return {
        "channel": channel_id,
        "accountId": account_id,
        "configured": configured,
        "enabled": enabled,
        "support": support,
        "actions": actions,
        "probe": probe,
    }


def _account_summaries_by_id(value: object) -> dict[str, dict[str, object]]:
    if not isinstance(value, list):
        return {}
    result: dict[str, dict[str, object]] = {}
    for item in value:
        if not isinstance(item, dict):
            continue
        account_id = _optional_cli_string(item.get("accountId"))
        if account_id is None:
            continue
        result[account_id] = dict(item)
    return result


async def _build_channel_capabilities_payload(
    services: CliServices,
    *,
    channel: str | None,
    account: str | None,
    target: str | None,
    timeout_ms: int,
) -> dict[str, object]:
    normalized_channel = (_optional_cli_string(channel) or "all").lower()
    normalized_account = _optional_cli_string(account)
    normalized_target = _optional_cli_string(target)
    if normalized_account is not None and normalized_channel == "all":
        raise ValueError("--account requires a specific --channel.")
    if normalized_target is not None and normalized_channel == "all":
        raise ValueError("--target requires a specific --channel.")

    snapshot = await services.gateway_channels.build_snapshot(
        probe=True,
        timeout_ms=timeout_ms,
    )
    channel_order = [
        str(item).strip().lower()
        for item in snapshot.get("channelOrder", [])
        if str(item).strip()
    ]
    selected_channels = (
        channel_order if normalized_channel == "all" else [normalized_channel]
    )
    if normalized_channel != "all" and normalized_channel not in channel_order:
        raise ValueError(f'Unknown channel "{normalized_channel}".')

    channel_accounts = snapshot.get("channelAccounts")
    default_accounts = snapshot.get("channelDefaultAccountId")
    if not isinstance(channel_accounts, dict):
        channel_accounts = {}
    if not isinstance(default_accounts, dict):
        default_accounts = {}

    reports: list[dict[str, object]] = []
    for channel_id in selected_channels:
        accounts_by_id = _account_summaries_by_id(channel_accounts.get(channel_id))
        account_ids = (
            [normalized_account]
            if normalized_account is not None
            else sorted(accounts_by_id)
            or [
                _optional_cli_string(default_accounts.get(channel_id))
                or "default"
            ]
        )
        for account_id in account_ids:
            reports.append(
                _build_channel_capabilities_report(
                    channel_id=channel_id,
                    account_id=account_id,
                    account_summary=accounts_by_id.get(account_id),
                    timeout_ms=timeout_ms,
                )
            )

    return {
        "channels": reports,
        "timeoutMs": timeout_ms,
        "target": normalized_target,
    }


def _normalize_channel_resolve_kind(kind: str | None) -> str:
    normalized = (_optional_cli_string(kind) or "auto").lower()
    valid_kinds = {"auto", "user", "group", "channel"}
    if normalized not in valid_kinds:
        raise ValueError("--kind must be one of: auto, user, group, channel.")
    return normalized


def _channel_target_field(target: dict[str, object], *names: str) -> str | None:
    for name in names:
        text = _optional_cli_string(target.get(name))
        if text is not None:
            return text
    return None


def _channel_resolve_kind_matches(target_kind: str | None, requested_kind: str) -> bool:
    if requested_kind == "auto":
        return True
    normalized_target_kind = (target_kind or "").strip().lower()
    if requested_kind == "group":
        return normalized_target_kind in {"group", "channel"}
    return normalized_target_kind == requested_kind


def _detect_channel_resolve_auto_kind(entry: str, channel: str | None) -> str:
    trimmed = entry.strip()
    if not trimmed:
        return "group"
    if trimmed.startswith("@"):
        return "user"
    if re.match(r"^<@!?", trimmed):
        return "user"
    if re.match(r"^[^\s@]+@[^\s@]+\.[^\s@]+$", trimmed):
        return "user"
    if re.match(r"^user:", trimmed, re.IGNORECASE):
        return "user"

    normalized_channel = (_optional_cli_string(channel) or "").lower()
    lowered = trimmed.lower()
    if normalized_channel and lowered.startswith(f"{normalized_channel}:"):
        remainder = lowered[len(normalized_channel) + 1 :]
        if remainder.startswith(
            (
                "group:",
                "channel:",
                "room:",
                "conversation:",
                "spaces/",
                "channels/",
            )
        ):
            return "group"
        return "user"
    return "group"


def _channel_resolve_route_targets(
    snapshot: dict[str, object],
    *,
    channel: str | None,
    account: str | None,
    kind: str,
) -> list[dict[str, str]]:
    normalized_channel = _optional_cli_string(channel)
    normalized_account = _optional_cli_string(account)
    routes = snapshot.get("routes")
    if not isinstance(routes, list):
        return []

    matches: list[dict[str, str]] = []
    for route in routes:
        if not isinstance(route, dict):
            continue
        target = route.get("conversation_target")
        if not isinstance(target, dict):
            target = route.get("conversationTarget")
        if not isinstance(target, dict):
            continue
        typed_target = cast(dict[str, object], target)
        target_channel = _channel_target_field(typed_target, "channel")
        if normalized_channel is not None and (
            target_channel is None or target_channel.lower() != normalized_channel.lower()
        ):
            continue
        target_account = _channel_target_field(typed_target, "account_id", "accountId")
        if normalized_account is not None and (
            target_account is None or target_account != normalized_account
        ):
            continue
        target_kind = _channel_target_field(typed_target, "peer_kind", "peerKind")
        if not _channel_resolve_kind_matches(target_kind, kind):
            continue
        target_id = _channel_target_field(typed_target, "peer_id", "peerId")
        if target_id is None:
            continue
        summary = _channel_target_field(typed_target, "summary")
        route_name = _optional_cli_string(route.get("name"))
        matches.append(
            {
                "id": target_id,
                "name": route_name or summary or target_id,
                "summary": summary or "",
                "channel": target_channel or "",
                "account": target_account or "",
                "kind": target_kind or "",
            }
        )
    return matches


def _channel_resolve_match_entry(
    entry: str,
    targets: list[dict[str, str]],
) -> dict[str, str] | None:
    normalized_entry = entry.strip().lower()
    for target in targets:
        candidates = {
            target.get("id", ""),
            target.get("name", ""),
            target.get("summary", ""),
        }
        if any(candidate.strip().lower() == normalized_entry for candidate in candidates):
            return target
    return None


def _normalize_channel_resolve_result(
    entry: str,
    result: dict[str, object],
) -> dict[str, object]:
    payload: dict[str, object] = {
        "input": _optional_cli_string(result.get("input")) or entry,
        "resolved": bool(result.get("resolved")),
    }
    for key in ("id", "name", "error", "note"):
        text = _optional_cli_string(result.get(key))
        if text is not None:
            payload[key] = text
    return payload


async def _build_channel_resolve_results(
    services: CliServices,
    *,
    entries: list[str],
    channel: str | None,
    account: str | None,
    kind: str | None,
) -> list[dict[str, object]]:
    normalized_entries = [entry.strip() for entry in entries if entry.strip()]
    if not normalized_entries:
        raise ValueError("At least one entry is required.")
    normalized_kind = _normalize_channel_resolve_kind(kind)
    snapshot = await services.gateway_channels.build_snapshot()
    targets = _channel_resolve_route_targets(
        snapshot,
        channel=channel,
        account=account,
        kind=normalized_kind,
    )

    route_results: dict[str, dict[str, object]] = {}
    unresolved_entries: list[str] = []
    for entry in normalized_entries:
        target = _channel_resolve_match_entry(entry, targets)
        if target is None:
            unresolved_entries.append(entry)
            continue
        route_results[entry] = {
            "input": entry,
            "resolved": True,
            "id": target["id"],
            "name": target["name"],
            "note": "saved conversation target",
        }
    live_results: dict[str, dict[str, object]] = {}
    resolver = getattr(services.gateway_channels, "resolve_targets", None)
    if unresolved_entries and callable(resolver):
        grouped_entries: dict[str, list[str]] = {}
        for entry in unresolved_entries:
            resolver_kind = (
                _detect_channel_resolve_auto_kind(entry, channel)
                if normalized_kind == "auto"
                else normalized_kind
            )
            grouped_entries.setdefault(resolver_kind, []).append(entry)
        for resolver_kind, resolver_inputs in grouped_entries.items():
            resolved_live = await resolver(
                channel=_optional_cli_string(channel),
                account_id=_optional_cli_string(account),
                kind=resolver_kind,
                inputs=resolver_inputs,
            )
            if isinstance(resolved_live, list):
                for item in resolved_live:
                    if not isinstance(item, dict):
                        continue
                    input_value = _optional_cli_string(item.get("input"))
                    if input_value is None:
                        continue
                    live_results[input_value] = _normalize_channel_resolve_result(
                        input_value,
                        cast(dict[str, object], item),
                    )
    results: list[dict[str, object]] = []
    for entry in normalized_entries:
        results.append(
            route_results.get(entry)
            or live_results.get(entry)
            or {
                "input": entry,
                "resolved": False,
                "note": "native provider resolver unavailable",
            }
        )
    return results


def _normalize_channel_logs_channel(channel: str | None) -> str:
    normalized = (_optional_cli_string(channel) or "all").lower()
    if normalized == "all" or normalized in _CHANNEL_CAPABILITY_SUPPORT:
        return normalized
    return "all"


def _coerce_channel_logs_limit(lines: str | int | None) -> int:
    try:
        value = int(str(lines).strip()) if lines is not None else _CHANNEL_LOG_DEFAULT_LIMIT
    except ValueError:
        return _CHANNEL_LOG_DEFAULT_LIMIT
    if value <= 0:
        return _CHANNEL_LOG_DEFAULT_LIMIT
    return value


def _parse_channel_log_meta_name(raw: object) -> dict[str, str]:
    if not isinstance(raw, str):
        return {}
    try:
        parsed = json.loads(raw)
    except json.JSONDecodeError:
        return {}
    if not isinstance(parsed, dict):
        return {}
    result: dict[str, str] = {}
    for source_key, target_key in (("subsystem", "subsystem"), ("module", "module")):
        text = _optional_cli_string(parsed.get(source_key))
        if text is not None:
            result[target_key] = text
    return result


def _extract_channel_log_message(parsed: dict[str, object]) -> str:
    parts: list[str] = []
    numeric_keys = sorted(
        (key for key in parsed if key.isdecimal()),
        key=lambda item: int(item),
    )
    for key in numeric_keys:
        value = parsed.get(key)
        if isinstance(value, str):
            parts.append(value)
        elif value is not None:
            parts.append(json.dumps(value))
    return " ".join(parts)


def _parse_channel_log_line(raw: str) -> dict[str, object] | None:
    try:
        parsed = json.loads(raw)
    except json.JSONDecodeError:
        return None
    if not isinstance(parsed, dict):
        return None
    typed_parsed = cast(dict[str, object], parsed)
    meta = typed_parsed.get("_meta")
    typed_meta = cast(dict[str, object], meta) if isinstance(meta, dict) else {}
    name_meta = _parse_channel_log_meta_name(typed_meta.get("name"))
    result: dict[str, object] = {}
    time_text = _optional_cli_string(typed_parsed.get("time")) or _optional_cli_string(
        typed_meta.get("date")
    )
    if time_text is not None:
        result["time"] = time_text
    level = _optional_cli_string(typed_meta.get("logLevelName"))
    if level is not None:
        result["level"] = level.lower()
    result.update(name_meta)
    result["message"] = _extract_channel_log_message(typed_parsed)
    result["raw"] = raw
    return result


def _channel_log_matches_channel(line: dict[str, object], channel: str) -> bool:
    if channel == "all":
        return True
    subsystem = _optional_cli_string(line.get("subsystem")) or ""
    module = _optional_cli_string(line.get("module")) or ""
    return f"gateway/channels/{channel}" in subsystem or channel in module


async def _build_channel_logs_payload(
    services: CliServices,
    *,
    channel: str | None,
    lines: str | int | None,
) -> dict[str, object]:
    normalized_channel = _normalize_channel_logs_channel(channel)
    limit = _coerce_channel_logs_limit(lines)
    try:
        tail = await services.gateway_logs.read_tail(
            limit=limit * 4,
            max_bytes=_CHANNEL_LOG_MAX_BYTES,
        )
    except GatewayLogsUnavailableError as exc:
        raise ValueError(str(exc)) from exc
    raw_lines = tail.get("lines")
    if not isinstance(raw_lines, list):
        raw_lines = []
    parsed_lines = [
        parsed
        for parsed in (
            _parse_channel_log_line(str(raw_line))
            for raw_line in raw_lines
            if isinstance(raw_line, str)
        )
        if parsed is not None
    ]
    filtered_lines = [
        line
        for line in parsed_lines
        if _channel_log_matches_channel(line, normalized_channel)
    ]
    return {
        "file": str(tail.get("file") or ""),
        "channel": normalized_channel,
        "lines": filtered_lines[-limit:],
    }


async def _build_operator_dashboard(services: CliServices) -> DashboardView | SimpleNamespace:
    live_dashboard = await _try_live_dashboard_view(services.settings)
    if live_dashboard is not None:
        return live_dashboard
    project_rows = await services.database.list_projects()
    projects = [
        ProjectView.model_validate(services.project_service.inspect(row)) for row in project_rows
    ]
    instances = await services.manager.list_views()
    missions = await services.mission_service.list_views()
    doctrines = build_doctrines(missions, projects)
    gateway_capability = await services.gateway_capability.get_view()
    gateway_bootstrap = await services.gateway_bootstrap.get_view()
    preferred_memory_provider, preferred_executor = await load_saved_runtime_preferences(
        services.database
    )
    launchpad = build_launchpad(
        instances,
        missions,
        projects,
        doctrines=doctrines,
        gateway_capability=gateway_capability,
        preferred_memory_provider=preferred_memory_provider,
        preferred_executor=preferred_executor,
    )
    browser_posture = build_browser_posture(
        control_plane_url=_control_plane_base_url(services.settings),
        gateway_bootstrap=gateway_bootstrap,
        gateway_capability=gateway_capability,
    )
    return SimpleNamespace(
        brief=build_brief(
            instances,
            missions,
            projects,
            browser_posture=browser_posture,
        ),
        instances=instances,
        missions=missions,
        projects=projects,
        launchpad=launchpad,
        radar=build_radar(
            instances,
            missions,
            projects,
            browser_posture=browser_posture,
            gateway_capability=gateway_capability,
        ),
        browser_posture=browser_posture,
        gateway_capability=gateway_capability,
        gateway_bootstrap=gateway_bootstrap,
        ops_mesh=SimpleNamespace(skillbooks=[]),
    )


def _build_cli_conversation_target(
    *,
    conversation_channel: str | None,
    conversation_account_id: str | None,
    conversation_peer_kind: str | None,
    conversation_peer_id: str | None,
) -> ConversationTargetView | None:
    channel = str(conversation_channel or "").strip()
    account_id = str(conversation_account_id or "").strip() or None
    peer_kind = str(conversation_peer_kind or "").strip().lower() or None
    peer_id = str(conversation_peer_id or "").strip() or None
    if not channel and not account_id and not peer_kind and not peer_id:
        return None
    if not channel:
        raise ValueError(
            "Provide --conversation-channel when saving a conversation route target."
        )
    if bool(peer_kind) != bool(peer_id):
        raise ValueError(
            "Provide both --conversation-peer-kind and --conversation-peer-id together."
        )
    if peer_kind not in {None, "direct", "group", "channel"}:
        raise ValueError("--conversation-peer-kind must be one of: direct, group, channel.")
    resolved_peer_kind = cast(Literal["direct", "group", "channel"] | None, peer_kind)
    return ConversationTargetView(
        channel=channel,
        account_id=account_id,
        peer_kind=resolved_peer_kind,
        peer_id=peer_id,
    )


def _parse_cli_csv_list(value: str | None) -> list[str]:
    return [item.strip() for item in str(value or "").split(",") if item.strip()]


def _build_bootstrap_payload(
    *,
    setup_mode: str,
    setup_flow: str,
    project_path: Path,
    operator_name: str,
    task_name: str,
    objective_template: str,
    instance_mode: str,
    instance_id: int | None,
    instance_name: str,
    project_label: str | None,
    team_name: str | None,
    operator_email: str | None,
    issue_api_key: bool,
    task_summary: str | None,
    cadence_minutes: int,
    model: str,
    max_turns: int | None,
    use_builtin_agents: bool,
    run_verification: bool,
    auto_commit: bool,
    pause_on_approval: bool,
    allow_auto_reflexes: bool,
    auto_recover: bool,
    auto_recover_limit: int,
    reflex_cooldown_seconds: int,
    allow_failover: bool,
    enabled: bool,
    use_mempalace: bool,
    conversation_channel: str | None = None,
    conversation_account_id: str | None = None,
    conversation_peer_kind: str | None = None,
    conversation_peer_id: str | None = None,
) -> OnboardingBootstrapCreate:
    bootstrap_roles, bootstrap_scopes = default_device_bootstrap_profile()
    conversation_target = _build_cli_conversation_target(
        conversation_channel=conversation_channel,
        conversation_account_id=conversation_account_id,
        conversation_peer_kind=conversation_peer_kind,
        conversation_peer_id=conversation_peer_id,
    )
    return OnboardingBootstrapCreate(
        setup_mode=setup_mode,  # type: ignore[arg-type]
        setup_flow=setup_flow,  # type: ignore[arg-type]
        instance_mode=instance_mode,  # type: ignore[arg-type]
        instance_id=instance_id,
        instance_name=instance_name,
        project_path=str(project_path),
        project_label=project_label,
        operator_name=operator_name,
        operator_email=operator_email,
        team_name=team_name,
        issue_api_key=issue_api_key,
        bootstrap_roles=bootstrap_roles,
        bootstrap_scopes=bootstrap_scopes,
        task_name=task_name,
        task_summary=task_summary,
        objective_template=objective_template,
        conversation_target=conversation_target,
        cadence_minutes=cadence_minutes,
        model=model,
        max_turns=max_turns,
        use_builtin_agents=use_builtin_agents,
        run_verification=run_verification,
        auto_commit=auto_commit,
        pause_on_approval=pause_on_approval,
        allow_auto_reflexes=allow_auto_reflexes,
        auto_recover=auto_recover,
        auto_recover_limit=auto_recover_limit,
        reflex_cooldown_seconds=reflex_cooldown_seconds,
        allow_failover=allow_failover,
        enabled=enabled,
        use_mempalace=use_mempalace,
    )


def _encode_pairing_setup_code(payload: Mapping[str, object]) -> str:
    raw = json.dumps(payload, separators=(",", ":")).encode("utf-8")
    return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")


def _format_pairing_host(host: str) -> str:
    if ":" in host and not host.startswith("["):
        return f"[{host}]"
    return host


def _normalize_pairing_setup_url(raw: str) -> str:
    value = str(raw or "").strip()
    if not value:
        raise ValueError("Gateway URL unavailable.")
    candidate = value if "://" in value else f"wss://{value}"
    parsed = urlparse(candidate)
    if parsed.username or parsed.password:
        raise ValueError("Configured publicUrl is invalid.")
    scheme = parsed.scheme.lower()
    if scheme == "http":
        scheme = "ws"
    elif scheme == "https":
        scheme = "wss"
    if scheme not in {"ws", "wss"} or not parsed.hostname:
        raise ValueError("Configured publicUrl is invalid.")
    try:
        parsed_port = parsed.port
    except ValueError as exc:
        raise ValueError("Configured publicUrl is invalid.") from exc
    port = f":{parsed_port}" if parsed_port is not None else ""
    return f"{scheme}://{_format_pairing_host(parsed.hostname)}{port}"


def _resolve_qr_gateway_url(
    *,
    app_settings: Settings,
    url: str | None,
    public_url: str | None,
    remote: bool,
) -> tuple[str, str]:
    explicit_url = str(url or "").strip() or str(public_url or "").strip()
    if explicit_url:
        return _normalize_pairing_setup_url(explicit_url), (
            "cli.url" if str(url or "").strip() else "cli.publicUrl"
        )
    if remote:
        raise ValueError(
            "qr --remote requires gateway.remote.url (or gateway.tailscale.mode=serve/funnel)."
        )
    scheme = "wss" if remote else "ws"
    return (
        _normalize_pairing_setup_url(
            f"{scheme}://{app_settings.host}:{app_settings.port}"
        ),
        "openzues.settings",
    )


def _apply_swarm_launch_override(
    payload: MissionCreate,
    *,
    swarm_enabled: bool,
) -> MissionCreate:
    if not swarm_enabled:
        return payload
    return payload.model_copy(
        update={
            "swarm_enabled": True,
            "collaboration_mode": SWARM_COLLABORATION_MODE,
        }
    )


@app.command()
def serve(
    host: str = typer.Option(settings.host, help="Host to bind."),
    port: int = typer.Option(settings.port, help="Port to bind."),
    reload: bool = typer.Option(False, help="Enable hot reload."),
) -> None:
    settings.host = host
    settings.port = port
    os.environ["OPENZUES_HOST"] = host
    os.environ["OPENZUES_PORT"] = str(port)
    uvicorn.run(
        "openzues.app:create_app",
        host=host,
        port=port,
        reload=reload,
        factory=True,
    )


