@cron_app.command("create")
@cron_app.command("add")
def cron_add_command(
    name: str = typer.Option(..., "--name", help="Cron job name."),
    description: str | None = typer.Option(None, "--description", help="Optional description."),
    cron_expr: str | None = typer.Option(None, "--cron", help="Cron expression."),
    every: str | None = typer.Option(None, "--every", help="Run every duration, such as 10m."),
    at: str | None = typer.Option(None, "--at", help="Run once at an ISO time."),
    tz: str | None = typer.Option(None, "--tz", help="Timezone for cron expressions."),
    stagger: str | None = typer.Option(None, "--stagger", help="Cron stagger window."),
    exact: bool = typer.Option(False, "--exact", help="Disable cron staggering."),
    message: str | None = typer.Option(None, "--message", help="Agent message payload."),
    system_event: str | None = typer.Option(
        None,
        "--system-event",
        help="Main-session system event payload.",
    ),
    model: str | None = typer.Option(None, "--model", help="Model override for agent jobs."),
    thinking: str | None = typer.Option(None, "--thinking", help="Thinking level for agent jobs."),
    timeout_seconds: str | None = typer.Option(
        None,
        "--timeout-seconds",
        help="Timeout seconds for agent jobs.",
    ),
    light_context: bool = typer.Option(
        False,
        "--light-context",
        help="Use lightweight bootstrap context.",
    ),
    tools: str | None = typer.Option(None, "--tools", help="Tool allow-list."),
    session: str | None = typer.Option(None, "--session", help="Session target."),
    session_key: str | None = typer.Option(None, "--session-key", help="Session routing key."),
    wake: str = typer.Option("now", "--wake", help="Wake mode: now or next-heartbeat."),
    announce: bool = typer.Option(False, "--announce", help="Announce summary delivery."),
    no_deliver: bool = typer.Option(False, "--no-deliver", help="Disable announce delivery."),
    channel: str = typer.Option("last", "--channel", help="Announce delivery channel."),
    to: str | None = typer.Option(None, "--to", help="Delivery destination."),
    account: str | None = typer.Option(None, "--account", help="Delivery account id."),
    best_effort_deliver: bool = typer.Option(
        False,
        "--best-effort-deliver",
        help="Do not fail the job if delivery fails.",
    ),
    disabled: bool = typer.Option(False, "--disabled", help="Create the job disabled."),
    json_output: bool = typer.Option(False, "--json", help="Emit created cron job as JSON."),
) -> None:
    if announce and no_deliver:
        raise typer.BadParameter("Choose at most one of --announce or --no-deliver")
    schedule = _cron_cli_schedule(
        cron_expr=cron_expr,
        every=every,
        at=at,
        tz=tz,
        stagger=stagger,
        exact=exact,
    )
    payload = _cron_cli_payload(
        message=message,
        system_event=system_event,
        model=model,
        thinking=thinking,
        timeout_seconds=timeout_seconds,
        light_context=light_context,
        tools=tools,
    )
    wake_mode = _optional_cli_string(wake) or "now"
    if wake_mode not in {"now", "next-heartbeat"}:
        raise typer.BadParameter("--wake must be now or next-heartbeat")
    session_target = _optional_cli_string(session)
    if session_target is None:
        session_target = "isolated" if payload.get("kind") == "agentTurn" else "main"
    params: dict[str, object] = {
        "name": name,
        "enabled": not disabled,
        "schedule": schedule,
        "sessionTarget": session_target,
        "wakeMode": wake_mode,
        "payload": payload,
    }
    normalized_description = _optional_cli_string(description)
    if normalized_description is not None:
        params["description"] = normalized_description
    normalized_session_key = _optional_cli_string(session_key)
    if normalized_session_key is not None:
        params["sessionKey"] = normalized_session_key
    if payload.get("kind") == "agentTurn" and session_target != "main":
        delivery: dict[str, object] = {
            "mode": "none" if no_deliver else "announce",
            "channel": channel,
        }
        normalized_to = _optional_cli_string(to)
        if normalized_to is not None:
            delivery["to"] = normalized_to
        normalized_account = _optional_cli_string(account)
        if normalized_account is not None:
            delivery["accountId"] = normalized_account
        if best_effort_deliver:
            delivery["bestEffort"] = True
        params["delivery"] = delivery

    async def _action(services: CliServices) -> dict[str, object]:
        return await _call_gateway_node_method(services, "cron.add", params)

    result = _run(_run_with_services(_action))
    _emit_cron_mutation(result, json_output=json_output)


def _cron_has_schedule_options(
    *,
    cron_expr: str | None,
    every: str | None,
    at: str | None,
    tz: str | None,
    stagger: str | None,
    exact: bool,
) -> bool:
    return any(
        (
            _optional_cli_string(cron_expr),
            _optional_cli_string(every),
            _optional_cli_string(at),
            _optional_cli_string(tz),
            _optional_cli_string(stagger),
            exact,
        )
    )


def _cron_direct_schedule_option_count(
    *,
    cron_expr: str | None,
    every: str | None,
    at: str | None,
) -> int:
    return sum(
        value is not None
        for value in (
            _optional_cli_string(cron_expr),
            _optional_cli_string(every),
            _optional_cli_string(at),
        )
    )


def _cron_existing_schedule_patch(
    list_payload: dict[str, object],
    *,
    job_id: str,
    tz: str | None,
    stagger: str | None,
    exact: bool,
) -> dict[str, object]:
    if _optional_cli_string(stagger) is not None and exact:
        raise typer.BadParameter("Choose either --stagger or --exact, not both")
    jobs = list_payload.get("jobs")
    job_rows = jobs if isinstance(jobs, list) else []
    existing_job = next(
        (
            row
            for row in job_rows
            if isinstance(row, dict) and str(row.get("id") or "").strip() == job_id
        ),
        None,
    )
    if existing_job is None:
        raise typer.BadParameter(f"unknown cron job id: {job_id}")
    existing_schedule = existing_job.get("schedule")
    if not isinstance(existing_schedule, dict) or existing_schedule.get("kind") != "cron":
        raise typer.BadParameter("Current job is not a cron schedule; use --cron to convert first")
    expr = _optional_cli_string(existing_schedule.get("expr"))
    if expr is None:
        raise typer.BadParameter("Current cron schedule is missing an expression")
    schedule: dict[str, object] = {"kind": "cron", "expr": expr}
    normalized_tz = _optional_cli_string(tz)
    if normalized_tz is not None:
        schedule["tz"] = normalized_tz
    else:
        existing_tz = _optional_cli_string(existing_schedule.get("tz"))
        if existing_tz is not None:
            schedule["tz"] = existing_tz
    normalized_stagger = _optional_cli_string(stagger)
    if exact:
        schedule["staggerMs"] = 0
    elif normalized_stagger is not None:
        stagger_ms = _cron_duration_ms(normalized_stagger)
        if stagger_ms is None:
            raise typer.BadParameter("Invalid --stagger; use e.g. 30s, 1m, 5m")
        schedule["staggerMs"] = stagger_ms
    else:
        existing_stagger_ms = existing_schedule.get("staggerMs")
        if isinstance(existing_stagger_ms, int) and not isinstance(existing_stagger_ms, bool):
            schedule["staggerMs"] = existing_stagger_ms
    return schedule


def _cron_cli_failure_alert_patch(
    *,
    failure_alert: bool,
    no_failure_alert: bool,
    after: str | None,
    channel: str | None,
    to: str | None,
    cooldown: str | None,
    mode: str | None,
    account_id: str | None,
) -> dict[str, object] | bool | None:
    has_fields = any(
        _optional_cli_string(value) is not None
        for value in (after, channel, to, cooldown, mode, account_id)
    )
    if failure_alert and no_failure_alert:
        raise typer.BadParameter("Choose --failure-alert or --no-failure-alert, not both")
    if no_failure_alert and has_fields:
        raise typer.BadParameter("Use --no-failure-alert alone")
    if no_failure_alert:
        return False
    if not failure_alert and not has_fields:
        return None
    payload: dict[str, object] = {}
    normalized_after = _optional_cli_string(after)
    if normalized_after is not None:
        try:
            parsed_after = int(normalized_after)
        except ValueError as exc:
            raise typer.BadParameter("--failure-alert-after must be a positive integer") from exc
        if parsed_after <= 0:
            raise typer.BadParameter("--failure-alert-after must be a positive integer")
        payload["after"] = parsed_after
    normalized_channel = _optional_cli_string(channel)
    if normalized_channel is not None:
        payload["channel"] = normalized_channel.lower()
    normalized_to = _optional_cli_string(to)
    if normalized_to is not None:
        payload["to"] = normalized_to
    normalized_cooldown = _optional_cli_string(cooldown)
    if normalized_cooldown is not None:
        cooldown_ms = _cron_duration_ms(normalized_cooldown)
        if cooldown_ms is None:
            raise typer.BadParameter("Invalid --failure-alert-cooldown")
        payload["cooldownMs"] = cooldown_ms
    normalized_mode = _optional_cli_string(mode)
    if normalized_mode is not None:
        mode_value = normalized_mode.lower()
        if mode_value not in {"announce", "webhook"}:
            raise typer.BadParameter("--failure-alert-mode must be announce or webhook")
        payload["mode"] = mode_value
    normalized_account_id = _optional_cli_string(account_id)
    if normalized_account_id is not None:
        payload["accountId"] = normalized_account_id
    return payload


_OPENCLAW_TASK_STATUS_VALUES = (
    "queued",
    "running",
    "succeeded",
    "failed",
    "timed_out",
    "cancelled",
    "lost",
)
_OPENCLAW_TASK_RUNTIME_VALUES = ("subagent", "acp", "cli", "cron")
_OPENCLAW_TASK_NOTIFY_VALUES = ("done_only", "state_changes", "silent")
_OPENCLAW_TASK_DELIVERY_VALUES = (
    "pending",
    "delivered",
    "session_queued",
    "failed",
    "parent_missing",
    "not_applicable",
)
_OPENCLAW_TASK_AUDIT_CODES = (
    "stale_queued",
    "stale_running",
    "lost",
    "delivery_failed",
    "missing_cleanup",
    "inconsistent_timestamps",
)
_OPENCLAW_TASK_FLOW_AUDIT_CODES = (
    "restore_failed",
    "stale_running",
    "stale_waiting",
    "stale_blocked",
    "cancel_stuck",
    "missing_linked_tasks",
    "blocked_task_missing",
    "inconsistent_timestamps",
)
_TASK_AUDIT_STALE_QUEUED_MS = 10 * 60_000
_TASK_AUDIT_STALE_RUNNING_MS = 30 * 60_000


def _record_value(record: object, key: str, default: object = None) -> object:
    if isinstance(record, dict):
        return record.get(key, default)
    return getattr(record, key, default)


def _task_timestamp_ms(value: object) -> int | None:
    if isinstance(value, datetime):
        timestamp = value if value.tzinfo is not None else value.replace(tzinfo=UTC)
        return int(timestamp.timestamp() * 1000)
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        numeric = float(value)
        return int(numeric if numeric > 10_000_000_000 else numeric * 1000)
    text = _optional_cli_string(value)
    if text is None:
        return None
    try:
        parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
    except ValueError:
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=UTC)
    return int(parsed.timestamp() * 1000)


def _openclaw_task_add_optional(
    task: dict[str, object],
    key: str,
    value: object,
) -> None:
    if value is None:
        return
    if isinstance(value, str) and not value.strip():
        return
    task[key] = value


def _openclaw_task_status_from_mission(mission: object) -> str:
    status = str(_record_value(mission, "status", "") or "").strip().lower()
    if status == "completed":
        return "succeeded"
    if status == "failed":
        return "failed"
    if status == "blocked":
        return "failed"
    if status == "active" and bool(_record_value(mission, "in_progress", False)):
        return "running"
    return "queued"


def _openclaw_task_status_from_blueprint(task: object) -> str:
    if not bool(_record_value(task, "enabled", True)):
        return "cancelled"
    status = str(_record_value(task, "last_status", "") or "").strip().lower()
    if status in {"active", "running"}:
        return "running"
    if status == "completed":
        return "succeeded"
    if status == "failed":
        return "failed"
    return "queued"


def _openclaw_task_runtime_from_blueprint(task: object) -> str:
    schedule_kind = _optional_cli_string(_record_value(task, "schedule_kind"))
    cadence = _record_value(task, "cadence_minutes")
    if schedule_kind is not None or isinstance(cadence, int):
        return "cron"
    return "cli"


def _openclaw_task_record_from_mission(mission: object) -> dict[str, object] | None:
    mission_id = _record_value(mission, "id")
    if not isinstance(mission_id, int):
        return None
    task_id = f"mission:{mission_id}"
    status = _openclaw_task_status_from_mission(mission)
    created_ms = _task_timestamp_ms(_record_value(mission, "created_at")) or 0
    updated_ms = _task_timestamp_ms(
        _record_value(mission, "last_activity_at")
    ) or _task_timestamp_ms(_record_value(mission, "updated_at"))
    session_key = _optional_cli_string(_record_value(mission, "session_key"))
    run_id = _optional_cli_string(_record_value(mission, "thread_id")) or _optional_cli_string(
        _record_value(mission, "last_turn_id")
    )
    task: dict[str, object] = {
        "taskId": task_id,
        "runtime": "subagent",
        "taskKind": "mission",
        "sourceId": task_id,
        "requesterSessionKey": session_key or task_id,
        "ownerKey": task_id,
        "scopeKind": "session",
        "agentId": "openzues",
        "label": str(_record_value(mission, "name", "Mission")).strip() or task_id,
        "task": str(_record_value(mission, "objective", "") or "").strip(),
        "status": status,
        "deliveryStatus": "not_applicable",
        "notifyPolicy": "done_only",
        "createdAt": created_ms,
    }
    task_blueprint_id = _record_value(mission, "task_blueprint_id")
    if isinstance(task_blueprint_id, int):
        task["parentFlowId"] = f"task-blueprint:{task_blueprint_id}"
    _openclaw_task_add_optional(task, "childSessionKey", session_key)
    _openclaw_task_add_optional(task, "runId", run_id)
    if status in {"running", "succeeded", "failed"}:
        task["startedAt"] = created_ms
    if (
        status in {"succeeded", "failed", "timed_out", "cancelled", "lost"}
        and updated_ms is not None
    ):
        task["endedAt"] = updated_ms
    if updated_ms is not None:
        task["lastEventAt"] = updated_ms
    last_turn_id = _optional_cli_string(_record_value(mission, "last_turn_id"))
    if status == "running":
        _openclaw_task_add_optional(task, "progressSummary", last_turn_id)
    terminal_summary = _optional_cli_string(_record_value(mission, "last_checkpoint"))
    if terminal_summary is not None:
        task["terminalSummary"] = terminal_summary
    error = _optional_cli_string(_record_value(mission, "last_error"))
    if error is not None:
        task["error"] = error
    if status == "succeeded":
        task["terminalOutcome"] = "succeeded"
    elif status == "failed":
        task["terminalOutcome"] = "blocked"
    return task


async def _native_mission_records(services: CliServices) -> list[object]:
    list_missions = getattr(getattr(services, "mission_service", None), "list_views", None)
    if not callable(list_missions):
        return []
    return list(await list_missions())


async def _native_task_blueprint_records(services: CliServices) -> list[object]:
    list_task_blueprints = getattr(
        getattr(services, "ops_mesh", None),
        "list_task_blueprint_views",
        None,
    )
    if not callable(list_task_blueprints):
        return []
    return list(await list_task_blueprints())


async def _gateway_session_metadata_by_key(
    services: CliServices,
) -> dict[str, dict[str, object]]:
    database = getattr(services, "database", None)
    list_rows = getattr(database, "list_gateway_session_metadata_rows", None)
    if not callable(list_rows):
        return {}
    rows = await list_rows()
    metadata_by_key: dict[str, dict[str, object]] = {}
    for row in rows:
        if not isinstance(row, dict):
            continue
        session_key = _optional_cli_string(row.get("session_key"))
        metadata = row.get("metadata")
        if session_key is not None and isinstance(metadata, dict):
            metadata_by_key[session_key] = cast("dict[str, object]", metadata)
    return metadata_by_key


def _apply_task_session_metadata(
    task: dict[str, object],
    metadata_by_key: dict[str, dict[str, object]],
) -> None:
    for key in ("childSessionKey", "requesterSessionKey"):
        session_key = _optional_cli_string(task.get(key))
        if session_key is None:
            continue
        metadata = metadata_by_key.get(session_key)
        if metadata is None:
            continue
        notify_policy = _optional_cli_string(metadata.get("taskNotifyPolicy"))
        if notify_policy in _OPENCLAW_TASK_NOTIFY_VALUES:
            task["notifyPolicy"] = notify_policy
            return


def _openclaw_task_record_from_blueprint(blueprint: object) -> dict[str, object] | None:
    task_id_value = _record_value(blueprint, "id")
    if not isinstance(task_id_value, int):
        return None
    task_id = f"task-blueprint:{task_id_value}"
    status = _openclaw_task_status_from_blueprint(blueprint)
    created_ms = _task_timestamp_ms(_record_value(blueprint, "created_at")) or 0
    updated_ms = _task_timestamp_ms(_record_value(blueprint, "updated_at"))
    launched_ms = _task_timestamp_ms(_record_value(blueprint, "last_launched_at"))
    task_text = (
        _optional_cli_string(_record_value(blueprint, "objective_template"))
        or _optional_cli_string(_record_value(blueprint, "summary"))
        or _optional_cli_string(_record_value(blueprint, "name"))
        or task_id
    )
    task: dict[str, object] = {
        "taskId": task_id,
        "runtime": _openclaw_task_runtime_from_blueprint(blueprint),
        "taskKind": "task_blueprint",
        "sourceId": task_id,
        "requesterSessionKey": task_id,
        "ownerKey": task_id,
        "scopeKind": "system",
        "label": _optional_cli_string(_record_value(blueprint, "name")) or task_id,
        "task": task_text,
        "status": status,
        "deliveryStatus": "not_applicable",
        "notifyPolicy": "done_only",
        "createdAt": created_ms,
    }
    if launched_ms is not None:
        task["startedAt"] = launched_ms
    if (
        status in {"succeeded", "failed", "timed_out", "cancelled", "lost"}
        and updated_ms is not None
    ):
        task["endedAt"] = updated_ms
    if updated_ms is not None:
        task["lastEventAt"] = updated_ms
    terminal_summary = _optional_cli_string(_record_value(blueprint, "last_result_summary"))
    if terminal_summary is not None:
        task["terminalSummary"] = terminal_summary
    if status == "succeeded":
        task["terminalOutcome"] = "succeeded"
    elif status == "failed":
        task["terminalOutcome"] = "blocked"
    return task


def _openclaw_task_metadata_timestamp_ms(value: object) -> int | None:
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return int(value)
    return _task_timestamp_ms(value)


def _openclaw_task_record_from_session_metadata(
    session_key: str,
    metadata: Mapping[str, object],
) -> dict[str, object] | None:
    raw_record = metadata.get("taskRecord")
    if not isinstance(raw_record, Mapping):
        return None
    task_id = _optional_cli_string(raw_record.get("taskId"))
    runtime = _optional_cli_string(raw_record.get("runtime"))
    requester_session_key = _optional_cli_string(raw_record.get("requesterSessionKey"))
    owner_key = _optional_cli_string(raw_record.get("ownerKey"))
    scope_kind = _optional_cli_string(raw_record.get("scopeKind"))
    task_text = _optional_cli_string(raw_record.get("task"))
    status = _optional_cli_string(raw_record.get("status"))
    delivery_status = _optional_cli_string(raw_record.get("deliveryStatus"))
    notify_policy = _optional_cli_string(raw_record.get("notifyPolicy"))
    created_ms = _openclaw_task_metadata_timestamp_ms(raw_record.get("createdAt"))
    if (
        task_id is None
        or runtime not in _OPENCLAW_TASK_RUNTIME_VALUES
        or requester_session_key is None
        or owner_key is None
        or scope_kind not in {"session", "system"}
        or task_text is None
        or status not in _OPENCLAW_TASK_STATUS_VALUES
        or delivery_status not in _OPENCLAW_TASK_DELIVERY_VALUES
        or notify_policy not in _OPENCLAW_TASK_NOTIFY_VALUES
        or created_ms is None
    ):
        return None
    task: dict[str, object] = {
        "taskId": task_id,
        "runtime": runtime,
        "requesterSessionKey": requester_session_key,
        "ownerKey": owner_key,
        "scopeKind": scope_kind,
        "task": task_text,
        "status": status,
        "deliveryStatus": delivery_status,
        "notifyPolicy": notify_policy,
        "createdAt": created_ms,
    }
    for key in (
        "taskKind",
        "sourceId",
        "childSessionKey",
        "parentFlowId",
        "parentTaskId",
        "agentId",
        "runId",
        "label",
        "error",
        "progressSummary",
        "terminalSummary",
        "terminalOutcome",
    ):
        _openclaw_task_add_optional(task, key, _optional_cli_string(raw_record.get(key)))
    child_session_key = _optional_cli_string(task.get("childSessionKey"))
    if child_session_key is None:
        task["childSessionKey"] = session_key
    for key in ("startedAt", "endedAt", "lastEventAt", "cleanupAfter"):
        timestamp_ms = _openclaw_task_metadata_timestamp_ms(raw_record.get(key))
        if timestamp_ms is not None:
            task[key] = timestamp_ms
    return task


async def _list_openclaw_background_tasks(services: CliServices) -> list[dict[str, object]]:
    records: list[dict[str, object]] = []
    for mission in await _native_mission_records(services):
        record = _openclaw_task_record_from_mission(mission)
        if record is not None:
            records.append(record)
    for blueprint in await _native_task_blueprint_records(services):
        record = _openclaw_task_record_from_blueprint(blueprint)
        if record is not None:
            records.append(record)
    metadata_by_key = await _gateway_session_metadata_by_key(services)
    if metadata_by_key:
        for session_key, metadata in metadata_by_key.items():
            record = _openclaw_task_record_from_session_metadata(session_key, metadata)
            if record is not None:
                records.append(record)
        for record in records:
            _apply_task_session_metadata(record, metadata_by_key)
    return records


def _filter_openclaw_tasks(
    tasks: list[dict[str, object]],
    *,
    runtime_filter: str | None,
    status_filter: str | None,
) -> list[dict[str, object]]:
    return [
        task
        for task in tasks
        if (runtime_filter is None or task.get("runtime") == runtime_filter)
        and (status_filter is None or task.get("status") == status_filter)
    ]


async def _build_tasks_list_payload(
    services: CliServices,
    *,
    runtime_filter: str | None,
    status_filter: str | None,
) -> dict[str, object]:
    normalized_runtime = _optional_cli_string(runtime_filter)
    normalized_status = _optional_cli_string(status_filter)
    tasks = _filter_openclaw_tasks(
        await _list_openclaw_background_tasks(services),
        runtime_filter=normalized_runtime,
        status_filter=normalized_status,
    )
    return {
        "count": len(tasks),
        "runtime": normalized_runtime,
        "status": normalized_status,
        "tasks": tasks,
    }


def _openclaw_task_matches_lookup(task: dict[str, object], lookup: str) -> bool:
    lookup_token = lookup.strip()
    if not lookup_token:
        return False
    for key in (
        "taskId",
        "runId",
        "childSessionKey",
        "requesterSessionKey",
        "sourceId",
        "ownerKey",
    ):
        value = _optional_cli_string(task.get(key))
        if value == lookup_token:
            return True
    return False


def _cli_timestamp_ms_iso(value: object) -> str | None:
    timestamp_ms = _openclaw_task_metadata_timestamp_ms(value)
    if timestamp_ms is None:
        return None
    return (
        datetime.fromtimestamp(timestamp_ms / 1000, tz=UTC)
        .isoformat()
        .replace("+00:00", "Z")
    )


async def _resolve_openclaw_task(services: CliServices, lookup: str) -> dict[str, object] | None:
    for task in await _list_openclaw_background_tasks(services):
        if _openclaw_task_matches_lookup(task, lookup):
            return task
    return None


def _mission_id_from_task_record(task: dict[str, object]) -> int | None:
    task_id = _optional_cli_string(task.get("taskId"))
    if task_id is None or not task_id.startswith("mission:"):
        return None
    try:
        return int(task_id.removeprefix("mission:"))
    except ValueError:
        return None


def _acp_runtime_id_from_session_key(session_key: str | None) -> str | None:
    normalized = _optional_cli_string(session_key)
    if normalized is None or ":acp:" not in normalized:
        return None
    runtime_id = normalized.rsplit(":acp:", 1)[-1].strip()
    return runtime_id or None


def _acp_status_json_mapping(value: object) -> dict[str, object]:
    if not isinstance(value, Mapping):
        return {}
    return {
        str(key): item
        for key, item in value.items()
        if isinstance(key, str)
    }


def _acp_status_is_row(row: object) -> bool:
    if not isinstance(row, dict):
        return False
    session_key = _optional_cli_string(row.get("session_key"))
    metadata = row.get("metadata")
    if not isinstance(metadata, Mapping):
        return False
    return metadata.get("runtime") == "acp" or (
        session_key is not None and ":acp:" in session_key
    )


def _acp_status_latest_task_for_session(
    tasks: list[dict[str, object]],
    session_key: str,
) -> dict[str, object] | None:
    matches = [
        task
        for task in tasks
        if _optional_cli_string(task.get("childSessionKey")) == session_key
        or _optional_cli_string(task.get("requesterSessionKey")) == session_key
    ]
    if not matches:
        return None
    return max(
        matches,
        key=lambda task: (
            _openclaw_task_metadata_timestamp_ms(task.get("lastEventAt"))
            or _openclaw_task_metadata_timestamp_ms(task.get("startedAt"))
            or _openclaw_task_metadata_timestamp_ms(task.get("createdAt"))
            or 0
        ),
    )


def _acp_status_task_payload(task: dict[str, object]) -> dict[str, object]:
    payload: dict[str, object] = {}
    for key in (
        "taskId",
        "status",
        "deliveryStatus",
        "runId",
        "progressSummary",
        "terminalSummary",
        "error",
    ):
        value = _optional_cli_string(task.get(key))
        if value is not None:
            payload[key] = value
    updated_at = _cli_timestamp_ms_iso(task.get("lastEventAt"))
    if updated_at is not None:
        payload["taskUpdatedAt"] = updated_at
    return payload


def _acp_status_record_from_metadata_row(
    row: dict[str, object],
    *,
    linked_task: dict[str, object] | None,
) -> dict[str, object] | None:
    session_key = _optional_cli_string(row.get("session_key"))
    metadata = row.get("metadata")
    if session_key is None or not isinstance(metadata, Mapping):
        return None
    metadata_mapping = cast("Mapping[str, object]", metadata)
    backend = (
        _optional_cli_string(metadata_mapping.get("backend"))
        or _optional_cli_string(metadata_mapping.get("acpBackend"))
        or "codex"
    )
    agent = (
        _optional_cli_string(metadata_mapping.get("agentId"))
        or _optional_cli_string(metadata_mapping.get("targetAgentId"))
        or _agent_id_from_session_key(session_key)
        or "openzues"
    )
    session_mode = (
        _optional_cli_string(metadata_mapping.get("acpMode"))
        or _optional_cli_string(metadata_mapping.get("mode"))
        or _optional_cli_string(metadata_mapping.get("spawnMode"))
        or "run"
    )
    state = (
        _optional_cli_string(metadata_mapping.get("acpState"))
        or _optional_cli_string(metadata_mapping.get("state"))
        or (
            _optional_cli_string(linked_task.get("status"))
            if linked_task is not None
            else None
        )
        or "known"
    )
    last_activity_at = (
        _optional_cli_string(metadata_mapping.get("lastActivityAt"))
        or _optional_cli_string(row.get("updated_at"))
        or (
            _cli_timestamp_ms_iso(linked_task.get("lastEventAt"))
            if linked_task is not None
            else None
        )
        or _cli_timestamp_ms_iso(metadata_mapping.get("createdAt"))
        or _cli_timestamp_ms_iso(metadata_mapping.get("startedAt"))
    )
    record: dict[str, object] = {
        "sessionKey": session_key,
        "backend": backend,
        "agent": agent,
        "sessionMode": session_mode,
        "state": state,
        "runtimeOptions": _acp_status_json_mapping(
            metadata_mapping.get("runtimeOptions")
        ),
        "capabilities": _acp_status_json_mapping(metadata_mapping.get("capabilities")),
    }
    if last_activity_at is not None:
        record["lastActivityAt"] = last_activity_at
    for source_key, output_key in (
        ("label", "label"),
        ("runtimeThreadId", "runtimeThreadId"),
        ("runtimeSessionId", "runtimeSessionId"),
        ("streamTo", "streamTo"),
        ("streamLogPath", "streamLogPath"),
        ("spawnedWorkspaceDir", "cwd"),
    ):
        value = _optional_cli_string(metadata_mapping.get(source_key))
        if value is not None:
            record[output_key] = value
    runtime_id = metadata_mapping.get("runtimeId")
    if isinstance(runtime_id, int) and not isinstance(runtime_id, bool):
        record["runtimeId"] = runtime_id
    identity = _acp_status_json_mapping(metadata_mapping.get("identity"))
    if identity:
        record["identity"] = identity
    if linked_task is not None:
        task_payload = _acp_status_task_payload(linked_task)
        if task_payload:
            record["task"] = task_payload
            task_key_map = (
                ("taskId", "taskId"),
                ("status", "taskStatus"),
                ("deliveryStatus", "delivery"),
                ("progressSummary", "taskProgress"),
                ("terminalSummary", "taskSummary"),
                ("error", "taskError"),
                ("taskUpdatedAt", "taskUpdatedAt"),
            )
            for task_key, record_key in task_key_map:
                task_value = task_payload.get(task_key)
                if task_value is not None:
                    record[record_key] = task_value
    last_error = _optional_cli_string(metadata_mapping.get("lastError"))
    if last_error is not None:
        record["lastError"] = last_error
    runtime_status = _acp_status_json_mapping(metadata_mapping.get("runtimeStatus"))
    if runtime_status:
        record["runtimeStatus"] = runtime_status
    return record


def _acp_status_record_matches_lookup(
    record: dict[str, object],
    lookup: str,
) -> bool:
    lookup_token = lookup.strip()
    if not lookup_token:
        return False
    for key in (
        "sessionKey",
        "runtimeThreadId",
        "runtimeSessionId",
        "label",
        "taskId",
    ):
        if _optional_cli_string(record.get(key)) == lookup_token:
            return True
    session_runtime_id = _acp_runtime_id_from_session_key(
        _optional_cli_string(record.get("sessionKey"))
    )
    if session_runtime_id == lookup_token:
        return True
    task = record.get("task")
    if isinstance(task, dict):
        for key in ("taskId", "runId"):
            if _optional_cli_string(task.get(key)) == lookup_token:
                return True
    return False


async def _list_acp_status_records(
    services: CliServices,
) -> list[dict[str, object]]:
    database = getattr(services, "database", None)
    list_rows = getattr(database, "list_gateway_session_metadata_rows", None)
    if not callable(list_rows):
        return []
    tasks = await _list_openclaw_background_tasks(services)
    records: list[dict[str, object]] = []
    for row in await list_rows():
        if not _acp_status_is_row(row):
            continue
        typed_row = cast("dict[str, object]", row)
        session_key = _optional_cli_string(typed_row.get("session_key"))
        if session_key is None:
            continue
        record = _acp_status_record_from_metadata_row(
            typed_row,
            linked_task=_acp_status_latest_task_for_session(tasks, session_key),
        )
        if record is not None:
            records.append(record)
    records.sort(key=lambda item: str(item.get("sessionKey") or ""))
    return records


async def _build_acp_status_payload(
    services: CliServices,
    *,
    lookup: str | None,
) -> dict[str, object]:
    normalized_lookup = _optional_cli_string(lookup)
    records = await _list_acp_status_records(services)
    if normalized_lookup is not None:
        matches = [
            record
            for record in records
            if _acp_status_record_matches_lookup(record, normalized_lookup)
        ]
        if not matches:
            raise ValueError(f"ACP session not found: {normalized_lookup}")
        return {
            "ok": True,
            "lookup": normalized_lookup,
            "count": len(matches),
            "session": matches[0],
            "sessions": matches,
        }
    payload: dict[str, object] = {
        "ok": True,
        "lookup": None,
        "count": len(records),
        "sessions": records,
    }
    if len(records) == 1:
        payload["session"] = records[0]
    return payload


def _format_acp_status_value(value: object) -> str:
    if isinstance(value, Mapping) or isinstance(value, list):
        if not value:
            return "-"
        return json.dumps(value, sort_keys=True, separators=(",", ":"))
    text = _optional_cli_string(value)
    return text or "-"


def _format_acp_status_capabilities(value: object) -> str:
    if isinstance(value, Mapping):
        controls = value.get("controls")
        if isinstance(controls, list):
            items = [
                item
                for item in (_optional_cli_string(raw_item) for raw_item in controls)
                if item is not None
            ]
            if items:
                return ", ".join(items)
    return _format_acp_status_value(value)


def _emit_acp_status_single(record: dict[str, object]) -> None:
    typer.echo("ACP status:")
    typer.echo("-----")
    typer.echo(f"session: {record.get('sessionKey')}")
    typer.echo(f"backend: {record.get('backend')}")
    typer.echo(f"agent: {record.get('agent')}")
    identity = record.get("identity")
    if isinstance(identity, Mapping):
        for key in sorted(identity):
            value = _optional_cli_string(identity.get(key))
            if value is not None:
                typer.echo(f"identity.{key}: {value}")
    typer.echo(f"sessionMode: {record.get('sessionMode')}")
    typer.echo(f"state: {record.get('state')}")
    for key, label in (
        ("taskId", "taskId"),
        ("taskStatus", "taskStatus"),
        ("delivery", "delivery"),
        ("taskProgress", "taskProgress"),
        ("taskSummary", "taskSummary"),
        ("taskError", "taskError"),
        ("taskUpdatedAt", "taskUpdatedAt"),
    ):
        value = _optional_cli_string(record.get(key))
        if value is not None:
            typer.echo(f"{label}: {value}")
    typer.echo(
        "runtimeOptions: "
        + _format_acp_status_value(record.get("runtimeOptions"))
    )
    typer.echo(
        "capabilities: "
        + _format_acp_status_capabilities(record.get("capabilities"))
    )
    typer.echo(f"lastActivityAt: {record.get('lastActivityAt') or '-'}")
    last_error = _optional_cli_string(record.get("lastError"))
    if last_error is not None:
        typer.echo(f"lastError: {last_error}")
    runtime_status = record.get("runtimeStatus")
    if isinstance(runtime_status, Mapping):
        summary = _optional_cli_string(runtime_status.get("summary"))
        details = _optional_cli_string(runtime_status.get("details"))
        if summary is not None:
            typer.echo(f"runtime: {summary}")
        if details is not None:
            typer.echo(f"runtimeDetails: {details}")


def _emit_acp_status(payload: dict[str, object], *, json_output: bool) -> None:
    if json_output:
        _emit_payload(payload, json_output=True)
        return
    session = payload.get("session")
    if isinstance(session, dict):
        _emit_acp_status_single(cast("dict[str, object]", session))
        return
    raw_sessions = payload.get("sessions")
    sessions = (
        [cast("dict[str, object]", item) for item in raw_sessions if isinstance(item, dict)]
        if isinstance(raw_sessions, list)
        else []
    )
    if not sessions:
        typer.echo("No ACP sessions found.")
        return
    typer.echo(f"ACP sessions: {len(sessions)}")
    for record in sessions:
        session_key = _optional_cli_string(record.get("sessionKey")) or "-"
        mode = _optional_cli_string(record.get("sessionMode")) or "run"
        state = _optional_cli_string(record.get("state")) or "known"
        backend = _optional_cli_string(record.get("backend")) or "codex"
        runtime_thread_id = _optional_cli_string(record.get("runtimeThreadId"))
        thread_text = f", thread:{runtime_thread_id}" if runtime_thread_id is not None else ""
        typer.echo(f"- {session_key} ({mode}, {state}, backend:{backend}{thread_text})")


def _cli_acp_spawn_service(services: CliServices) -> object | None:
    for container in (services, getattr(services, "gateway_node_methods", None)):
        if container is None:
            continue
        for attribute in (
            "acp_spawn_service",
            "gateway_acp_spawn_service",
            "_acp_spawn_service",
        ):
            service = getattr(container, attribute, None)
            if service is not None:
                return service
    return None


async def _cancel_openclaw_acp_task(
    services: CliServices,
    task: dict[str, object],
    lookup: str,
) -> str:
    session_key = _optional_cli_string(task.get("childSessionKey"))
    database = getattr(services, "database", None)
    get_metadata = getattr(database, "get_gateway_session_metadata", None)
    upsert_metadata = getattr(database, "upsert_gateway_session_metadata", None)
    if session_key is None or not callable(get_metadata) or not callable(upsert_metadata):
        raise ValueError(f"Could not cancel task: {lookup}")
    metadata_row = await get_metadata(session_key)
    existing_metadata = (
        metadata_row.get("metadata") if isinstance(metadata_row, dict) else None
    )
    if not isinstance(existing_metadata, dict):
        raise ValueError(f"Could not cancel task: {lookup}")
    metadata = dict(existing_metadata)
    raw_task_record = metadata.get("taskRecord")
    if not isinstance(raw_task_record, Mapping):
        raise ValueError(f"Could not cancel task: {lookup}")
    task_record = {
        str(key): value
        for key, value in raw_task_record.items()
        if isinstance(key, str)
    }
    runtime_thread_id = (
        _optional_cli_string(metadata.get("runtimeThreadId"))
        or _optional_cli_string(metadata.get("runtimeSessionId"))
        or _acp_runtime_id_from_session_key(session_key)
    )
    runtime_session_id = _optional_cli_string(metadata.get("runtimeSessionId")) or runtime_thread_id
    acp_service = _cli_acp_spawn_service(services)
    cancel_session = getattr(acp_service, "cancel_session", None)
    if not callable(cancel_session):
        raise ValueError(f"Could not cancel task: {lookup}")
    cancel_result = await cancel_session(
        session_key=session_key,
        runtime_thread_id=runtime_thread_id,
        runtime_session_id=runtime_session_id,
        reason="task-cancel",
    )
    if isinstance(cancel_result, dict):
        status = _optional_cli_string(cancel_result.get("status"))
        if status in {"error", "timeout"}:
            detail = _optional_cli_string(cancel_result.get("error")) or _optional_cli_string(
                cancel_result.get("reason")
            )
            raise ValueError(detail or f"Could not cancel task: {lookup}")
    now_ms = int(time.time() * 1000)
    task_record["status"] = "cancelled"
    task_record["endedAt"] = now_ms
    task_record["lastEventAt"] = now_ms
    task_record["error"] = "Cancelled by operator."
    task_record.pop("terminalOutcome", None)
    metadata["taskRecord"] = task_record
    await upsert_metadata(session_key=session_key, metadata=metadata)
    run_id = _optional_cli_string(task_record.get("runId")) or _optional_cli_string(
        task.get("runId")
    )
    run_text = f" run {run_id}" if run_id is not None else ""
    task_id = _optional_cli_string(task_record.get("taskId")) or str(task.get("taskId"))
    runtime = _optional_cli_string(task_record.get("runtime")) or str(task.get("runtime"))
    return f"Cancelled {task_id} ({runtime}){run_text}."


async def _cancel_openclaw_task(services: CliServices, lookup: str) -> str:
    task = await _resolve_openclaw_task(services, lookup)
    if task is None:
        raise ValueError(f"Task not found: {lookup}")
    status = _optional_cli_string(task.get("status"))
    if status not in {"queued", "running"}:
        raise ValueError(f"Could not cancel task: {lookup}")
    if _optional_cli_string(task.get("runtime")) == "acp":
        return await _cancel_openclaw_acp_task(services, task, lookup)
    mission_id = _mission_id_from_task_record(task)
    pause = getattr(getattr(services, "mission_service", None), "pause", None)
    if mission_id is None or not callable(pause):
        raise ValueError(f"Could not cancel task: {lookup}")
    await pause(mission_id)
    run_id = _optional_cli_string(task.get("runId"))
    run_text = f" run {run_id}" if run_id is not None else ""
    return f"Cancelled {task.get('taskId')} ({task.get('runtime')}){run_text}."


async def _set_openclaw_task_notify_policy(
    services: CliServices,
    *,
    lookup: str,
    notify_policy: str,
) -> str:
    normalized_policy = _optional_cli_string(notify_policy)
    if normalized_policy not in _OPENCLAW_TASK_NOTIFY_VALUES:
        raise ValueError("Notify policy must be done_only, state_changes, or silent.")
    task = await _resolve_openclaw_task(services, lookup)
    if task is None:
        raise ValueError(f"Task not found: {lookup}")
    session_key = _optional_cli_string(task.get("childSessionKey")) or _optional_cli_string(
        task.get("requesterSessionKey")
    )
    database = getattr(services, "database", None)
    get_metadata = getattr(database, "get_gateway_session_metadata", None)
    upsert_metadata = getattr(database, "upsert_gateway_session_metadata", None)
    if session_key is None or not callable(get_metadata) or not callable(upsert_metadata):
        raise ValueError(f"Could not update task notify policy: {lookup}")
    existing_row = await get_metadata(session_key)
    existing_metadata = (
        existing_row.get("metadata")
        if isinstance(existing_row, dict)
        else None
    )
    metadata = dict(existing_metadata) if isinstance(existing_metadata, dict) else {}
    metadata["taskNotifyPolicy"] = normalized_policy
    await upsert_metadata(session_key=session_key, metadata=metadata)
    return f"Updated {task.get('taskId')} notify policy to {normalized_policy}."


def _task_status_counts(tasks: list[dict[str, object]]) -> dict[str, int]:
    counts = dict.fromkeys(_OPENCLAW_TASK_STATUS_VALUES, 0)
    for task in tasks:
        status = str(task.get("status") or "")
        if status in counts:
            counts[status] += 1
    return counts


def _task_failure_count(tasks: list[dict[str, object]]) -> int:
    return sum(
        1
        for task in tasks
        if task.get("status") in {"failed", "timed_out", "lost"}
        or _optional_cli_string(task.get("error")) is not None
    )


def _summarize_openclaw_tasks(tasks: list[dict[str, object]]) -> dict[str, object]:
    by_status = dict.fromkeys(_OPENCLAW_TASK_STATUS_VALUES, 0)
    by_runtime = dict.fromkeys(_OPENCLAW_TASK_RUNTIME_VALUES, 0)
    active = 0
    terminal = 0
    failures = 0
    for task in tasks:
        status = _optional_cli_string(task.get("status")) or ""
        runtime = _optional_cli_string(task.get("runtime")) or ""
        if status in by_status:
            by_status[status] += 1
        if runtime in by_runtime:
            by_runtime[runtime] += 1
        if status in {"queued", "running"}:
            active += 1
        else:
            terminal += 1
        if status in {"failed", "timed_out", "lost"}:
            failures += 1
    return {
        "total": len(tasks),
        "active": active,
        "terminal": terminal,
        "failures": failures,
        "byStatus": by_status,
        "byRuntime": by_runtime,
    }


def _tasks_cli_positive_int(value: str | None, *, option: str) -> int | None:
    normalized = _optional_cli_string(value)
    if normalized is None:
        return None
    try:
        parsed = int(normalized)
    except ValueError as exc:
        raise typer.BadParameter(f"{option} must be a positive integer") from exc
    if parsed <= 0:
        raise typer.BadParameter(f"{option} must be a positive integer")
    return parsed


def _task_int_field(task: dict[str, object], key: str) -> int | None:
    value = task.get(key)
    if isinstance(value, int) and not isinstance(value, bool):
        return value
    return None


def _task_audit_reference_ms(task: dict[str, object]) -> int:
    return (
        _task_int_field(task, "lastEventAt")
        or _task_int_field(task, "startedAt")
        or _task_int_field(task, "createdAt")
        or 0
    )


def _task_audit_finding(
    *,
    severity: str,
    code: str,
    task: dict[str, object],
    detail: str,
    age_ms: int | None = None,
) -> dict[str, object]:
    finding: dict[str, object] = {
        "kind": "task",
        "severity": severity,
        "code": code,
        "detail": detail,
        "status": task.get("status") or "n/a",
        "token": task.get("taskId"),
        "task": task,
    }
    if age_ms is not None:
        finding["ageMs"] = age_ms
    return finding


def _list_task_audit_findings(
    tasks: list[dict[str, object]],
    *,
    now_ms: int | None = None,
) -> list[dict[str, object]]:
    now = now_ms if now_ms is not None else int(time.time() * 1000)
    findings: list[dict[str, object]] = []
    for task in tasks:
        reference_ms = _task_audit_reference_ms(task)
        age_ms = max(0, now - reference_ms)
        status = _optional_cli_string(task.get("status")) or ""
        if status == "queued" and age_ms >= _TASK_AUDIT_STALE_QUEUED_MS:
            findings.append(
                _task_audit_finding(
                    severity="warn",
                    code="stale_queued",
                    task=task,
                    age_ms=age_ms,
                    detail="queued task has not advanced recently",
                )
            )
        if status == "running" and age_ms >= _TASK_AUDIT_STALE_RUNNING_MS:
            findings.append(
                _task_audit_finding(
                    severity="error",
                    code="stale_running",
                    task=task,
                    age_ms=age_ms,
                    detail="running task appears stuck",
                )
            )
        if status == "lost":
            findings.append(
                _task_audit_finding(
                    severity="error",
                    code="lost",
                    task=task,
                    age_ms=age_ms,
                    detail=_optional_cli_string(task.get("error"))
                    or "task lost its backing session",
                )
            )
        if task.get("deliveryStatus") == "failed" and task.get("notifyPolicy") != "silent":
            findings.append(
                _task_audit_finding(
                    severity="warn",
                    code="delivery_failed",
                    task=task,
                    age_ms=age_ms,
                    detail="terminal update delivery failed",
                )
            )
        if status not in {"lost", "queued", "running"} and not isinstance(
            task.get("cleanupAfter"),
            int,
        ):
            findings.append(
                _task_audit_finding(
                    severity="warn",
                    code="missing_cleanup",
                    task=task,
                    age_ms=age_ms,
                    detail="terminal task is missing cleanupAfter",
                )
            )
        created_ms = _task_int_field(task, "createdAt")
        started_ms = _task_int_field(task, "startedAt")
        ended_ms = _task_int_field(task, "endedAt")
        if created_ms is not None and started_ms is not None and started_ms < created_ms:
            findings.append(
                _task_audit_finding(
                    severity="warn",
                    code="inconsistent_timestamps",
                    task=task,
                    detail="startedAt is earlier than createdAt",
                )
            )
        if started_ms is not None and ended_ms is not None and ended_ms < started_ms:
            findings.append(
                _task_audit_finding(
                    severity="warn",
                    code="inconsistent_timestamps",
                    task=task,
                    detail="endedAt is earlier than startedAt",
                )
            )
        if status in {"queued", "running"} and ended_ms is not None:
            findings.append(
                _task_audit_finding(
                    severity="warn",
                    code="inconsistent_timestamps",
                    task=task,
                    detail=f"{status} task should not already have endedAt",
                )
            )
    return sorted(findings, key=_task_audit_sort_key)


def _task_audit_sort_key(finding: dict[str, object]) -> tuple[int, int, int]:
    severity_rank = 0 if finding.get("severity") == "error" else 1
    age = finding.get("ageMs")
    age_ms = age if isinstance(age, int) else -1
    task = finding.get("task")
    created_ms = (
        _task_int_field(task, "createdAt")
        if isinstance(task, dict)
        else None
    )
    return (severity_rank, -age_ms, created_ms or 0)


def _empty_task_audit_summary() -> dict[str, object]:
    return {
        "total": 0,
        "warnings": 0,
        "errors": 0,
        "byCode": dict.fromkeys(_OPENCLAW_TASK_AUDIT_CODES, 0),
    }


def _empty_task_flow_audit_summary() -> dict[str, object]:
    return {
        "total": 0,
        "warnings": 0,
        "errors": 0,
        "byCode": dict.fromkeys(_OPENCLAW_TASK_FLOW_AUDIT_CODES, 0),
    }


def _empty_task_flow_maintenance_summary() -> dict[str, int]:
    return {"reconciled": 0, "pruned": 0}


def _summarize_task_audit_findings(findings: list[dict[str, object]]) -> dict[str, object]:
    summary = _empty_task_audit_summary()
    by_code = cast("dict[str, int]", summary["byCode"])
    for finding in findings:
        summary["total"] = cast("int", summary["total"]) + 1
        code = _optional_cli_string(finding.get("code"))
        if code in by_code:
            by_code[code] += 1
        if finding.get("severity") == "error":
            summary["errors"] = cast("int", summary["errors"]) + 1
        else:
            summary["warnings"] = cast("int", summary["warnings"]) + 1
    return summary


def _filter_task_audit_findings(
    findings: list[dict[str, object]],
    *,
    severity_filter: str | None,
    code_filter: str | None,
) -> list[dict[str, object]]:
    return [
        finding
        for finding in findings
        if (severity_filter is None or finding.get("severity") == severity_filter)
        and (code_filter is None or finding.get("code") == code_filter)
    ]


async def _build_tasks_audit_payload(
    services: CliServices,
    *,
    severity_filter: str | None,
    code_filter: str | None,
    limit: int | None,
) -> dict[str, object]:
    normalized_severity = _optional_cli_string(severity_filter)
    normalized_code = _optional_cli_string(code_filter)
    all_findings = _list_task_audit_findings(await _list_openclaw_background_tasks(services))
    filtered_findings = _filter_task_audit_findings(
        all_findings,
        severity_filter=normalized_severity,
        code_filter=normalized_code,
    )
    displayed = filtered_findings[:limit] if limit is not None else filtered_findings
    task_summary = _summarize_task_audit_findings(all_findings)
    task_flow_summary = _empty_task_flow_audit_summary()
    return {
        "count": len(all_findings),
        "filteredCount": len(filtered_findings),
        "displayed": len(displayed),
        "filters": {
            "severity": normalized_severity,
            "code": normalized_code,
            "limit": limit,
        },
        "summary": {
            **task_summary,
            "taskFlows": task_flow_summary,
            "combined": {
                "total": len(all_findings),
                "errors": task_summary["errors"],
                "warnings": task_summary["warnings"],
            },
        },
        "findings": displayed,
    }


def _task_maintenance_summary(findings: list[dict[str, object]]) -> dict[str, int]:
    return {
        "reconciled": sum(1 for finding in findings if finding.get("code") == "lost"),
        "recovered": 0,
        "cleanupStamped": sum(
            1 for finding in findings if finding.get("code") == "missing_cleanup"
        ),
        "pruned": 0,
    }


async def _build_tasks_maintenance_payload(
    services: CliServices,
    *,
    apply: bool,
) -> dict[str, object]:
    tasks = await _list_openclaw_background_tasks(services)
    findings = _list_task_audit_findings(tasks)
    task_audit_summary = _summarize_task_audit_findings(findings)
    flow_audit_summary = _empty_task_flow_audit_summary()
    audit_before = {**task_audit_summary, "taskFlows": flow_audit_summary}
    audit_after = dict(audit_before)
    return {
        "mode": "apply" if apply else "preview",
        "maintenance": {
            "tasks": _task_maintenance_summary(findings),
            "taskFlows": _empty_task_flow_maintenance_summary(),
        },
        "tasks": _summarize_openclaw_tasks(tasks),
        "auditBefore": audit_before,
        "auditAfter": audit_after,
    }


def _emit_tasks_maintenance(payload: dict[str, object], *, json_output: bool) -> None:
    if json_output:
        typer.echo(json.dumps(payload, indent=2))
        return
    mode = _optional_cli_string(payload.get("mode")) or "preview"
    maintenance = payload.get("maintenance")
    raw_tasks_maintenance = maintenance.get("tasks") if isinstance(maintenance, dict) else None
    tasks_maintenance = (
        cast("dict[str, object]", raw_tasks_maintenance)
        if isinstance(raw_tasks_maintenance, dict)
        else {}
    )
    raw_flow_maintenance = (
        maintenance.get("taskFlows") if isinstance(maintenance, dict) else None
    )
    flow_maintenance = (
        cast("dict[str, object]", raw_flow_maintenance)
        if isinstance(raw_flow_maintenance, dict)
        else {}
    )
    typer.echo(
        f"Tasks maintenance ({'applied' if mode == 'apply' else 'preview'}): "
        f"tasks {tasks_maintenance.get('reconciled', 0)} reconcile | "
        f"{tasks_maintenance.get('recovered', 0)} recovered | "
        f"{tasks_maintenance.get('cleanupStamped', 0)} cleanup stamp | "
        f"{tasks_maintenance.get('pruned', 0)} prune; "
        f"task-flows {flow_maintenance.get('reconciled', 0)} reconcile | "
        f"{flow_maintenance.get('pruned', 0)} prune"
    )
    audit_after = payload.get("auditAfter")
    errors = audit_after.get("errors") if isinstance(audit_after, dict) else 0
    warnings = audit_after.get("warnings") if isinstance(audit_after, dict) else 0
    task_summary = payload.get("tasks")
    queued = 0
    running = 0
    if isinstance(task_summary, dict):
        by_status = task_summary.get("byStatus")
        if isinstance(by_status, dict):
            queued = int(by_status.get("queued") or 0)
            running = int(by_status.get("running") or 0)
    typer.echo(
        f"Tasks health{' after apply' if mode == 'apply' else ''}: "
        f"{queued} queued | {running} running | {errors} audit errors | "
        f"{warnings} audit warnings"
    )
    if mode != "apply":
        typer.echo(
            "Dry run only. Re-run with `openzues tasks maintenance --apply` to write changes."
        )


def _openclaw_flow_status_from_blueprint(
    blueprint: object,
    linked_tasks: list[dict[str, object]],
) -> str:
    if not bool(_record_value(blueprint, "enabled", True)):
        return "cancelled"
    blueprint_status = str(_record_value(blueprint, "last_status", "") or "").strip().lower()
    if blueprint_status == "blocked":
        return "blocked"
    if blueprint_status == "failed":
        return "failed"
    if blueprint_status == "completed" and not linked_tasks:
        return "succeeded"
    linked_statuses = {_optional_cli_string(task.get("status")) for task in linked_tasks}
    if "running" in linked_statuses:
        return "running"
    if "queued" in linked_statuses:
        return "queued"
    if linked_statuses & {"failed", "timed_out"}:
        return "failed"
    if "lost" in linked_statuses:
        return "lost"
    if linked_tasks and linked_statuses <= {"succeeded"}:
        return "succeeded"
    if blueprint_status in {"active", "running"}:
        return "running"
    return "queued"


def _openclaw_flow_goal(blueprint: object) -> str:
    return (
        _optional_cli_string(_record_value(blueprint, "objective_template"))
        or _optional_cli_string(_record_value(blueprint, "summary"))
        or _optional_cli_string(_record_value(blueprint, "name"))
        or "OpenZues task blueprint"
    )


def _openclaw_flow_current_step(
    blueprint: object,
    linked_tasks: list[dict[str, object]],
) -> str | None:
    running_task = next(
        (
            task
            for task in linked_tasks
            if task.get("status") in {"running", "queued", "failed", "lost"}
        ),
        None,
    )
    if running_task is not None:
        label = (
            _optional_cli_string(running_task.get("label"))
            or _optional_cli_string(running_task.get("task"))
            or _optional_cli_string(running_task.get("taskId"))
        )
        status = _optional_cli_string(running_task.get("status"))
        if label is not None and status is not None:
            return f"{status}: {label}"
    if _record_value(blueprint, "last_launched_at") is not None:
        return "launched"
    return "scheduled"


def _openclaw_task_flow_record_from_blueprint(
    blueprint: object,
    linked_tasks: list[dict[str, object]],
) -> dict[str, object] | None:
    blueprint_id = _record_value(blueprint, "id")
    if not isinstance(blueprint_id, int):
        return None
    flow_id = f"task-blueprint:{blueprint_id}"
    created_ms = _task_timestamp_ms(_record_value(blueprint, "created_at")) or 0
    updated_ms = _task_timestamp_ms(_record_value(blueprint, "updated_at")) or created_ms
    status = _openclaw_flow_status_from_blueprint(blueprint, linked_tasks)
    flow: dict[str, object] = {
        "flowId": flow_id,
        "syncMode": "task_mirrored",
        "ownerKey": flow_id,
        "controllerId": "openzues.task_blueprint",
        "revision": 1,
        "status": status,
        "notifyPolicy": "done_only",
        "goal": _openclaw_flow_goal(blueprint),
        "createdAt": created_ms,
        "updatedAt": updated_ms,
    }
    current_step = _openclaw_flow_current_step(blueprint, linked_tasks)
    if current_step is not None:
        flow["currentStep"] = current_step
    blocked_task_id = _optional_cli_string(
        _record_value(blueprint, "blockedTaskId")
    ) or _optional_cli_string(_record_value(blueprint, "blocked_task_id"))
    if blocked_task_id is not None:
        flow["blockedTaskId"] = blocked_task_id
    wait_json = _record_value(blueprint, "waitJson")
    if wait_json is None:
        wait_json = _record_value(blueprint, "wait_json")
    if wait_json is not None:
        flow["waitJson"] = wait_json
    if status in {"succeeded", "failed", "cancelled", "lost"}:
        flow["endedAt"] = updated_ms
    return {
        **flow,
        "tasks": linked_tasks,
        "taskSummary": _summarize_openclaw_tasks(linked_tasks),
    }


async def _list_openclaw_task_flows(services: CliServices) -> list[dict[str, object]]:
    tasks = await _list_openclaw_background_tasks(services)
    flows: list[dict[str, object]] = []
    for blueprint in await _native_task_blueprint_records(services):
        blueprint_id = _record_value(blueprint, "id")
        if not isinstance(blueprint_id, int):
            continue
        flow_id = f"task-blueprint:{blueprint_id}"
        linked_tasks = [task for task in tasks if task.get("parentFlowId") == flow_id]
        flow = _openclaw_task_flow_record_from_blueprint(blueprint, linked_tasks)
        if flow is not None:
            flows.append(flow)
    return flows


async def _build_task_flows_list_payload(
    services: CliServices,
    *,
    status_filter: str | None,
) -> dict[str, object]:
    normalized_status = _optional_cli_string(status_filter)
    flows = [
        flow
        for flow in await _list_openclaw_task_flows(services)
        if normalized_status is None or flow.get("status") == normalized_status
    ]
    return {
        "count": len(flows),
        "status": normalized_status,
        "flows": flows,
    }


async def _resolve_openclaw_task_flow(
    services: CliServices,
    lookup: str,
) -> dict[str, object] | None:
    token = lookup.strip()
    for flow in await _list_openclaw_task_flows(services):
        if token in {
            _optional_cli_string(flow.get("flowId")),
            _optional_cli_string(flow.get("ownerKey")),
        }:
            return flow
    return None


def _task_blueprint_id_from_flow_id(flow_id: object) -> int | None:
    normalized = _optional_cli_string(flow_id)
    if normalized is None or not normalized.startswith("task-blueprint:"):
        return None
    try:
        return int(normalized.removeprefix("task-blueprint:"))
    except ValueError:
        return None


async def _cancel_openclaw_task_flow(services: CliServices, lookup: str) -> str:
    flow = await _resolve_openclaw_task_flow(services, lookup)
    if flow is None:
        raise ValueError(f"Flow not found: {lookup}")
    if flow.get("status") in {"succeeded", "failed", "cancelled", "lost"}:
        raise ValueError(f"Could not cancel TaskFlow: {lookup}")
    task_id = _task_blueprint_id_from_flow_id(flow.get("flowId"))
    update_task_blueprint = getattr(
        getattr(services, "database", None),
        "update_task_blueprint",
        None,
    )
    if task_id is None or not callable(update_task_blueprint):
        raise ValueError(f"Could not cancel TaskFlow: {lookup}")
    flow_id = str(flow.get("flowId") or lookup)
    await update_task_blueprint(
        task_id,
        enabled=0,
        last_status="cancelled",
        last_result_summary=f"TaskFlow {flow_id} cancelled via CLI.",
    )
    pause = getattr(getattr(services, "mission_service", None), "pause", None)
    linked_tasks = flow.get("tasks")
    if callable(pause) and isinstance(linked_tasks, list):
        for task in linked_tasks:
            if not isinstance(task, dict) or task.get("status") not in {"queued", "running"}:
                continue
            mission_id = _mission_id_from_task_record(cast("dict[str, object]", task))
            if mission_id is not None:
                await pause(mission_id)
    return f"Cancelled {flow_id} ({flow.get('syncMode')}) with status cancelled."


def _emit_task_flows_list(payload: dict[str, object], *, json_output: bool) -> None:
    if json_output:
        typer.echo(json.dumps(payload, indent=2))
        return
    raw_flows = payload.get("flows")
    flows = (
        [cast("dict[str, object]", item) for item in raw_flows if isinstance(item, dict)]
        if isinstance(raw_flows, list)
        else []
    )
    active = sum(1 for flow in flows if flow.get("status") in {"queued", "running"})
    blocked = sum(1 for flow in flows if flow.get("status") == "blocked")
    cancel_requested = sum(1 for flow in flows if flow.get("cancelRequestedAt") is not None)
    typer.echo(f"TaskFlows: {len(flows)}")
    typer.echo(
        "TaskFlow pressure: "
        f"{active} active | {blocked} blocked | "
        f"{cancel_requested} cancel-requested | {len(flows)} total"
    )
    status = _optional_cli_string(payload.get("status"))
    if status is not None:
        typer.echo(f"Status filter: {status}")
    if not flows:
        typer.echo("No TaskFlows found.")
        return
    typer.echo(
        " ".join(
            [
                "TaskFlow".ljust(16),
                "Mode".ljust(14),
                "Status".ljust(10),
                "Rev".ljust(6),
                "Controller".ljust(24),
                "Tasks".ljust(14),
                "Goal",
            ]
        )
    )
    for flow in flows:
        task_summary = flow.get("taskSummary")
        active_count = 0
        total_count = 0
        if isinstance(task_summary, dict):
            active_count = int(task_summary.get("active") or 0)
            total_count = int(task_summary.get("total") or 0)
        typer.echo(
            " ".join(
                [
                    str(flow.get("flowId") or "n/a")[:16].ljust(16),
                    str(flow.get("syncMode") or "n/a")[:14].ljust(14),
                    str(flow.get("status") or "n/a")[:10].ljust(10),
                    str(flow.get("revision") or "0")[:6].ljust(6),
                    str(flow.get("controllerId") or "n/a")[:24].ljust(24),
                    f"{active_count} active/{total_count} total".ljust(14),
                    str(flow.get("goal") or ""),
                ]
            ).rstrip()
        )


def _emit_task_flow_show(flow: dict[str, object], *, json_output: bool) -> None:
    if json_output:
        typer.echo(json.dumps(flow, indent=2))
        return
    typer.echo("TaskFlow:")
    typer.echo(f"flowId: {flow.get('flowId', 'n/a')}")
    typer.echo(f"status: {flow.get('status', 'n/a')}")
    typer.echo(f"goal: {flow.get('goal', 'n/a')}")
    typer.echo(f"currentStep: {flow.get('currentStep', 'n/a')}")
    typer.echo(f"owner: {flow.get('ownerKey', 'n/a')}")
    task_summary = flow.get("taskSummary")
    if isinstance(task_summary, dict):
        typer.echo(
            "tasks: "
            f"{task_summary.get('total', 0)} total | "
            f"{task_summary.get('active', 0)} active | "
            f"{task_summary.get('failures', 0)} issues"
        )
    raw_tasks = flow.get("tasks")
    tasks = (
        [cast("dict[str, object]", item) for item in raw_tasks if isinstance(item, dict)]
        if isinstance(raw_tasks, list)
        else []
    )
    if not tasks:
        typer.echo("Linked tasks: none")
        return
    typer.echo("Linked tasks:")
    for task in tasks:
        typer.echo(
            f"- {task.get('taskId', 'n/a')} {task.get('status', 'n/a')} "
            f"{task.get('runId', 'n/a')} {task.get('label', task.get('task', ''))}"
        )


def _emit_tasks_audit(payload: dict[str, object], *, json_output: bool) -> None:
    if json_output:
        typer.echo(json.dumps(payload, indent=2))
        return
    summary = payload.get("summary")
    combined = summary.get("combined") if isinstance(summary, dict) else None
    if not isinstance(combined, dict):
        combined = {"total": payload.get("count", 0), "errors": 0, "warnings": 0}
    typer.echo(
        "Tasks audit: "
        f"{combined.get('total', 0)} findings | "
        f"{combined.get('errors', 0)} errors | "
        f"{combined.get('warnings', 0)} warnings"
    )
    filters = payload.get("filters")
    if isinstance(filters, dict):
        severity = _optional_cli_string(filters.get("severity"))
        code = _optional_cli_string(filters.get("code"))
        limit = filters.get("limit")
        if severity is not None:
            typer.echo(f"Severity filter: {severity}")
        if code is not None:
            typer.echo(f"Code filter: {code}")
        if isinstance(limit, int):
            typer.echo(f"Limit: {limit}")
    raw_findings = payload.get("findings")
    findings = (
        [cast("dict[str, object]", item) for item in raw_findings if isinstance(item, dict)]
        if isinstance(raw_findings, list)
        else []
    )
    if not findings:
        typer.echo("No tasks audit findings.")
        return
    typer.echo("Scope    Severity Code                   Item       Status     Age      Detail")
    for finding in findings:
        age = finding.get("ageMs")
        age_text = f"{int(age / 1000)}s" if isinstance(age, int) else "fresh"
        typer.echo(
            " ".join(
                [
                    str(finding.get("kind") or "task").ljust(8),
                    str(finding.get("severity") or "n/a").ljust(8),
                    str(finding.get("code") or "n/a")[:22].ljust(22),
                    str(finding.get("token") or "n/a")[:10].ljust(10),
                    str(finding.get("status") or "n/a")[:10].ljust(10),
                    age_text[:8].ljust(8),
                    str(finding.get("detail") or ""),
                ]
            ).rstrip()
        )


def _emit_tasks_list(payload: dict[str, object], *, json_output: bool) -> None:
    if json_output:
        typer.echo(json.dumps(payload, indent=2))
        return
    raw_tasks = payload.get("tasks")
    tasks = [
        cast("dict[str, object]", task)
        for task in raw_tasks
        if isinstance(task, dict)
    ] if isinstance(raw_tasks, list) else []
    counts = _task_status_counts(tasks)
    typer.echo(f"Background tasks: {len(tasks)}")
    typer.echo(
        "Task pressure: "
        f"{counts['queued']} queued | {counts['running']} running | "
        f"{_task_failure_count(tasks)} issues"
    )
    runtime_filter = _optional_cli_string(payload.get("runtime"))
    if runtime_filter is not None:
        typer.echo(f"Runtime filter: {runtime_filter}")
    status_filter = _optional_cli_string(payload.get("status"))
    if status_filter is not None:
        typer.echo(f"Status filter: {status_filter}")
    if not tasks:
        typer.echo("No background tasks found.")
        return
    typer.echo(
        " ".join(
            [
                "Task".ljust(14),
                "Kind".ljust(8),
                "Status".ljust(10),
                "Delivery".ljust(14),
                "Run".ljust(12),
                "Child Session".ljust(30),
                "Summary",
            ]
        )
    )
    for task in tasks:
        label = (
            _optional_cli_string(task.get("terminalSummary"))
            or _optional_cli_string(task.get("progressSummary"))
            or _optional_cli_string(task.get("label"))
            or _optional_cli_string(task.get("task"))
            or ""
        )
        typer.echo(
            " ".join(
                [
                    str(task.get("taskId") or "n/a")[:14].ljust(14),
                    str(task.get("runtime") or "n/a")[:8].ljust(8),
                    str(task.get("status") or "n/a")[:10].ljust(10),
                    str(task.get("deliveryStatus") or "n/a")[:14].ljust(14),
                    str(task.get("runId") or "n/a")[:12].ljust(12),
                    str(task.get("childSessionKey") or "n/a")[:30].ljust(30),
                    label[:80],
                ]
            ).rstrip()
        )


def _emit_task_show(task: dict[str, object], *, json_output: bool) -> None:
    if json_output:
        typer.echo(json.dumps(task, indent=2))
