        ("deliveryStatus", "delivery"),
        ("notifyPolicy", "notify"),
        ("ownerKey", "ownerKey"),
        ("childSessionKey", "childSessionKey"),
        ("parentTaskId", "parentTaskId"),
        ("agentId", "agentId"),
        ("runId", "runId"),
        ("label", "label"),
        ("task", "task"),
        ("createdAt", "createdAt"),
        ("startedAt", "startedAt"),
        ("endedAt", "endedAt"),
        ("lastEventAt", "lastEventAt"),
