@sessions_app.callback(invoke_without_command=True)
def sessions_inventory_command(
    ctx: typer.Context,
    json_output: bool = typer.Option(False, "--json", help="Output as JSON."),
    agent: str | None = typer.Option(None, "--agent", help="Agent id to inspect."),
    all_agents: bool = typer.Option(
        False,
        "--all-agents",
        help="Aggregate sessions across configured agents.",
    ),
    active: str | None = typer.Option(
        None,
        "--active",
        help="Only show sessions updated within the past N minutes.",
    ),
    store: str | None = typer.Option(
        None,
        "--store",
        help="OpenClaw-compatible option; native OpenZues uses the gateway session store.",
    ),
) -> None:
    if ctx.invoked_subcommand is not None:
        return
    if _optional_cli_string(store) is not None:
        raise typer.BadParameter("--store is not supported by the native OpenZues session store")
    params: dict[str, object] = {}
    normalized_agent = _optional_cli_string(agent)
    if normalized_agent is not None:
        params["agentId"] = normalized_agent
    active_minutes = _sessions_cli_positive_int(active, option="--active")
    if active_minutes is not None:
        params["activeMinutes"] = active_minutes
    if all_agents:
        params["includeGlobal"] = True

    async def _action(services: CliServices) -> dict[str, object]:
        return await _call_gateway_node_method(services, "sessions.list", params)

    result = _run(_run_with_services(_action))
    _emit_sessions_inventory(result, json_output=json_output)


@sessions_app.command("cleanup")
def sessions_cleanup_command(
    ctx: typer.Context,
    store: str | None = typer.Option(
        None,
        "--store",
        help="OpenClaw-compatible option; native OpenZues uses the gateway session store.",
    ),
    agent: str | None = typer.Option(None, "--agent", help="Agent id to maintain."),
    all_agents: bool = typer.Option(
        False,
        "--all-agents",
        help="Preview maintenance across all native gateway sessions.",
    ),
    dry_run: bool = typer.Option(False, "--dry-run", help="Preview maintenance actions."),
    enforce: bool = typer.Option(False, "--enforce", help="Preview enforce-mode maintenance."),
    fix_missing: bool = typer.Option(
        False,
        "--fix-missing",
        help="OpenClaw-compatible flag; dry-run reports native transcript posture.",
    ),
    active_key: str | None = typer.Option(
        None,
        "--active-key",
        help="Protect this session key from budget eviction.",
    ),
    json_output: bool = typer.Option(False, "--json", help="Emit cleanup summary as JSON."),
) -> None:
    parent_params = ctx.parent.params if ctx.parent is not None else {}
    parent_store = _optional_cli_string(parent_params.get("store"))
    normalized_store = _optional_cli_string(store) or parent_store
    if normalized_store is not None:
        raise typer.BadParameter("--store is not supported by the native OpenZues session store")
    normalized_agent = _optional_cli_string(agent) or _optional_cli_string(
        parent_params.get("agent")
    )
    include_all_agents = all_agents or bool(parent_params.get("all_agents"))
    json_output = json_output or bool(parent_params.get("json_output"))
    mode = "enforce" if enforce else "warn"
    params: dict[str, object] = {}
    if normalized_agent is not None:
        params["agentId"] = normalized_agent
    if include_all_agents:
        params["includeGlobal"] = True

    async def _action(services: CliServices) -> dict[str, object]:
        inventory = await _call_gateway_node_method(services, "sessions.list", params)
        missing_keys = (
            await _sessions_cleanup_missing_metadata_keys(
                services,
                agent_id=None if include_all_agents else normalized_agent,
            )
            if fix_missing
            else []
        )
        if fix_missing and not dry_run:
            await _sessions_cleanup_delete_metadata_keys(services, missing_keys)
        if include_all_agents and json_output:
            summary: dict[str, object] = {
                "allAgents": True,
                "mode": mode,
                "dryRun": dry_run,
                "stores": _sessions_cleanup_grouped_summaries(
                    inventory,
                    services=services,
                    mode=mode,
                    dry_run=dry_run,
                    missing_keys=missing_keys,
                    active_key=active_key,
                ),
            }
        else:
            summary = _sessions_cleanup_summary(
                inventory,
                services=services,
                agent_id=normalized_agent,
                mode=mode,
                dry_run=dry_run,
                missing_keys=missing_keys,
                active_key=active_key,
            )
        if not dry_run and mode == "enforce":
            raw_sessions = inventory.get("sessions")
            sessions = raw_sessions if isinstance(raw_sessions, list) else []
            cleanup_plan = _sessions_cleanup_planned_keys(
                sessions,
                missing_keys=missing_keys,
                services=services,
                active_key=active_key,
            )
            await _sessions_cleanup_delete_metadata_keys(
                services,
                [
                    *cast(list[str], cleanup_plan["stale"]),
                    *cast(list[str], cleanup_plan["capped"]),
                    *cast(list[str], cleanup_plan["disk"]),
                ],
            )
        return summary

    result = _run(_run_with_services(_action))
    _emit_sessions_cleanup(result, json_output=json_output)


@sessions_app.command("spawn")
def sessions_spawn_command(
    task: str = typer.Option(..., "--task", "-t", help="Task to hand to the spawned session."),
    label: str | None = typer.Option(None, "--label", help="Optional child session label."),
    runtime: str | None = typer.Option(
        None,
        "--runtime",
        help="Spawn runtime: subagent or acp.",
    ),
    agent_id: str | None = typer.Option(None, "--agent-id", help="Target agent id."),
    cwd: str | None = typer.Option(None, "--cwd", help="Workspace directory for the child turn."),
    resume_session_id: str | None = typer.Option(
        None,
        "--resume-session-id",
        help="ACP runtime session/thread id to resume.",
    ),
    stream_to: str | None = typer.Option(
        None,
        "--stream-to",
        help='ACP stream target, currently "parent".',
    ),
    mode: str | None = typer.Option(None, "--mode", help="Spawn mode: run or session."),
    thread: bool = typer.Option(
        False,
        "--thread",
        help="Create a persistent child thread when a provider binder is available.",
    ),
    sandbox: str | None = typer.Option(
        None,
        "--sandbox",
        help="Sandbox posture: inherit or require.",
    ),
    run_timeout_seconds: int | None = typer.Option(
        None,
        "--run-timeout-seconds",
        min=0,
        help="Run timeout in seconds.",
    ),
    cleanup: str | None = typer.Option(
        None,
        "--cleanup",
        help="Cleanup mode: delete or keep.",
    ),
    expects_completion_message: bool | None = typer.Option(
        None,
        "--expects-completion-message/--no-expects-completion-message",
        help="Whether terminal waits announce completion to the parent session.",
    ),
    requester_session_key: str | None = typer.Option(
        None,
        "--requester-session-key",
        help="Parent/requester session key for spawn tracking.",
    ),
    json_output: bool = typer.Option(False, "--json", help="Emit the spawn result as JSON."),
) -> None:
    params: dict[str, object] = {"task": task}
    for key, value in (
        ("label", label),
        ("runtime", runtime),
        ("agentId", agent_id),
        ("cwd", cwd),
        ("resumeSessionId", resume_session_id),
        ("streamTo", stream_to),
        ("mode", mode),
        ("sandbox", sandbox),
        ("cleanup", cleanup),
        ("requesterSessionKey", requester_session_key),
    ):
        normalized = _optional_cli_string(value)
        if normalized is not None:
            params[key] = normalized
    if thread:
        params["thread"] = True
    if run_timeout_seconds is not None:
        params["runTimeoutSeconds"] = run_timeout_seconds
    if expects_completion_message is not None:
        params["expectsCompletionMessage"] = expects_completion_message

    async def _action(services: CliServices) -> dict[str, object]:
        return await _call_gateway_node_method(services, "sessions.spawn", params)

    result = _run(_run_with_services(_action))
    _emit_session_method_result(result, json_output=json_output)


